/* 秘伝の書のデータ（Notion のメモから作成。build/notion2hiden.py で作り直せます） */
const HIDEN = [{"id": "html-01", "page": "HTML・CSS まとめ", "cat": "html", "ch": 1, "title": "まず全体像をつかもう", "summary": "Webページは「家」にたとえるとわかりやすいです。", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<p>Webページは「家」にたとえるとわかりやすいです。</p><div class=\"tbl\"><table><tr><th>役割</th><th>家でいうと</th><th>何をするもの?</th></tr><tr><td>🧱 <b>HTML</b></td><td>骨組み・部屋・家具</td><td>ページに「何があるか」を決める</td></tr><tr><td>🎨 <b>CSS</b></td><td>壁紙・色・家具の配置</td><td>「どう見えるか」を決める</td></tr><tr><td>⚡ <b>JavaScript</b></td><td>電気・自動ドア</td><td>「動き」をつける(→ JavaScriptまとめ へ)</td></tr></table></div><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>HTML = 中身、CSS = 見た目、JavaScript = 動き</b>。まずはこれだけ覚えればOK。</p></div></div>"}, {"id": "html-02", "page": "HTML・CSS まとめ", "cat": "html", "ch": 2, "title": "HTMLの基本", "summary": "HTMLは、文章に「ここは見出し」「ここは段落」と ラベルを貼る ためのもの。このラベルを タグ といいます。", "snippet": "<p>こんにちは</p>", "date": "2026-10-16", "min": 6, "html": "<p>HTMLは、文章に「ここは見出し」「ここは段落」と<b>ラベルを貼る</b>ためのもの。このラベルを<b>タグ</b>といいます。</p><h4>タグの書き方</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;p&gt;こんにちは&lt;/p&gt;</code></pre></div><ul><li><code>&lt;p&gt;</code> … 開始タグ(ここから段落だよ)</li><li><code>こんにちは</code> … 中身</li><li><code>&lt;/p&gt;</code> … 終了タグ(ここまで。<code>/</code> がつく)</li></ul><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>ルール:はさんで使う。始まりと終わりをセットにする。</b>(<code>&lt;img&gt;</code> <code>&lt;br&gt;</code> <code>&lt;input&gt;</code> など、閉じタグがないものも一部ある)</p></div></div><h4>最小のHTMLファイル(毎回これをコピーしてスタート)</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;ja&quot;&gt;\n&lt;head&gt;\n  &lt;meta charset=&quot;UTF-8&quot;&gt;\n  &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;\n  &lt;title&gt;ページのタイトル&lt;/title&gt;\n  &lt;link rel=&quot;stylesheet&quot; href=&quot;style.css&quot;&gt;\n  &lt;script src=&quot;main.js&quot; defer&gt;&lt;/script&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;h1&gt;ここが見出し&lt;/h1&gt;\n  &lt;p&gt;ここが本文&lt;/p&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre></div><div class=\"tbl\"><table><tr><th>部分</th><th>意味</th></tr><tr><td><code>&lt;!DOCTYPE html&gt;</code></td><td>「これはHTMLですよ」という宣言。毎回書く</td></tr><tr><td><code>&lt;html lang=\"ja\"&gt;</code></td><td>ページ全体。日本語ページという意味</td></tr><tr><td><code>&lt;head&gt;</code></td><td>画面には出ない設定部屋(タイトルなど)</td></tr><tr><td><code>&lt;meta charset=\"UTF-8\"&gt;</code></td><td>文字化け防止</td></tr><tr><td><code>&lt;meta name=\"viewport\" …&gt;</code></td><td>スマホで正しく表示させる(レスポンシブに必須)</td></tr><tr><td><code>&lt;title&gt;</code></td><td>ブラウザのタブに出る名前</td></tr><tr><td><code>&lt;link rel=\"stylesheet\" …&gt;</code></td><td>CSSファイルを読み込む</td></tr><tr><td>✨ <code>&lt;script src=\"…\" defer&gt;</code></td><td>JSファイルを読み込む。<code>defer</code> で「HTMLを読み終わってから実行」になる</td></tr><tr><td><code>&lt;body&gt;</code></td><td><b>画面に表示される部分はぜんぶここ</b></td></tr></table></div><h4>よく使うタグ</h4><div class=\"tbl\"><table><tr><th>タグ</th><th>意味</th><th>例</th></tr><tr><td><code>&lt;h1&gt;</code>〜<code>&lt;h6&gt;</code></td><td>見出し(h1が一番大きい。h1はページに1つが目安)</td><td><code>&lt;h1&gt;タイトル&lt;/h1&gt;</code></td></tr><tr><td><code>&lt;p&gt;</code></td><td>段落</td><td><code>&lt;p&gt;文章&lt;/p&gt;</code></td></tr><tr><td><code>&lt;a&gt;</code></td><td>リンク</td><td><code>&lt;a href=\"https://example.com\"&gt;クリック&lt;/a&gt;</code></td></tr><tr><td><code>&lt;img&gt;</code></td><td>画像</td><td><code>&lt;img src=\"cat.jpg\" alt=\"ねこ\"&gt;</code></td></tr><tr><td><code>&lt;ul&gt;</code> <code>&lt;li&gt;</code></td><td>箇条書き(番号付きは <code>&lt;ol&gt;</code>)</td><td>下に例</td></tr><tr><td><code>&lt;div&gt;</code></td><td>区切り用の箱(中身に意味はない)</td><td><code>&lt;div&gt;…&lt;/div&gt;</code></td></tr><tr><td><code>&lt;span&gt;</code></td><td>文章の一部だけを囲む箱</td><td><code>&lt;span&gt;赤い字&lt;/span&gt;</code></td></tr><tr><td><code>&lt;br /&gt;</code></td><td>改行</td><td><code>&lt;br /&gt;</code></td></tr><tr><td>✨ <code>&lt;button&gt;</code></td><td>ボタン(JSで動かすときに使う)</td><td><code>&lt;button&gt;送信&lt;/button&gt;</code></td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;ul&gt;\n  &lt;li&gt;りんご&lt;/li&gt;\n  &lt;li&gt;みかん&lt;/li&gt;\n&lt;/ul&gt;</code></pre></div><h4>✨ 意味のある箱(セマンティックタグ)</h4><p><code>&lt;div&gt;</code> の代わりに使うと、「ここはヘッダー」「ここはメニュー」と意味が伝わり、検索エンジンや読み上げソフトにも優しくなります。実務のコーディングではほぼ必ず使います。</p><div class=\"tbl\"><table><tr><th>タグ</th><th>使う場所</th></tr><tr><td><code>&lt;header&gt;</code></td><td>ページ上部(ロゴ・メニューなど)</td></tr><tr><td><code>&lt;nav&gt;</code></td><td>ナビゲーション(メニューのリンク集)</td></tr><tr><td><code>&lt;main&gt;</code></td><td>ページのメインの内容(1ページに1つ)</td></tr><tr><td><code>&lt;section&gt;</code></td><td>見出しのあるひとまとまり(「サービス紹介」など)</td></tr><tr><td><code>&lt;article&gt;</code></td><td>それだけで完結する記事(ブログ記事・ニュースなど)</td></tr><tr><td><code>&lt;footer&gt;</code></td><td>ページ下部(コピーライトなど)</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;body&gt;\n  &lt;header&gt;\n    &lt;h1&gt;サイト名&lt;/h1&gt;\n    &lt;nav&gt;\n      &lt;ul&gt;\n        &lt;li&gt;&lt;a href=&quot;#about&quot;&gt;私たちについて&lt;/a&gt;&lt;/li&gt;\n        &lt;li&gt;&lt;a href=&quot;#contact&quot;&gt;お問い合わせ&lt;/a&gt;&lt;/li&gt;\n      &lt;/ul&gt;\n    &lt;/nav&gt;\n  &lt;/header&gt;\n  &lt;main&gt;\n    &lt;section id=&quot;about&quot;&gt;\n      &lt;h2&gt;私たちについて&lt;/h2&gt;\n      &lt;p&gt;説明文&lt;/p&gt;\n    &lt;/section&gt;\n  &lt;/main&gt;\n  &lt;footer&gt;\n    &lt;p&gt;&amp;copy; 2026 サイト名&lt;/p&gt;\n  &lt;/footer&gt;\n&lt;/body&gt;</code></pre></div><h4>属性(ぞくせい)</h4><p>タグに<b>追加の情報</b>をつけるもの。<code>名前=\"値\"</code> の形で、開始タグの中に書きます。</p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;a href=&quot;https://example.com&quot;&gt;リンク&lt;/a&gt;\n&lt;img src=&quot;cat.jpg&quot; alt=&quot;ねこの写真&quot;&gt;</code></pre></div><ul><li><code>href</code> … リンク先(<code>#about</code> と書くと、同じページの <code>id=\"about\"</code> の場所に飛ぶ)</li><li><code>src</code> … 画像のある場所</li><li><code>alt</code> … 画像が表示できないときの代わりの説明</li><li><code>class</code> / <code>id</code> … CSSやJSで「この部品」と指定するための名前</li><li>✨ <code>target=\"_blank\"</code> … リンクを新しいタブで開く</li></ul><h4>タグは「入れ子」にできる</h4><p>箱の中に箱を入れるイメージ。<b>閉じる順番は、開けた順番の逆</b>。</p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;div&gt;\n  &lt;h2&gt;見出し&lt;/h2&gt;\n  &lt;p&gt;文章&lt;/p&gt;\n&lt;/div&gt;</code></pre></div><h4>✨ フォーム(お問い合わせ欄など)</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;form&gt;\n  &lt;label for=&quot;name&quot;&gt;お名前&lt;/label&gt;\n  &lt;input type=&quot;text&quot; id=&quot;name&quot; name=&quot;name&quot; placeholder=&quot;山田太郎&quot; required&gt;\n\n  &lt;label for=&quot;email&quot;&gt;メールアドレス&lt;/label&gt;\n  &lt;input type=&quot;email&quot; id=&quot;email&quot; name=&quot;email&quot;&gt;\n\n  &lt;label for=&quot;msg&quot;&gt;内容&lt;/label&gt;\n  &lt;textarea id=&quot;msg&quot; name=&quot;msg&quot; rows=&quot;5&quot;&gt;&lt;/textarea&gt;\n\n  &lt;button type=&quot;submit&quot;&gt;送信する&lt;/button&gt;\n&lt;/form&gt;</code></pre></div><div class=\"tbl\"><table><tr><th>部品</th><th>意味</th></tr><tr><td><code>&lt;input type=\"text\"&gt;</code></td><td>1行の文字入力</td></tr><tr><td><code>type=\"email\"</code> / <code>type=\"tel\"</code> / <code>type=\"password\"</code></td><td>メール / 電話番号 / パスワード用(スマホで合ったキーボードが出る)</td></tr><tr><td><code>type=\"checkbox\"</code> / <code>type=\"radio\"</code></td><td>チェックボックス(複数選べる)/ ラジオボタン(1つだけ)</td></tr><tr><td><code>&lt;textarea&gt;</code></td><td>複数行の文字入力</td></tr><tr><td><code>&lt;select&gt;</code> <code>&lt;option&gt;</code></td><td>プルダウン</td></tr><tr><td><code>&lt;label for=\"…\"&gt;</code></td><td>入力欄の名前。<code>for</code> と input の <code>id</code> をそろえると、文字をクリックしても入力欄が選ばれる</td></tr><tr><td><code>required</code></td><td>入力必須にする</td></tr></table></div>"}, {"id": "html-03", "page": "HTML・CSS まとめ", "cat": "css", "ch": 3, "title": "CSSの基本", "summary": "CSSは、HTMLの部品に 色・大きさ・並び方をつける もの。", "snippet": "セレクタ {", "date": "2026-10-16", "min": 2, "html": "<p>CSSは、HTMLの部品に<b>色・大きさ・並び方をつける</b>もの。</p><h4>書き方(基本の型)</h4><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>セレクタ {\n  プロパティ: 値;\n}</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>p {\n  color: red;\n  font-size: 20px;\n}</code></pre></div><div class=\"tbl\"><table><tr><th>用語</th><th>意味</th><th>上の例では</th></tr><tr><td>セレクタ</td><td><b>どの部品に</b>適用するか</td><td><code>p</code>(すべての段落)</td></tr><tr><td>プロパティ</td><td><b>何を</b>変えるか</td><td><code>color</code>(文字色)</td></tr><tr><td>値</td><td><b>どう</b>変えるか</td><td><code>red</code>(赤)</td></tr></table></div><p><b>読み方:「すべての段落の、文字色を赤に、文字の大きさを20pxにしてね」</b></p><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>よくある事故:行の最後の </b><b><code>;</code></b><b>(セミコロン)を忘れる。</b> その行だけでなく、次の行まで効かなくなることがあります。</p></div></div><h4>HTMLにCSSをつなげる</h4><p><code>&lt;head&gt;</code> の中に1行書きます(最小のHTMLファイルにすでに入っています)。</p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;link rel=&quot;stylesheet&quot; href=&quot;style.css&quot;&gt;</code></pre></div><h4>セレクタ:「どれに」効かせるか</h4><p>同じ <code>&lt;p&gt;</code> が10個あっても、1つだけ色を変えたいときは<b>クラス(名前)をつけます</b>。</p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;p class=&quot;warning&quot;&gt;注意してください&lt;/p&gt;\n&lt;p&gt;ふつうの文章&lt;/p&gt;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.warning {\n  color: red;\n}</code></pre></div><p>→ <code>warning</code> と名前をつけた段落だけが赤くなります。</p><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th><th>例</th></tr><tr><td><code>p</code></td><td>タグ名で指定(全部)</td><td><code>p { … }</code></td></tr><tr><td><code>.名前</code></td><td>クラスで指定(<b>一番よく使う</b>)</td><td><code>.warning { … }</code></td></tr><tr><td><code>#名前</code></td><td>idで指定(ページに1つだけのもの)</td><td><code>#header { … }</code></td></tr><tr><td><code>.a .b</code></td><td>aの<b>中にある</b>b</td><td><code>.menu li { … }</code></td></tr><tr><td>✨ <code>.a, .b</code></td><td>aとbの両方に同じ指定</td><td><code>h1, h2 { … }</code></td></tr><tr><td>✨ <code>.a:hover</code></td><td>マウスを乗せたとき</td><td><code>.btn:hover { … }</code></td></tr><tr><td>✨ <code>li:first-child</code> / <code>li:last-child</code></td><td>最初の / 最後の要素だけ</td><td><code>li:last-child { … }</code></td></tr><tr><td>✨ <code>li:nth-child(2)</code></td><td>2番目だけ(<code>odd</code> / <code>even</code> で奇数・偶数)</td><td><code>tr:nth-child(even) { … }</code></td></tr></table></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p>迷ったら <b>クラス(</b><b><code>.</code></b><b>)を使う</b> でOK。idはCSSではなるべく使わず、JSやページ内リンク用にとっておくのが実務の定番です。</p></div></div><h4>✨ 同じ部品に2つのCSSが当たったら、どっちが勝つ?</h4><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ol><li><b>より詳しい指定が勝つ</b>:id(<code>#</code>) &gt; クラス(<code>.</code>) &gt; タグ名</li><li><b>同じ強さなら、後に書いたほうが勝つ</b></li><li><code>!important</code> を付けると最強になるが、あとで直せなくなるので<b>基本は使わない</b></li></ol><p>「CSSが効かない」ときは、検証ツールで<b>線が引かれて消されている指定</b>を探すと、どれに負けているか分かります。</p></div></div>"}, {"id": "html-04", "page": "HTML・CSS まとめ", "cat": "css", "ch": 4, "title": "よく使うCSSプロパティ", "summary": "文字まわり プロパティ 意味 例 color 文字の色 color: #333; font-size 文字の大きさ font-size: 16px; font-weight 太さ font-weight: bold; (数字なら 700 )", "snippet": "", "date": "2026-10-16", "min": 3, "html": "<h4>文字まわり</h4><div class=\"tbl\"><table><tr><th>プロパティ</th><th>意味</th><th>例</th></tr><tr><td><code>color</code></td><td>文字の色</td><td><code>color: #333;</code></td></tr><tr><td><code>font-size</code></td><td>文字の大きさ</td><td><code>font-size: 16px;</code></td></tr><tr><td><code>font-weight</code></td><td>太さ</td><td><code>font-weight: bold;</code>(数字なら <code>700</code>)</td></tr><tr><td><code>font-family</code></td><td>フォントの種類</td><td><code>font-family: sans-serif;</code></td></tr><tr><td><code>text-align</code></td><td>文字の寄せ方</td><td><code>text-align: center;</code></td></tr><tr><td><code>line-height</code></td><td>行の高さ</td><td><code>line-height: 1.6;</code></td></tr><tr><td>✨ <code>letter-spacing</code></td><td>文字の間隔</td><td><code>letter-spacing: 0.05em;</code></td></tr><tr><td>✨ <code>text-decoration</code></td><td>下線など</td><td><code>text-decoration: none;</code>(リンクの下線を消す)</td></tr></table></div><h4>箱まわり(超重要)</h4><div class=\"tbl\"><table><tr><th>プロパティ</th><th>意味</th><th>例</th></tr><tr><td><code>width</code> / <code>height</code></td><td>横幅 / 高さ</td><td><code>width: 300px;</code></td></tr><tr><td>✨ <code>max-width</code></td><td>最大の横幅(これ以上広がらない)</td><td><code>max-width: 1200px;</code></td></tr><tr><td><code>background-color</code></td><td>背景色</td><td><code>background-color: #eee;</code></td></tr><tr><td>✨ <code>background-image</code></td><td>背景画像</td><td><code>background-image: url(\"bg.jpg\");</code></td></tr><tr><td><code>border</code></td><td>枠線(太さ・種類・色)</td><td><code>border: 1px solid #000;</code></td></tr><tr><td><code>border-radius</code></td><td>角を丸くする</td><td><code>border-radius: 8px;</code></td></tr><tr><td><code>padding</code></td><td>枠線の<b>内側</b>の余白</td><td><code>padding: 20px;</code></td></tr><tr><td><code>margin</code></td><td>枠線の<b>外側</b>の余白</td><td><code>margin: 20px;</code></td></tr><tr><td>✨ <code>box-shadow</code></td><td>影</td><td><code>box-shadow: 0 2px 8px rgba(0,0,0,0.1);</code></td></tr></table></div><h4>色の指定方法</h4><ul><li>名前:<code>red</code> <code>blue</code> <code>white</code></li><li>16進数:<code>#ff0000</code>(赤)、<code>#ffffff</code>(白)、<code>#000000</code>(黒)… Figmaからコピーしたコードはこの形が多い</li><li>✨ <code>rgba(0, 0, 0, 0.5)</code>:最後の数字が<b>透明度</b>(0=透明 〜 1=不透明)。影や半透明の背景に便利</li></ul><h4>✨ 単位の使い分け</h4><div class=\"tbl\"><table><tr><th>単位</th><th>意味</th><th>よく使う場面</th></tr><tr><td><code>px</code></td><td>画面の点の数(固定)</td><td>枠線、細かい余白</td></tr><tr><td><code>%</code></td><td>親の箱に対する割合</td><td>横幅(<code>width: 50%;</code>)</td></tr><tr><td><code>rem</code></td><td>基本の文字サイズ(ふつう16px)の何倍か</td><td>文字サイズ(<code>1.5rem</code> = 24px)</td></tr><tr><td><code>em</code></td><td>その要素の文字サイズの何倍か</td><td>文字間隔など</td></tr><tr><td><code>vw</code> / <code>vh</code></td><td>画面の幅 / 高さの何%か</td><td>画面いっぱいのメイン画像(<code>height: 100vh;</code>)</td></tr></table></div><h4>✨ display:箱の並び方の種類</h4><div class=\"tbl\"><table><tr><th>値</th><th>並び方</th><th>代表的なタグ</th></tr><tr><td><code>block</code></td><td>縦に積み重なる。横幅いっぱいに広がる。幅・高さ・余白が効く</td><td><code>div</code> <code>p</code> <code>h1</code> <code>section</code></td></tr><tr><td><code>inline</code></td><td>文章の中で横に流れる。<b>幅・高さ・上下の余白が効かない</b></td><td><code>a</code> <code>span</code></td></tr><tr><td><code>inline-block</code></td><td>横に流れるけど、幅・高さ・余白が効く</td><td>ボタン風のリンクに使う</td></tr><tr><td><code>flex</code> / <code>grid</code></td><td>中の子を並べる(次の章)</td><td>—</td></tr><tr><td><code>none</code></td><td>表示しない(消える)</td><td>メニューを隠すとき</td></tr></table></div>"}, {"id": "html-05", "page": "HTML・CSS まとめ", "cat": "css", "ch": 5, "title": "ボックスモデル:CSSで一番大事な考え方", "summary": "HTMLの部品は、 すべて四角い箱 。箱は4つの層でできています。", "snippet": "margin: 10px;                /* 上下左右ぜんぶ10px */", "date": "2026-10-16", "min": 2, "html": "<p>HTMLの部品は、<b>すべて四角い箱</b>。箱は4つの層でできています。</p><p><b>たとえ話:ギフトの箱</b> … content=プレゼント、padding=緩衝材、border=箱そのもの、margin=隣の箱との距離</p><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><b>paddingとmarginの違い(最初につまずくところ)</b></p><ul><li><code>padding</code> … <b>箱の中</b>の余白(背景色がつく)</li><li><code>margin</code> … <b>箱の外</b>の余白(背景色がつかない)</li></ul></div></div><h4>余白の書き方</h4><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>margin: 10px;                /* 上下左右ぜんぶ10px */\nmargin: 10px 20px;           /* 上下10px、左右20px */\nmargin: 10px 20px 30px 40px; /* 上、右、下、左(時計回り) */\nmargin: 0 auto;              /* 上下0、左右は自動 → 箱が真ん中に寄る(widthが必要) */</code></pre></div><h4>box-sizing</h4><p>ふつうは <code>padding</code> や <code>border</code> を足すと、箱が<b>大きくなってしまいます</b>。これを防ぐ定番の1行:</p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>* {\n  box-sizing: border-box;\n}</code></pre></div><p>→ 「<code>width: 300px</code> と書いたら、余白や枠線を含めて300pxにする」という設定。</p><h4>✨ 最初に書いておく定番CSS(コピペ用)</h4><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p>ブラウザごとの見た目の差をなくし、よくあるトラブルを先に防ぐセットです。<code>style.css</code> の一番上に置きましょう。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: sans-serif;\n  line-height: 1.6;\n  color: #333;\n}\n\nimg {\n  max-width: 100%;   /* 画像がはみ出さない */\n  height: auto;\n  vertical-align: bottom; /* 画像の下にできる謎のすき間を消す */\n}\n\nul {\n  list-style: none;  /* 箇条書きの点を消す(メニュー用) */\n  padding: 0;\n  margin: 0;\n}\n\na {\n  color: inherit;          /* 親の文字色を使う */\n  text-decoration: none;   /* 下線を消す */\n}</code></pre></div>"}, {"id": "html-06", "page": "HTML・CSS まとめ", "cat": "css", "ch": 6, "title": "並べる:Flexbox と Grid", "summary": "ふつう、 <div> は 縦に積み重なります 。横に並べたいときに使うのがこの2つ。", "snippet": "<div class=\"row\">", "date": "2026-10-16", "min": 2, "html": "<p>ふつう、<code>&lt;div&gt;</code> は<b>縦に積み重なります</b>。横に並べたいときに使うのがこの2つ。</p><h4>Flexbox(1列に並べる)</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;div class=&quot;row&quot;&gt;\n  &lt;div class=&quot;item&quot;&gt;1&lt;/div&gt;\n  &lt;div class=&quot;item&quot;&gt;2&lt;/div&gt;\n  &lt;div class=&quot;item&quot;&gt;3&lt;/div&gt;\n&lt;/div&gt;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.row {\n  display: flex;\n}</code></pre></div><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>親の箱に </b><b><code>display: flex;</code></b><b> と書くだけで、中の子が横並びになる。</b>(子に書いても効かない)</p></div></div><div class=\"tbl\"><table><tr><th>プロパティ(親に書く)</th><th>意味</th><th>よく使う値</th></tr><tr><td><code>justify-content</code></td><td><b>横方向</b>の並べ方</td><td><code>center</code> <code>space-between</code> <code>flex-start</code> <code>flex-end</code></td></tr><tr><td><code>align-items</code></td><td><b>縦方向</b>の並べ方</td><td><code>center</code> <code>flex-start</code> <code>flex-end</code></td></tr><tr><td><code>gap</code></td><td>子どうしのすき間</td><td><code>gap: 16px;</code></td></tr><tr><td><code>flex-wrap</code></td><td>入りきらなければ折り返す</td><td><code>wrap</code></td></tr><tr><td><code>flex-direction</code></td><td>並べる向き</td><td><code>row</code>(横)<code>column</code>(縦)</td></tr></table></div><p><b>真ん中に配置したいとき(超よく使う)</b></p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.box {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}</code></pre></div><h4>✨ Grid(縦横のマス目に並べる)</h4><p>カードを「3列で並べて、はみ出したら次の段へ」のような<b>タイル状の配置</b>はGridが得意です。</p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.cards {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr); /* 同じ幅の列を3つ */\n  gap: 24px;\n}\n\n@media (max-width: 767px) {\n  .cards {\n    grid-template-columns: 1fr;          /* スマホでは1列 */\n  }\n}</code></pre></div><ul><li><code>1fr</code> … 「残りのスペースを1つ分」という単位。<code>1fr 2fr</code> なら1:2の幅になる</li></ul><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><b>使い分けの目安</b>:横1列に並べる(メニュー、ボタンの並び)→ <b>Flexbox</b>、マス目状に並べる(カード一覧、写真ギャラリー)→ <b>Grid</b></p></div></div>"}, {"id": "html-07", "page": "HTML・CSS まとめ", "cat": "css", "ch": 7, "title": "位置をずらす・重ねる:position", "summary": "画像の上に「NEW」ラベルを重ねる、ヘッダーを画面上部に固定する、などに使います。", "snippet": "<div class=\"photo\">", "date": "2026-10-16", "min": 1, "html": "<p>画像の上に「NEW」ラベルを重ねる、ヘッダーを画面上部に固定する、などに使います。</p><div class=\"tbl\"><table><tr><th>値</th><th>動き</th><th>よく使う場面</th></tr><tr><td><code>relative</code></td><td>基準点になる(自分は元の位置のまま)</td><td>absoluteの親に付ける</td></tr><tr><td><code>absolute</code></td><td>relativeの親を基準に、好きな位置に置く</td><td>画像の上のラベル、×ボタン</td></tr><tr><td><code>fixed</code></td><td>画面に固定(スクロールしても動かない)</td><td>固定ヘッダー、「上に戻る」ボタン</td></tr><tr><td><code>sticky</code></td><td>スクロールして上端に来たら貼り付く</td><td>途中から固定されるメニュー</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;div class=&quot;photo&quot;&gt;\n  &lt;img src=&quot;item.jpg&quot; alt=&quot;商品&quot;&gt;\n  &lt;span class=&quot;badge&quot;&gt;NEW&lt;/span&gt;\n&lt;/div&gt;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.photo {\n  position: relative;   /* ここが基準 */\n}\n\n.badge {\n  position: absolute;\n  top: 8px;             /* 上から8px */\n  left: 8px;            /* 左から8px */\n  background-color: #e60033;\n  color: #fff;\n  padding: 2px 8px;\n}</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><b>absoluteは「relativeの親」とセット。</b> 親に <code>position: relative;</code> がないと、ページ全体を基準にして思わぬ場所へ飛んでいきます。重なり順は <code>z-index</code>(数字が大きいほど上)で調整します。</p></div></div>"}, {"id": "html-08", "page": "HTML・CSS まとめ", "cat": "css", "ch": 8, "title": "レスポンシブ:画面サイズに合わせる", "summary": "パソコン・タブレット・スマホで 画面の幅に応じてCSSを切り替える のが「レスポンシブ対応」。", "snippet": ".row {", "date": "2026-10-16", "min": 1, "html": "<p>パソコン・タブレット・スマホで<b>画面の幅に応じてCSSを切り替える</b>のが「レスポンシブ対応」。</p><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><code>&lt;head&gt;</code> に <code>&lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"&gt;</code> がないと、スマホで縮小表示されてしまいます。必ず入れること。</p></div></div><h4>メディアクエリ</h4><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.row {\n  display: flex;\n}\n\n@media (max-width: 767px) {\n  .row {\n    flex-direction: column;\n  }\n}</code></pre></div><p><b>読み方:「画面の幅が767px以下のときだけ、</b><b><code>.row</code></b><b> を縦並びにしてね」</b></p><div class=\"tbl\"><table><tr><th>端末</th><th>幅の目安</th></tr><tr><td>📱 スマホ(SP)</td><td>〜767px</td></tr><tr><td>📟 タブレット(Tab)</td><td>768px〜1023px</td></tr><tr><td>💻 パソコン(PC)</td><td>1024px〜</td></tr></table></div><p>※ 数字はFigmaのデザインや案件のルールに合わせてください。</p><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p>✨ <b>スマホファースト</b>:先にスマホ用のCSSを書き、<code>@media (min-width: 768px)</code> で「広い画面のときだけ」上書きする書き方も主流です。案件の書き方に合わせましょう。</p></div></div>"}, {"id": "html-09", "page": "HTML・CSS まとめ", "cat": "css", "ch": 9, "title": "動きをつける:hover と transition", "summary": "JavaScriptを使わなくても、CSSだけでちょっとした動きがつけられます。", "snippet": ".btn {", "date": "2026-10-16", "min": 1, "html": "<p>JavaScriptを使わなくても、CSSだけでちょっとした動きがつけられます。</p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.btn {\n  background-color: #ff7a00;\n  color: #fff;\n  transition: 0.3s;          /* 変化を0.3秒かけてなめらかに */\n}\n\n.btn:hover {\n  background-color: #e06600; /* マウスを乗せると少し暗く */\n  opacity: 0.8;\n}</code></pre></div><ul><li><code>transition</code> は<b>元の状態(.btn)のほうに書く</b>のがポイント</li><li><code>transform: translateY(-2px);</code> を hover に足すと、少し浮き上がる動きになる</li></ul>"}, {"id": "html-10", "page": "HTML・CSS まとめ", "cat": "css", "ch": 10, "title": "CSS変数:色をまとめて管理する", "summary": "サイトのメインカラーを何十か所にも書いていると、色を変えたいときに大変です。変数にしておけば1か所直すだけ。", "snippet": ":root {", "date": "2026-10-16", "min": 1, "html": "<p>サイトのメインカラーを何十か所にも書いていると、色を変えたいときに大変です。変数にしておけば1か所直すだけ。</p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>:root {\n  --main-color: #ff7a00;\n  --text-color: #333;\n}\n\n.btn {\n  background-color: var(--main-color);\n}\n\nh2 {\n  color: var(--text-color);\n}</code></pre></div>"}, {"id": "html-11", "page": "HTML・CSS まとめ", "cat": "css", "ch": 11, "title": "実践:カードを1枚作ってみよう", "summary": "HTML", "snippet": "<!DOCTYPE html>", "date": "2026-10-16", "min": 3, "html": "<p><b>HTML</b></p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;ja&quot;&gt;\n&lt;head&gt;\n  &lt;meta charset=&quot;UTF-8&quot;&gt;\n  &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;\n  &lt;title&gt;カードの練習&lt;/title&gt;\n  &lt;link rel=&quot;stylesheet&quot; href=&quot;style.css&quot;&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;div class=&quot;card&quot;&gt;\n    &lt;img src=&quot;cat.jpg&quot; alt=&quot;ねこ&quot;&gt;\n    &lt;h2 class=&quot;card-title&quot;&gt;ねこのタマ&lt;/h2&gt;\n    &lt;p class=&quot;card-text&quot;&gt;とてもかわいいねこです。&lt;/p&gt;\n    &lt;a href=&quot;#&quot; class=&quot;card-button&quot;&gt;もっと見る&lt;/a&gt;\n  &lt;/div&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre></div><p><b>CSS(style.css)</b></p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  background-color: #f5f5f5;\n  font-family: sans-serif;\n}\n\n.card {\n  width: 320px;\n  margin: 40px auto;        /* 左右autoで真ん中に寄る */\n  padding: 20px;\n  background-color: #fff;\n  border-radius: 12px;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\n}\n\n.card img {\n  max-width: 100%;\n  height: auto;\n}\n\n.card-title {\n  font-size: 24px;\n  color: #333;\n}\n\n.card-text {\n  font-size: 14px;\n  line-height: 1.6;\n}\n\n.card-button {\n  display: inline-block;     /* リンクにもpaddingが効くようにする */\n  padding: 10px 20px;\n  background-color: #ff7a00;\n  color: #fff;\n  border-radius: 6px;\n  text-decoration: none;     /* リンクの下線を消す */\n  transition: 0.3s;\n}\n\n.card-button:hover {\n  opacity: 0.8;\n}</code></pre></div><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>ポイント</b></p><ul><li><code>margin: 40px auto;</code> … 上下40px、左右は自動で均等 → 箱が真ん中に来る</li><li><code>display: inline-block;</code> … リンク(inline)にも <code>padding</code> が効くようにする</li><li><code>.card img</code> … 「<code>.card</code> の中にある <code>img</code>」だけに効かせる指定</li></ul></div></div><p><b>チャレンジ</b> ✨:このカードを3枚並べて、Gridで「PCは3列、スマホは1列」にしてみよう(6章のコードが使えます)。</p>"}, {"id": "html-12", "page": "HTML・CSS まとめ", "cat": "css", "ch": 12, "title": "困ったときのチェックリスト", "summary": "CSSが効かないとき、上から順に確認。", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<p>CSSが効かないとき、上から順に確認。</p><ul><li class=\"chk\"><b>CSSファイルは読み込めている?</b> → <code>&lt;link&gt;</code> の <code>href</code> のファイル名・場所が合っているか</li><li class=\"chk\"><b>クラス名のスペルは合っている?</b> → HTMLの <code>class=\"card\"</code> とCSSの <code>.card</code> が一致しているか</li><li class=\"chk\"><b>ドット </b><b><code>.</code></b><b> を忘れていない?</b> → <code>card</code> だけだとタグ名の指定になる</li><li class=\"chk\"><b><code>;</code></b><b> が抜けていない?</b></li><li class=\"chk\"><b><code>}</code></b><b> で閉じ忘れていない?</b></li><li class=\"chk\"><b>タグの閉じ忘れはない?</b> → <code>&lt;div&gt;</code> に対して <code>&lt;/div&gt;</code> があるか</li><li class=\"chk\">✨ <b>ほかのCSSに負けていない?</b> → 検証ツールで線が引かれていないか(3章の「どっちが勝つ?」)</li><li class=\"chk\">✨ <b>inline要素に幅や上下余白を指定していない?</b> → <code>display: inline-block;</code> か <code>block</code> にする</li><li class=\"chk\"><b>ブラウザのキャッシュ</b> → <code>Ctrl + F5</code>(Macは <code>Cmd + Shift + R</code>)で強制再読み込み</li></ul><h4>最強の味方:ブラウザの検証ツール</h4><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><ul><li>ページ上で右クリック →「<b>検証</b>」(または <code>F12</code> キー)</li><li>見たい部分をクリックすると、<b>その部品のHTMLとCSSがその場でわかる</b></li><li>CSSを書き換えて、結果をすぐ試せる(保存はされない)</li><li>✨ 左上のスマホのアイコンを押すと、<b>スマホ幅での見た目</b>を確認できる</li></ul><p>プロもずっと使っているので、迷ったらまず検証ツール。</p></div></div>"}, {"id": "html-13", "page": "HTML・CSS まとめ", "cat": "html", "ch": 13, "title": "用語ミニ辞典", "summary": "用語 意味 タグ HTMLのラベル。 <p> など 要素 開始タグ・中身・終了タグのセット 属性 タグにつける追加情報。 class href など クラス 部品につける名前。CSSで .名前 と指定する セレクタ CSSで「どの部品か」を", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<div class=\"tbl\"><table><tr><th>用語</th><th>意味</th></tr><tr><td>タグ</td><td>HTMLのラベル。<code>&lt;p&gt;</code> など</td></tr><tr><td>要素</td><td>開始タグ・中身・終了タグのセット</td></tr><tr><td>属性</td><td>タグにつける追加情報。<code>class</code> <code>href</code> など</td></tr><tr><td>クラス</td><td>部品につける名前。CSSで <code>.名前</code> と指定する</td></tr><tr><td>セレクタ</td><td>CSSで「どの部品か」を指定する部分</td></tr><tr><td>プロパティ</td><td>CSSで「何を変えるか」(<code>color</code> など)</td></tr><tr><td>親要素・子要素</td><td>外側の箱が親、中に入っている箱が子</td></tr><tr><td>疑似クラス ✨</td><td><code>:hover</code> など「ある状態のとき」を指定するもの</td></tr><tr><td>レスポンシブ</td><td>画面サイズに合わせて見た目が変わること</td></tr><tr><td>ブレークポイント</td><td>レスポンシブで見た目を切り替える幅(767pxなど)</td></tr><tr><td>コーディング ✨</td><td>デザイン(Figmaなど)を見て、HTML/CSSで形にする作業</td></tr></table></div>"}, {"id": "html-14", "page": "HTML・CSS まとめ", "cat": "css", "ch": 14, "title": "勉強のコツ", "summary": "全部覚えようとしない。 このページは「辞書」として使えばOK 手を動かす。 11章のカードを、コピペではなく 自分で打ってみる 数字をわざと変えてみる。 padding: 20px を 50px にしたらどうなる? 壊してもいい。 元に戻せ", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<ol><li><b>全部覚えようとしない。</b> このページは「辞書」として使えばOK</li><li><b>手を動かす。</b> 11章のカードを、コピペではなく<b>自分で打ってみる</b></li><li><b>数字をわざと変えてみる。</b> <code>padding: 20px</code> を <code>50px</code> にしたらどうなる?</li><li><b>壊してもいい。</b> 元に戻せばいいだけ</li><li><b>検証ツールで他のサイトを観察する。</b> 「これどう作ってるの?」が一番の勉強になる</li></ol>"}, {"id": "js-01", "page": "JavaScript まとめ", "cat": "js", "ch": 1, "title": "JavaScriptを動かす準備", "summary": "defer を付ける と「HTMLを全部読み終わってからJSを実行」になります。付けないと、まだ存在しないボタンを探してエラーになることがあります。( </body> の直前に <script> を書く方法でも同じ効果)", "snippet": "<head>", "date": "2026-10-16", "min": 1, "html": "<h4>HTMLから読み込む</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;head&gt;\n  &lt;script src=&quot;main.js&quot; defer&gt;&lt;/script&gt;\n&lt;/head&gt;</code></pre></div><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b><code>defer</code></b><b> を付ける</b>と「HTMLを全部読み終わってからJSを実行」になります。付けないと、まだ存在しないボタンを探してエラーになることがあります。(<code>&lt;/body&gt;</code> の直前に <code>&lt;script&gt;</code> を書く方法でも同じ効果)</p></div></div><h4>動きを確認する:console.log</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>console.log(&quot;ここまで動いた&quot;);\nconsole.log(count);   // 変数の中身を確認</code></pre></div><ul><li>ブラウザで <code>F12</code> →「<b>Console(コンソール)</b>」タブに表示される</li><li><b>エラーもここに赤字で出る</b>。動かないときは、まずコンソールを見る</li></ul>"}, {"id": "js-02", "page": "JavaScript まとめ", "cat": "js", "ch": 2, "title": "変数とデータ型", "summary": "const はオブジェクトや配列の 中身 までは固定しません。「変数に別のものを入れ直す」ことができないだけです。", "snippet": "const name = \"Taro\";   // 再代入できない", "date": "2026-10-16", "min": 2, "html": "<h4>宣言の種類</h4><div class=\"tbl\"><table><tr><th>キーワード</th><th>再代入</th><th>再宣言</th><th>スコープ</th><th>使い方</th></tr><tr><td><code>const</code></td><td>✕</td><td>✕</td><td>ブロック</td><td><b>基本はこれ</b></td></tr><tr><td><code>let</code></td><td>○</td><td>✕</td><td>ブロック</td><td>あとで値を変えるときだけ</td></tr><tr><td><code>var</code></td><td>○</td><td>○</td><td>関数</td><td>古い書き方。使わない</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const name = &quot;Taro&quot;;   // 再代入できない\nlet count = 0;         // 再代入できる\ncount = count + 1;</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><code>const</code> はオブジェクトや配列の<b>中身</b>までは固定しません。「変数に別のものを入れ直す」ことができないだけです。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const user = { age: 20 };\nuser.age = 21;   // OK(中身の変更)\nuser = {};       // エラー(入れ直し)</code></pre></div><h4>データ型</h4><ul><li><b>プリミティブ型</b>:<code>string</code>(文字)、<code>number</code>(数値)、<code>boolean</code>(true/false)、<code>null</code>、<code>undefined</code>、<code>bigint</code>、<code>symbol</code></li><li><b>オブジェクト型</b>:オブジェクト、配列、関数、日付など</li></ul><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>typeof &quot;a&quot;;        // &quot;string&quot;\ntypeof 10;         // &quot;number&quot;\ntypeof null;       // &quot;object&quot;(歴史的なバグ)\ntypeof undefined;  // &quot;undefined&quot;</code></pre></div><h4>テンプレートリテラル(文字の中に変数を入れる)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const age = 20;\nconsole.log(`私は${age}歳です`);   // バッククォート ` で囲み、${ } で埋め込む</code></pre></div><h4>✨ 文字と数値の変換</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Number(&quot;42&quot;);        // 42(文字 → 数値)\nString(42);          // &quot;42&quot;(数値 → 文字)\n&quot;10&quot; + 5;            // &quot;105&quot;(+ は文字の連結になる!)\nNumber(&quot;10&quot;) + 5;    // 15</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>入力欄(input)から取った値は必ず文字列。</b> そのまま <code>+</code> すると連結されてしまうので、計算するときは <code>Number()</code> で変換します。</p></div></div><h4>等価比較</h4><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><code>==</code> は型を勝手に変換するので避け、<b><code>===</code></b><b>(厳密等価)を使う</b>。否定は <code>!==</code>。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>1 == &quot;1&quot;;    // true\n1 === &quot;1&quot;;   // false</code></pre></div><h4>Falsy な値(条件式で false 扱い)</h4><p><code>false</code>、<code>0</code>、<code>\"\"</code>(空文字)、<code>null</code>、<code>undefined</code>、<code>NaN</code> の6つ。それ以外は全部 true(<code>\"0\"</code> や <code>[]</code> も true)。</p>"}, {"id": "js-03", "page": "JavaScript まとめ", "cat": "js", "ch": 3, "title": "条件分岐", "summary": "|| と ?? の違い: 0 や \"\" を ちゃんとした値として扱いたい ときは ?? を使う。", "snippet": "const score = 75;", "date": "2026-10-16", "min": 1, "html": "<h4>if / else if / else</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const score = 75;\n\nif (score &gt;= 80) {\n  console.log(&quot;優&quot;);\n} else if (score &gt;= 60) {\n  console.log(&quot;良&quot;);\n} else {\n  console.log(&quot;不可&quot;);\n}</code></pre></div><h4>三項演算子(短いif)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const result = score &gt;= 60 ? &quot;合格&quot; : &quot;不合格&quot;;</code></pre></div><h4>switch</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>switch (day) {\n  case &quot;sat&quot;:\n  case &quot;sun&quot;:\n    console.log(&quot;休み&quot;);\n    break;          // break を忘れると次の case に流れる\n  default:\n    console.log(&quot;平日&quot;);\n}</code></pre></div><h4>論理演算子・Null合体・オプショナルチェーン</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>a &amp;&amp; b;      // a が truthy なら b、falsy なら a\na || b;      // a が truthy なら a、falsy なら b\na ?? b;      // a が null/undefined のときだけ b\nuser?.name;  // user が null/undefined なら undefined(エラーにならない)</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><code>||</code> と <code>??</code> の違い:<code>0</code> や <code>\"\"</code> を<b>ちゃんとした値として扱いたい</b>ときは <code>??</code> を使う。</p><p><code>0 || 10</code> → 10 / <code>0 ?? 10</code> → 0</p></div></div>"}, {"id": "js-04", "page": "JavaScript まとめ", "cat": "js", "ch": 4, "title": "繰り返し(ループ)", "summary": "while で条件がずっと true のままだと 無限ループ になり、ブラウザが固まります。条件が変わる処理( n++ など)を忘れずに。", "snippet": "for (let i = 0; i < 5; i++) {", "date": "2026-10-16", "min": 1, "html": "<div class=\"tbl\"><table><tr><th>書き方</th><th>使う場面</th></tr><tr><td><code>for (let i = 0; i &lt; 5; i++)</code></td><td>回数を決めて繰り返す</td></tr><tr><td><code>for (const x of 配列)</code></td><td><b>配列の値を順に取り出す</b>(一番よく使う)</td></tr><tr><td><code>for (const key in オブジェクト)</code></td><td>オブジェクトのキーを順に(配列には使わない)</td></tr><tr><td><code>while (条件)</code></td><td>条件が true の間ずっと</td></tr><tr><td><code>配列.forEach((x) =&gt; …)</code></td><td>配列の各要素に処理をする</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>for (let i = 0; i &lt; 5; i++) {\n  console.log(i);              // 0,1,2,3,4\n}\n\nfor (const fruit of [&quot;apple&quot;, &quot;banana&quot;]) {\n  console.log(fruit);\n}\n\nconst obj = { a: 1, b: 2 };\nfor (const key in obj) {\n  console.log(key, obj[key]);\n}\n\nlet n = 0;\nwhile (n &lt; 3) {\n  n++;\n}\n\ndo {\n  n--;\n} while (n &gt; 0);               // 最低1回は実行される\n\n[1, 2, 3].forEach((x) =&gt; console.log(x));</code></pre></div><h4>break / continue</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>for (let i = 0; i &lt; 10; i++) {\n  if (i === 3) continue;  // 今回だけスキップ\n  if (i === 6) break;     // ループ終了\n}</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><code>while</code> で条件がずっと true のままだと<b>無限ループ</b>になり、ブラウザが固まります。条件が変わる処理(<code>n++</code> など)を忘れずに。</p></div></div>"}, {"id": "js-05", "page": "JavaScript まとめ", "cat": "js", "ch": 5, "title": "関数", "summary": "関数は、自分が定義された場所の変数を覚えています(クロージャ)。", "snippet": "function add(a, b) {", "date": "2026-10-16", "min": 2, "html": "<h4>定義の方法</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// 関数宣言(巻き上げされる=定義より前で呼べる)\nfunction add(a, b) {\n  return a + b;\n}\n\n// 関数式\nconst add2 = function (a, b) {\n  return a + b;\n};\n\n// アロー関数(よく使う)\nconst add3 = (a, b) =&gt; a + b;   // 式が1つなら return と {} を省略可\nconst square = (x) =&gt; x * x;    // 引数1つなら () も省略可</code></pre></div><h4>引数の便利な機能</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// デフォルト引数\nconst greet = (name = &quot;ゲスト&quot;) =&gt; `こんにちは、${name}さん`;\n\n// 残余引数(いくつでも受け取る)\nconst sum = (...nums) =&gt; nums.reduce((a, b) =&gt; a + b, 0);\nsum(1, 2, 3);  // 6\n\n// 分割代入を引数で使う\nfunction show({ name, age }) {\n  console.log(name, age);\n}</code></pre></div><h4>スコープとクロージャ</h4><p>関数は、自分が定義された場所の変数を覚えています(クロージャ)。</p><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>function counter() {\n  let count = 0;\n  return () =&gt; ++count;\n}\nconst c = counter();\nc();  // 1\nc();  // 2</code></pre></div><h4>関数宣言とアロー関数の違い</h4><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>アロー関数は自分の <code>this</code> を持たず、外側の <code>this</code> を引き継ぐ</li><li>アロー関数は <code>arguments</code> を持たない</li><li>アロー関数はコンストラクタ(<code>new</code>)として使えない</li></ul></div></div><h4>高階関数とコールバック</h4><p>関数を引数に渡したり、関数を返したりできます。イベント処理(9章)もこの仕組みです。</p><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>function repeat(n, fn) {\n  for (let i = 0; i &lt; n; i++) fn(i);\n}\nrepeat(3, (i) =&gt; console.log(i));</code></pre></div>"}, {"id": "js-06", "page": "JavaScript まとめ", "cat": "js", "ch": 6, "title": "配列", "summary": "sort() は 元の配列を変更し、しかも文字として比較 します( [10, 9, 1].sort() → [1, 10, 9] )。数値は比較関数を渡し、コピーしてから並べるのが安全です。", "snippet": "const arr = [10, 20, 30];", "date": "2026-10-16", "min": 3, "html": "<h4>作成とアクセス</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const arr = [10, 20, 30];\narr[0];        // 10(番号は0から)\narr.length;    // 3\narr.at(-1);    // 30(末尾)</code></pre></div><h4>追加・削除(元の配列を変更する)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>arr.push(40);       // 末尾に追加\narr.pop();          // 末尾を削除\narr.unshift(0);     // 先頭に追加\narr.shift();        // 先頭を削除\narr.splice(1, 2);   // 1番目から2個削除</code></pre></div><h4>主要メソッド(元の配列を変更しない)</h4><div class=\"tbl\"><table><tr><th>メソッド</th><th>役割</th><th>例(nums = [1,2,3,4,5])</th><th>結果</th></tr><tr><td><code>map</code></td><td>全部を<b>変換</b></td><td><code>nums.map((n) =&gt; n * 2)</code></td><td>[2,4,6,8,10]</td></tr><tr><td><code>filter</code></td><td>条件で<b>絞り込み</b></td><td><code>nums.filter((n) =&gt; n % 2 === 0)</code></td><td>[2,4]</td></tr><tr><td><code>reduce</code></td><td>1つに<b>集約</b></td><td><code>nums.reduce((a, b) =&gt; a + b, 0)</code></td><td>15</td></tr><tr><td><code>find</code></td><td>最初に一致したもの</td><td><code>nums.find((n) =&gt; n &gt; 2)</code></td><td>3</td></tr><tr><td><code>findIndex</code></td><td>最初に一致した番号</td><td><code>nums.findIndex((n) =&gt; n &gt; 2)</code></td><td>2</td></tr><tr><td><code>some</code></td><td>1つでも満たすか</td><td><code>nums.some((n) =&gt; n &gt; 4)</code></td><td>true</td></tr><tr><td><code>every</code></td><td>全部満たすか</td><td><code>nums.every((n) =&gt; n &gt; 0)</code></td><td>true</td></tr><tr><td><code>includes</code></td><td>含むか</td><td><code>nums.includes(3)</code></td><td>true</td></tr><tr><td><code>slice</code></td><td>一部を切り出す</td><td><code>nums.slice(1, 3)</code></td><td>[2,3]</td></tr><tr><td><code>join</code></td><td>文字列にする</td><td><code>nums.join(\"-\")</code></td><td>\"1-2-3-4-5\"</td></tr><tr><td><code>concat</code></td><td>結合</td><td><code>nums.concat([6])</code></td><td>[1,…,6]</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><code>sort()</code> は<b>元の配列を変更し、しかも文字として比較</b>します(<code>[10, 9, 1].sort()</code> → <code>[1, 10, 9]</code>)。数値は比較関数を渡し、コピーしてから並べるのが安全です。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>[...nums].sort((a, b) =&gt; a - b);   // 小さい順(コピーしてから)\n[...nums].sort((a, b) =&gt; b - a);   // 大きい順</code></pre></div><h4>スプレッド構文と分割代入</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const copy = [...nums];\nconst merged = [...nums, 6, 7];\nconst [first, second, ...rest] = nums;</code></pre></div><h4>メソッドチェーン(つなげて使う)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const total = items\n  .filter((i) =&gt; i.price &gt; 100)\n  .map((i) =&gt; i.price)\n  .reduce((a, b) =&gt; a + b, 0);</code></pre></div>"}, {"id": "js-07", "page": "JavaScript まとめ", "cat": "js", "ch": 7, "title": "オブジェクト", "summary": "this は「 どう呼ばれたか 」で決まります。メソッドとして呼べばそのオブジェクト、単独で呼ぶと undefined (strict mode)。", "snippet": "const user = {", "date": "2026-10-16", "min": 2, "html": "<h4>作成とアクセス</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const user = {\n  name: &quot;Taro&quot;,\n  age: 20,\n  greet() {                        // メソッド\n    return `I&#x27;m ${this.name}`;\n  },\n};\n\nuser.name;           // ドット記法\nuser[&quot;age&quot;];         // ブラケット記法(キーが変数のとき)\nuser.email = &quot;a@b&quot;;  // 追加\ndelete user.age;     // 削除</code></pre></div><h4>省略記法・計算されたキー・分割代入</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const name = &quot;Hanako&quot;;\nconst person = { name };             // { name: name } と同じ\n\nconst key = &quot;color&quot;;\nconst item = { [key]: &quot;red&quot; };       // { color: &quot;red&quot; }\n\nconst { name: n, age = 0 } = user;   // 別名・デフォルト値も指定可</code></pre></div><h4>コピー</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const updated = { ...user, age: 21 };   // 浅いコピー+上書き\nconst deep = structuredClone(user);      // 深いコピー(中のオブジェクトまで)</code></pre></div><h4>便利な静的メソッド</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Object.keys(user);      // キーの配列\nObject.values(user);    // 値の配列\nObject.entries(user);   // [[キー, 値], ...]\nObject.assign({}, a, b);\nObject.freeze(user);    // 変更不可にする(浅い)</code></pre></div><h4>JSON との変換</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const json = JSON.stringify(user);   // オブジェクト → 文字列\nconst obj = JSON.parse(json);        // 文字列 → オブジェクト</code></pre></div><h4>this について</h4><p><code>this</code> は「<b>どう呼ばれたか</b>」で決まります。メソッドとして呼べばそのオブジェクト、単独で呼ぶと <code>undefined</code>(strict mode)。</p><h4>クラス(参考)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>class Animal {\n  constructor(name) {\n    this.name = name;\n  }\n  speak() {\n    return `${this.name} makes a sound`;\n  }\n}\n\nclass Dog extends Animal {\n  speak() {\n    return `${this.name} barks`;\n  }\n}</code></pre></div>"}, {"id": "js-08", "page": "JavaScript まとめ", "cat": "js", "ch": 8, "title": "DOM操作:JSでHTMLを書き換える", "summary": "Webデザイン/コーディングで一番使うのがここ。 「ボタンを押したらメニューが開く」などは、すべて ① HTMLの部品をつかむ → ② 中身やクラスを変える の組み合わせです。", "snippet": "const title = document.querySelector(\".title\");      // 最初の1つ(CSSと同じ書き方)", "date": "2026-10-16", "min": 2, "html": "<div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>Webデザイン/コーディングで一番使うのがここ。</b> 「ボタンを押したらメニューが開く」などは、すべて <b>① HTMLの部品をつかむ → ② 中身やクラスを変える</b> の組み合わせです。</p></div></div><h4>① 部品をつかむ</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const title = document.querySelector(&quot;.title&quot;);      // 最初の1つ(CSSと同じ書き方)\nconst btn   = document.querySelector(&quot;#menu-btn&quot;);   // id で\nconst items = document.querySelectorAll(&quot;.item&quot;);    // 全部(forEach で回せる)</code></pre></div><h4>② 変える</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>コード</th></tr><tr><td>文字を変える</td><td><code>title.textContent = \"新しい見出し\";</code></td></tr><tr><td>クラスを付ける</td><td><code>el.classList.add(\"is-open\");</code></td></tr><tr><td>クラスを外す</td><td><code>el.classList.remove(\"is-open\");</code></td></tr><tr><td><b>付いていれば外す/なければ付ける</b></td><td><code>el.classList.toggle(\"is-open\");</code></td></tr><tr><td>クラスが付いているか</td><td><code>el.classList.contains(\"is-open\")</code></td></tr><tr><td>属性を変える</td><td><code>img.setAttribute(\"src\", \"new.jpg\");</code></td></tr><tr><td>スタイルを直接変える</td><td><code>el.style.color = \"red\";</code></td></tr><tr><td>入力欄の値を取る</td><td><code>input.value</code></td></tr><tr><td>新しい部品を作って追加</td><td>下のコード</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const li = document.createElement(&quot;li&quot;);\nli.textContent = &quot;新しい項目&quot;;\ndocument.querySelector(&quot;ul&quot;).append(li);</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><b>見た目の変更はCSSに任せて、JSはクラスを付け外しするだけ</b>にするのが実務のコツ。<code>el.style</code> で直接書くより、CSSに <code>.is-open { … }</code> を用意して <code>classList.toggle</code> するほうが管理しやすくなります。</p></div></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><code>innerHTML</code> でもHTMLを書き換えられますが、<b>ユーザーが入力した文字を入れると危険</b>(悪意あるコードが動く可能性)。文字だけなら <code>textContent</code> を使いましょう。</p></div></div>"}, {"id": "js-09", "page": "JavaScript まとめ", "cat": "js", "ch": 9, "title": "イベント:「〜したら」を作る", "summary": "読み方:「btn が click されたら、{ } の中を実行して」", "snippet": "const btn = document.querySelector(\"#menu-btn\");", "date": "2026-10-16", "min": 2, "html": "<div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const btn = document.querySelector(&quot;#menu-btn&quot;);\n\nbtn.addEventListener(&quot;click&quot;, () =&gt; {\n  console.log(&quot;クリックされた&quot;);\n});</code></pre></div><p><b>読み方:「btn が click されたら、{ } の中を実行して」</b></p><div class=\"tbl\"><table><tr><th>イベント名</th><th>いつ起きる?</th></tr><tr><td><code>click</code></td><td>クリックしたとき</td></tr><tr><td><code>input</code></td><td>入力欄に文字を打つたび</td></tr><tr><td><code>change</code></td><td>選択や入力が確定したとき(セレクトボックスなど)</td></tr><tr><td><code>submit</code></td><td>フォームを送信したとき</td></tr><tr><td><code>scroll</code></td><td>スクロールしたとき(<code>window</code> に付ける)</td></tr><tr><td><code>DOMContentLoaded</code></td><td>HTMLの読み込みが終わったとき</td></tr></table></div><h4>イベントの情報を使う</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const form = document.querySelector(&quot;form&quot;);\n\nform.addEventListener(&quot;submit&quot;, (e) =&gt; {\n  e.preventDefault();               // 本来の動き(ページ移動)を止める\n  const name = form.querySelector(&quot;#name&quot;).value;\n  if (name === &quot;&quot;) {\n    alert(&quot;お名前を入力してください&quot;);\n  }\n});</code></pre></div><ul><li><code>e</code>(event)… 何が起きたかの情報。<code>e.target</code> で「クリックされた部品」が分かる</li><li><code>e.preventDefault()</code> … リンクの移動やフォーム送信を止める</li></ul><h4>複数の部品にまとめて付ける</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>document.querySelectorAll(&quot;.item&quot;).forEach((item) =&gt; {\n  item.addEventListener(&quot;click&quot;, () =&gt; {\n    item.classList.toggle(&quot;is-active&quot;);\n  });\n});</code></pre></div>"}, {"id": "js-10", "page": "JavaScript まとめ", "cat": "js", "ch": 10, "title": "実践:よく作るパーツ", "summary": "HTML", "snippet": "<button class=\"menu-btn\" aria-label=\"メニュー\">☰</button>", "date": "2026-10-16", "min": 2, "html": "<h4>ハンバーガーメニュー</h4><p><b>HTML</b></p><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;button class=&quot;menu-btn&quot; aria-label=&quot;メニュー&quot;&gt;☰&lt;/button&gt;\n&lt;nav class=&quot;menu&quot;&gt;\n  &lt;ul&gt;\n    &lt;li&gt;&lt;a href=&quot;#about&quot;&gt;私たちについて&lt;/a&gt;&lt;/li&gt;\n    &lt;li&gt;&lt;a href=&quot;#contact&quot;&gt;お問い合わせ&lt;/a&gt;&lt;/li&gt;\n  &lt;/ul&gt;\n&lt;/nav&gt;</code></pre></div><p><b>CSS</b></p><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.menu {\n  display: none;          /* 最初は隠す */\n}\n\n.menu.is-open {\n  display: block;         /* is-open が付いたら表示 */\n}</code></pre></div><p><b>JavaScript</b></p><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>const menuBtn = document.querySelector(&quot;.menu-btn&quot;);\nconst menu = document.querySelector(&quot;.menu&quot;);\n\nmenuBtn.addEventListener(&quot;click&quot;, () =&gt; {\n  menu.classList.toggle(&quot;is-open&quot;);\n});</code></pre></div><h4>アコーディオン(Q&amp;Aの開閉)</h4><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;div class=&quot;faq&quot;&gt;\n  &lt;button class=&quot;faq-q&quot;&gt;Q. 送料はかかりますか?&lt;/button&gt;\n  &lt;p class=&quot;faq-a&quot;&gt;A. 5,000円以上で無料です。&lt;/p&gt;\n&lt;/div&gt;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>css</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>.faq-a {\n  display: none;\n}\n\n.faq.is-open .faq-a {\n  display: block;\n}</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>document.querySelectorAll(&quot;.faq-q&quot;).forEach((q) =&gt; {\n  q.addEventListener(&quot;click&quot;, () =&gt; {\n    q.parentElement.classList.toggle(&quot;is-open&quot;);  // 親の .faq に付け外し\n  });\n});</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><b>どちらも同じパターン</b>:①ボタンをつかむ → ②click イベント → ③親や対象に <code>classList.toggle</code> → ④見た目はCSSで切り替え。これが分かればタブ切り替えやモーダルも作れます。</p></div></div>"}, {"id": "js-11", "page": "JavaScript まとめ", "cat": "js", "ch": 11, "title": "非同期処理(待つ処理)", "summary": "✨ 時間をおいて実行する javascript 写経する setTimeout(() => { console.log(\"3秒後に実行\"); }, 3000); // ミリ秒(1000 = 1秒) const id = setInterva", "snippet": "setTimeout(() => {", "date": "2026-10-16", "min": 1, "html": "<h4>✨ 時間をおいて実行する</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>setTimeout(() =&gt; {\n  console.log(&quot;3秒後に実行&quot;);\n}, 3000);                      // ミリ秒(1000 = 1秒)\n\nconst id = setInterval(() =&gt; {\n  console.log(&quot;1秒ごとに実行&quot;);\n}, 1000);\nclearInterval(id);             // 止める</code></pre></div><h4>データを取りに行く(fetch + async/await)</h4><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>async function getUser() {\n  try {\n    const res = await fetch(&quot;https://example.com/api/user&quot;);\n    const data = await res.json();\n    return data;\n  } catch (e) {\n    console.error(e);          // 失敗したときはここ\n  }\n}</code></pre></div><ul><li><code>async</code> を付けた関数の中でだけ <code>await</code>(結果を待つ)が使える</li><li><code>try { } catch { }</code> で、通信エラーが起きても止まらないようにする</li></ul>"}, {"id": "js-12", "page": "JavaScript まとめ", "cat": "js", "ch": 12, "title": "モジュール(ファイルを分ける)", "summary": "javascript 写経する // math.js export const PI = 3.14; export function add(a, b) { return a + b; } export default function m", "snippet": "export const PI = 3.14;", "date": "2026-10-16", "min": 1, "html": "<div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// math.js\nexport const PI = 3.14;\nexport function add(a, b) {\n  return a + b;\n}\nexport default function main() {}   // デフォルトは1ファイルに1つ</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// main.js\nimport main, { PI, add } from &quot;./math.js&quot;;\nimport { add as plus } from &quot;./math.js&quot;;   // 別名\nimport * as math from &quot;./math.js&quot;;         // まとめて取得\nmath.add(1, 2);\n\nconst mod = await import(&quot;./heavy.js&quot;);    // 必要なときに読み込む(動的インポート)</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>html</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>&lt;script type=&quot;module&quot; src=&quot;main.js&quot;&gt;&lt;/script&gt;</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>相対パスでは拡張子(<code>.js</code>)が必要</li><li>モジュールは自動で strict mode・<code>defer</code> と同じ動き</li><li><b>HTMLをダブルクリックで開く(</b><b><code>file://</code></b><b>)とCORSエラー</b>になるので、VS Codeの「Live Server」などで開く</li><li>Node.jsでは <code>package.json</code> に <code>\"type\": \"module\"</code> を書くと使える(<code>require</code> は CommonJS という別方式)</li></ul></div></div>"}, {"id": "js-13", "page": "JavaScript まとめ", "cat": "js", "ch": 13, "title": "よく出るエラーと直し方", "summary": "動かないときの手順 :① F12でコンソールの赤字を読む → ② 行番号をクリックして場所を見る → ③ console.log を入れて、どこまで動いているか確かめる", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<div class=\"tbl\"><table><tr><th>コンソールの表示</th><th>意味</th><th>直し方</th></tr><tr><td><code>Uncaught ReferenceError: ○○ is not defined</code></td><td>○○という変数・関数がない</td><td>つづりミス、宣言し忘れ、大文字小文字の違いを確認</td></tr><tr><td><code>Cannot read properties of null (reading 'addEventListener')</code></td><td>querySelectorで部品が<b>見つからなかった</b>(null)</td><td>セレクタの <code>.</code> <code>#</code> やクラス名を確認。<code>defer</code> を付け忘れていないか</td></tr><tr><td><code>Cannot read properties of undefined (reading '○○')</code></td><td>中身のないものから○○を取ろうとした</td><td><code>console.log</code> で中身を確認。<code>?.</code> を使う</td></tr><tr><td><code>○○ is not a function</code></td><td>関数じゃないものを <code>()</code> で呼んだ</td><td>メソッド名のつづり(<code>addEventListner</code> など)を確認</td></tr><tr><td><code>Assignment to constant variable</code></td><td><code>const</code> に再代入した</td><td>変える必要があるなら <code>let</code> にする</td></tr><tr><td><code>SyntaxError: Unexpected token</code></td><td>書き方のミス</td><td><code>( )</code> <code>{ }</code> の閉じ忘れ、<code>,</code> の過不足を確認</td></tr><tr><td><code>Access … has been blocked by CORS policy</code></td><td><code>file://</code> で開いた、または相手のサーバーが許可していない</td><td>Live Server などのローカルサーバーで開く</td></tr></table></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><b>動かないときの手順</b>:① F12でコンソールの赤字を読む → ② 行番号をクリックして場所を見る → ③ <code>console.log</code> を入れて、どこまで動いているか確かめる</p></div></div>"}, {"id": "js-14", "page": "JavaScript まとめ", "cat": "js", "ch": 14, "title": "まとめ:押さえるポイント", "summary": "項目 押さえるポイント 準備 <script defer> で読み込み、 console.log とコンソールで確認 変数 const 優先、必要なら let 、 var は使わない 条件分岐 === で比較、 ?? と ?. を活用 繰り", "snippet": "", "date": "2026-10-16", "min": 1, "html": "<div class=\"tbl\"><table><tr><th>項目</th><th>押さえるポイント</th></tr><tr><td>準備</td><td><code>&lt;script defer&gt;</code> で読み込み、<code>console.log</code> とコンソールで確認</td></tr><tr><td>変数</td><td><code>const</code> 優先、必要なら <code>let</code>、<code>var</code> は使わない</td></tr><tr><td>条件分岐</td><td><code>===</code> で比較、<code>??</code> と <code>?.</code> を活用</td></tr><tr><td>繰り返し</td><td>値を回すなら <code>for...of</code>、変換・絞り込みは配列メソッド</td></tr><tr><td>関数</td><td>アロー関数が基本。通常関数との <code>this</code> の違いを知っておく</td></tr><tr><td>配列</td><td><code>map</code> / <code>filter</code> / <code>reduce</code> を使いこなす</td></tr><tr><td>オブジェクト</td><td>分割代入とスプレッド構文で扱いやすくなる</td></tr><tr><td>DOM・イベント ✨</td><td><code>querySelector</code> → <code>addEventListener</code> → <code>classList.toggle</code></td></tr><tr><td>非同期</td><td><code>async</code> / <code>await</code>  • <code>try</code> / <code>catch</code></td></tr><tr><td>モジュール</td><td><code>export</code> / <code>import</code> で分割し、<code>type=\"module\"</code> で読み込む</td></tr></table></div>"}, {"id": "db-01", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 1, "title": "データベースの基本用語", "summary": "データベース(DB)= データを整理して保存し、あとで探しやすくした「データの置き場所」 。ネットショップの商品一覧、SNSの投稿、学校の名簿などは、中身はすべてDBです。", "snippet": "{ id: 1, name: \"田中\", age: 25 },", "date": "2026-10-16", "min": 3, "html": "<p><b>データベース(DB)= データを整理して保存し、あとで探しやすくした「データの置き場所」</b>。ネットショップの商品一覧、SNSの投稿、学校の名簿などは、中身はすべてDBです。</p><div class=\"tbl\"><table><tr><th>困りごと(メモ帳やExcel)</th><th>DBなら</th></tr><tr><td>データが100万件あると探すのが遅い</td><td>一瞬で検索できる</td></tr><tr><td>複数人が同時に書き換えると壊れる</td><td>同時アクセスでも安全</td></tr><tr><td>間違ったデータ(年齢に「あ」など)が入る</td><td>ルール(制約)でブロックできる</td></tr><tr><td>PCが壊れたら全部消える</td><td>バックアップや復旧の仕組みがある</td></tr></table></div><h4>用語一覧</h4><div class=\"tbl\"><table><tr><th>言葉</th><th>意味</th><th>たとえると</th></tr><tr><td>データベース</td><td>データをまとめてしまう場所</td><td>本棚</td></tr><tr><td>テーブル</td><td>データを表の形で入れたもの</td><td>本棚の中の1冊のノート</td></tr><tr><td>カラム(列・フィールド)</td><td>表の「列」(名前、年齢などの項目)</td><td>ノートの見出し</td></tr><tr><td>レコード(行)</td><td>表の「行」(1件分のデータ)</td><td>ノートの1行</td></tr><tr><td>DBMS</td><td>DBを管理するソフト</td><td>倉庫番(管理人)</td></tr><tr><td>RDBMS</td><td><b>表の形</b>で管理し、表どうしをつなげられるDBMS(MySQLなど)</td><td>表で整理する倉庫番</td></tr><tr><td>SQL</td><td>DBに命令するための<b>言語</b></td><td>倉庫番へのお願いの言葉</td></tr><tr><td>クエリ</td><td>SQLで書いた1つの命令文</td><td>1つのお願い</td></tr></table></div><p>JavaScriptで例えると、テーブルは「同じ形のオブジェクトの配列」に近いものです。</p><div class=\"code\"><div class=\"code-head\"><span>javascript</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>[\n  { id: 1, name: &quot;田中&quot;, age: 25 },\n  { id: 2, name: &quot;佐藤&quot;, age: 30 },\n]</code></pre></div><h4>DBMS と RDBMS</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>DBMS(DBを管理するソフト全般)\n ├─ RDBMS(表形式で管理する)   ← いちばん主流。まずはこれを学ぶ\n └─ それ以外(NoSQLなど)\n      ├─ キー・バリュー型(Redis など)\n      ├─ ドキュメント型(MongoDB など)← JSONのような形で保存\n      └─ グラフ型(Neo4j など)</code></pre></div><p>RDBMSの土台は<b>関係モデル</b>(すべてのデータを表で表し、表どうしは共通の値でつなぐ)。1970年にE.F.コッドが提案。</p><h4>代表的なRDBMS</h4><div class=\"tbl\"><table><tr><th>名前</th><th>特徴</th><th>よく使われる場面</th></tr><tr><td><b>MySQL</b></td><td>無料、超定番、情報が多い</td><td>Webサービス、WordPress</td></tr><tr><td>PostgreSQL</td><td>無料、高機能、厳密</td><td>本格的なシステム</td></tr><tr><td>SQLite</td><td>ファイル1つで動く、インストールが簡単</td><td>スマホアプリ、学習、小規模ツール</td></tr><tr><td>MariaDB</td><td>MySQLから派生した無料版</td><td>MySQLの代わり</td></tr><tr><td>Oracle / SQL Server</td><td>有料・企業向け</td><td>銀行や大企業のシステム</td></tr></table></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li><b>SQL ≠ MySQL</b>。SQLは言語名、MySQLは製品名。</li><li>基本はどのRDBMSも同じだが、細かい書き方は製品ごとに違う(<b>方言</b>)。ネットのコードが動かないときは、どのRDBMS向けの情報か確認する。</li><li>「DB」はデータそのものも、管理ソフト(DBMS)も指すことがある。文脈で判断。</li></ul></div></div><h4>画面(HTML/CSS/JS)との位置関係</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>HTML/CSS/JS(画面側) → サーバー側のプログラム(PHP, Node.jsなど) → SQL → RDBMS</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p>ブラウザのJavaScriptから直接本番DBを操作する作りは危険(パスワードが丸見えになる)。必ずサーバー側を経由させる。</p></div></div>"}, {"id": "db-02", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 2, "title": "作業の準備:Docker → MySQLにログイン", "summary": "入れ物の中にさらに入っていくイメージ。出るときも exit で1段ずつ戻る。", "snippet": "PowerShell(自分のパソコン)", "date": "2026-10-16", "min": 3, "html": "<div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>PowerShell(自分のパソコン)\n  └ コンテナ(Docker)        ← docker exec で入る\n      └ MySQL               ← mysql -u ... で入る</code></pre></div><p>入れ物の中にさらに入っていくイメージ。出るときも <code>exit</code> で1段ずつ戻る。</p><div class=\"tbl\"><table><tr><th>言葉</th><th>意味</th><th>たとえると</th></tr><tr><td>🐳 イメージ</td><td>MySQLを動かすためのひな形</td><td>設計図</td></tr><tr><td>🐳 コンテナ</td><td>ひな形から実際に動かしたもの</td><td>設計図から建てた家</td></tr></table></div><h4>① コンテナを確認・起動する(PowerShellで打つ)</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>コマンド</th></tr><tr><td>動いているコンテナを見る</td><td><code>docker ps</code></td></tr><tr><td>止まっているものも含めて全部見る</td><td><code>docker ps -a</code></td></tr><tr><td>コンテナを起動する</td><td><code>docker start コンテナ名</code></td></tr><tr><td>コンテナを止める</td><td><code>docker stop コンテナ名</code></td></tr><tr><td>イメージ一覧を見る</td><td><code>docker images</code></td></tr><tr><td>イメージを削除する</td><td><code>docker rmi イメージ名</code></td></tr></table></div><p>コンテナ名は <code>docker ps -a</code> の一番右の <b>NAMES</b> 列。</p><div class=\"tbl\"><table><tr><th>STATUSの表示</th><th>状態</th><th>やること</th></tr><tr><td><code>Up …</code></td><td>動いている</td><td>そのまま <code>docker exec</code></td></tr><tr><td><code>Exited …</code></td><td>止まっている</td><td>先に <code>docker start コンテナ名</code></td></tr></table></div><h4>② MySQLにログインする</h4><p><b>まとめて1行で(おすすめ)</b></p><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>docker exec -it コンテナ名 mysql -u ユーザー名 -p -D データベース名</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>docker exec -it mysql-container mysql -u root -p\ndocker exec -it mysql-container mysql -u app_user -p -D sampleDB</code></pre></div><p><b>2段階で(先にコンテナに入る)</b></p><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>docker exec -it コンテナ名 bash\nmysql -u app_user -p -D sampleDB</code></pre></div><div class=\"tbl\"><table><tr><th>部分</th><th>意味</th></tr><tr><td><code>docker exec</code></td><td>動いているコンテナの中でコマンドを実行する</td></tr><tr><td><code>-it</code></td><td>対話モード(続けて入力できる状態)</td></tr><tr><td><code>bash</code></td><td>コンテナの中でコマンドを打てる画面を開く</td></tr><tr><td><code>mysql</code></td><td>MySQLに入るツール</td></tr><tr><td><code>-u ユーザー名</code></td><td>このユーザーで(<b>u</b>ser)</td></tr><tr><td><code>-p</code></td><td>パスワードを入力する(<b>p</b>assword)</td></tr><tr><td><code>-D データベース名</code></td><td>ログインと同時にこのDBを開く(<b>D</b>atabase)※省略OK</td></tr></table></div><p><code>mysql&gt;</code> と表示されればOK。管理作業(ユーザー作成など)は <code>-u root</code> で入る。</p><h4>③ 抜ける</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>exit   ← MySQLから抜ける(2段階で入った場合はコンテナの中に戻る)\nexit   ← コンテナから抜ける(PowerShellに戻る)</code></pre></div><p>まとめて1行でログインした場合は <code>exit</code> 1回でPowerShellに戻る。</p><h4>MySQLでまず覚える3つのルール</h4><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><ol><li><b>文の最後には必ず </b><b><code>;</code></b>。付け忘れると <code>-&gt;</code> と出て続きを待つ状態になる → <code>;</code> だけ打ってEnter</li><li><b>命令(SELECT、CREATEなど)は大文字でも小文字でもOK</b>。大文字にするのは「ここが命令」と分かりやすくするため</li><li><b>名前(DB名・テーブル名・パスワード)は作ったときと同じ書き方で打つ</b>(パスワードは大文字小文字を区別)</li></ol></div></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><ul><li><code>↑</code> キーで前に打ったSQLを呼び出せる。値だけ変えて再実行すると楽</li><li>✨ 途中まで打ってやり直したいときは、最後に <code>\\c</code> を付けてEnterするとその文がキャンセルされる</li><li>今どのユーザーかは <code>SELECT USER();</code>、どのDBを使っているかは <code>SELECT DATABASE();</code></li></ul></div></div>"}, {"id": "db-03", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 3, "title": "データベースとユーザーの操作", "summary": "最後に exit して、新しいユーザーでログインできるか試す。", "snippet": "CREATE USER 'app_user'@'localhost' IDENTIFIED BY 'pass1234';", "date": "2026-10-16", "min": 3, "html": "<h4>データベースの操作</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>コード</th></tr><tr><td>一覧を見る</td><td><code>SHOW DATABASES;</code></td></tr><tr><td>作る</td><td><code>CREATE DATABASE データベース名;</code></td></tr><tr><td>選ぶ(使う)</td><td><code>USE データベース名;</code></td></tr><tr><td>今選んでいるものを見る</td><td><code>SELECT DATABASE();</code></td></tr><tr><td>削除する</td><td><code>DROP DATABASE データベース名;</code> ⚠️ 戻せない</td></tr></table></div><h4>ユーザーの操作(rootでログインして打つ)</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>コード</th></tr><tr><td>ユーザー一覧を見る</td><td><code>SELECT user, host FROM mysql.user;</code></td></tr><tr><td>ユーザーを作る</td><td><code>CREATE USER 'ユーザー名'@'localhost' IDENTIFIED BY 'パスワード';</code></td></tr><tr><td>権限を与える</td><td><code>GRANT ALL PRIVILEGES ON DB名.* TO 'ユーザー名'@'localhost';</code></td></tr><tr><td>設定を読み込み直す</td><td><code>FLUSH PRIVILEGES;</code></td></tr><tr><td>権限を確認する</td><td><code>SHOW GRANTS FOR 'ユーザー名'@'localhost';</code></td></tr><tr><td>権限を取り消す</td><td><code>REVOKE ALL PRIVILEGES ON DB名.* FROM 'ユーザー名'@'localhost';</code></td></tr><tr><td>パスワードを変える</td><td><code>ALTER USER 'ユーザー名'@'localhost' IDENTIFIED BY '新パスワード';</code></td></tr><tr><td>ユーザーを削除する</td><td><code>DROP USER 'ユーザー名'@'localhost';</code></td></tr></table></div><h4>新しいユーザーを追加する手順</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- ① rootでログインした状態で\n-- ② ユーザーを作る\nCREATE USER &#x27;app_user&#x27;@&#x27;localhost&#x27; IDENTIFIED BY &#x27;pass1234&#x27;;\n-- ③ 権限を与える\nGRANT ALL PRIVILEGES ON sampleDB.* TO &#x27;app_user&#x27;@&#x27;localhost&#x27;;\n-- ④ 読み込み直す\nFLUSH PRIVILEGES;\n-- ⑤ 確認する\nSHOW GRANTS FOR &#x27;app_user&#x27;@&#x27;localhost&#x27;;</code></pre></div><p>最後に <code>exit</code> して、新しいユーザーでログインできるか試す。</p><h4>GRANTの読み方</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>GRANT  ALL PRIVILEGES  ON  sampleDB.*            TO  &#x27;app_user&#x27;@&#x27;localhost&#x27;;\n与える  すべての権限を   どこの  sampleDBの全テーブル  誰に  app_userに</code></pre></div><ul><li>覚え方:「<b>与える・何を・どこの・誰に</b>」</li><li><code>.</code> の前 = DB名、<code>.</code> の後 = テーブル名(<code>*</code> は全部)</li><li><code>CREATE USER</code> の中では <code>-p</code> は使えない。パスワードは <code>IDENTIFIED BY</code></li></ul><div class=\"tbl\"><table><tr><th>権限</th><th>できること</th></tr><tr><td><code>SELECT</code></td><td>データを見る(「見るだけ」ならこれだけ)</td></tr><tr><td><code>INSERT</code></td><td>データを追加する</td></tr><tr><td><code>UPDATE</code></td><td>データを変更する</td></tr><tr><td><code>DELETE</code></td><td>データを削除する</td></tr><tr><td><code>ALL PRIVILEGES</code></td><td>全部</td></tr></table></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>ユーザー作成・権限付与は <b>root でログインしてから</b>(app_userだと ERROR 1227)</li><li><b>GRANTは存在しないDB名(</b><b><code>pravtice</code></b><b> など)でもwarningだけで通ってしまう</b>。間違えたら <code>REVOKE</code> で取り消す</li><li>warningの中身は <code>SHOW WARNINGS;</code> で見られる。Warning 1285はDockerのMySQLでよく出るもので、<code>'localhost'</code> なら気にしなくてOK</li><li><code>FLUSH PRIVILEGES</code> は「保存」ではなく「読み込み直し」。GRANTの時点で保存は済んでいる</li></ul></div></div>"}, {"id": "db-04", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 4, "title": "テーブル設計の考え方", "summary": "注文データを1つの表にまとめると…", "snippet": "customers(客)              orders(注文)", "date": "2026-10-16", "min": 3, "html": "<h4>なぜ表を分けるのか</h4><p>注文データを1つの表にまとめると…</p><div class=\"tbl\"><table><tr><th>注文ID</th><th>客の名前</th><th>客の住所</th><th>商品</th></tr><tr><td>1</td><td>田中</td><td>東京都…</td><td>ペン</td></tr><tr><td>2</td><td>田中</td><td>東京都…</td><td>ノート</td></tr><tr><td>3</td><td>田中</td><td>東京都…</td><td>消しゴム</td></tr></table></div><ul><li>田中さんの住所が<b>何回も重複</b>している</li><li>引っ越したら<b>全部の行を直す</b>必要がある。直し忘れると矛盾が起きる</li></ul><p>→ <b>表を分けて、共通の値(ID)でつなぐ</b>。これがリレーションの考え方。(重複をなくすよう表を分ける作業 = <b>正規化</b> → 詳しくは16章)</p><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>customers(客)              orders(注文)\nid | name | address         id | customer_id | product\n1  | 田中 | 東京都…  ←──── 1  | 1           | ペン\n                      ←──── 2  | 1           | ノート\n                      ←──── 3  | 1           | 消しゴム</code></pre></div><p>住所は1か所にしかないので、<b>直すのも1か所だけ</b>。</p><h4>主キー(PRIMARY KEY)= 行の背番号</h4><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>その行をただ1つに特定するための列。</b> ルールは ①重複しない ②空っぽ(NULL)にできない。人間でいえばマイナンバー、学校でいえば出席番号。</p></div></div><ul><li>名前やメールアドレスを主キーにしない(重複・変更の可能性)</li><li>意味を持たない<b>連番ID</b>が定番。MySQLでは <code>AUTO_INCREMENT</code> で自動採番</li><li>主キーの値はあとから変更しない(ほかの表から参照されているため)</li></ul><h4>外部キー(FOREIGN KEY)= ほかの表へのつながり</h4><p><b>ほかの表の主キーを参照する列</b>。上の例の <code>orders.customer_id</code> が外部キーで、<code>customers.id</code> を指しています。</p><ul><li>存在しない客(id=999)の注文は<b>登録できない</b>(ERROR 1452)</li><li>注文が残っている客を消そうとすると<b>止めてくれる</b>(設定による)</li><li>カラム名は「<b>つなぐ先のテーブル名(単数形)_id</b>」にするのが一般的(<code>user_id</code>、<code>article_id</code>)</li></ul><h4>関係の種類</h4><div class=\"tbl\"><table><tr><th>種類</th><th>例</th><th>作り方</th></tr><tr><td>1対1</td><td>ユーザー ⇔ 詳細プロフィール</td><td>外部キーに <code>UNIQUE</code> を付ける(まず「1つの表で十分では?」と考える)</td></tr><tr><td><b>1対多</b>(一番多い)</td><td>1人のユーザー → 複数の記事</td><td><b>「多」の側に外部キーを置く</b>(articles に <code>user_id</code>)</td></tr><tr><td>多対多</td><td>記事 ⇔ タグ、生徒 ⇔ 授業</td><td><b>中間テーブル</b>を作る(post_tags に <code>post_id</code> と <code>tag_id</code>)</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><ul><li>1対多の外部キーを<b>「1」の側に置く</b>のはよくある間違い(客の表に「注文ID1, 注文ID2…」と並べるなど)</li><li><b>1つのマスには1つの値だけ</b>。「趣味:サッカー,読書」のようなカンマ区切りはNG(検索できなくなる)</li><li><b>1つのテーブルには1種類のものだけ</b>。ユーザーと商品を混ぜない</li></ul></div></div><h4>設計のチェックリスト(作る前に紙に書き出す)</h4><ul><li class=\"chk\">何を管理するか(ユーザー、商品、注文…)</li><li class=\"chk\">それぞれ何の情報を持つか(列)</li><li class=\"chk\">どう識別するか(主キー:たいてい <code>id</code>)</li><li class=\"chk\">表どうしの関係(1対1?1対多?多対多?)</li><li class=\"chk\">各列の型(数値?文字?日付?)</li><li class=\"chk\">ルール(空でもよいか?重複してもよいか?)</li><li class=\"chk\">名前の付け方を統一(テーブル名は英語の複数形 <code>users</code>、列名は小文字+アンダーバー <code>created_at</code>)</li></ul><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p>表を作ったあとで構造を変えるのは大変(データが入っているため)。分けすぎるとJOINが複雑になるので、まずは<b>「同じ情報が何度も出てくるなら分ける」</b>を目安に。</p></div></div>"}, {"id": "db-05", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 5, "title": "列の型と制約", "summary": "VARCHAR = var iable(変わる)+ char acter(文字)。入れた文字の長さに合わせて場所を使う。", "snippet": "", "date": "2026-10-16", "min": 3, "html": "<h4>よく使う型</h4><div class=\"tbl\"><table><tr><th>型</th><th>入れるもの</th><th>例</th></tr><tr><td><code>INT</code></td><td>整数</td><td>年齢、個数、ID</td></tr><tr><td><code>DECIMAL(10,2)</code></td><td>正確な小数</td><td>金額</td></tr><tr><td><code>FLOAT</code> / <code>DOUBLE</code></td><td>おおよその小数</td><td>測定値</td></tr><tr><td><code>VARCHAR(255)</code></td><td>短い文字(最大255文字)</td><td>名前、タイトル、メール</td></tr><tr><td><code>TEXT</code></td><td>長い文章</td><td>本文、自己紹介</td></tr><tr><td><code>BOOLEAN</code></td><td>真偽(true/false。MySQLでは中身は 1/0)</td><td>公開済みか</td></tr><tr><td><code>DATE</code></td><td>日付</td><td>2026-10-09</td></tr><tr><td><code>DATETIME</code> / <code>TIMESTAMP</code></td><td>日付と時間</td><td>2026-10-09 15:00:00</td></tr></table></div><p><code>VARCHAR</code> = <b>var</b>iable(変わる)+ <b>char</b>acter(文字)。入れた文字の長さに合わせて場所を使う。</p><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><ul><li><b>お金に </b><b><code>FLOAT</code></b><b> を使わない</b>(計算誤差が出る。JSの <code>0.1 + 0.2 = 0.30000000000000004</code> と同じ)。<code>DECIMAL</code> か、円なら <code>INT</code></li><li><b>電話番号・郵便番号は文字列型</b>(数値型だと先頭の0が消える)。「計算しないものは文字列」</li><li>日付を <code>VARCHAR</code> で保存しない(並べ替えや期間検索がうまくいかない)</li></ul></div></div><h4>制約(データのルール)</h4><p>「この列にはこういうデータしか入れてはいけない」というルール。DBMSが門番になって違反データをエラーで拒否してくれます(プログラム側のチェック漏れを防ぐ最後の砦)。</p><div class=\"tbl\"><table><tr><th>制約</th><th>意味</th><th>書き方</th><th>注意点</th></tr><tr><td><code>PRIMARY KEY</code></td><td>重複禁止+空っぽ禁止</td><td><code>id INT AUTO_INCREMENT PRIMARY KEY</code></td><td>1テーブルに1つ(複数列の組み合わせ=複合主キーは可)</td></tr><tr><td><code>NOT NULL</code></td><td>空っぽ禁止</td><td><code>title VARCHAR(255) NOT NULL</code></td><td>空文字 <code>''</code> は入ってしまう。必須項目には付ける</td></tr><tr><td><code>UNIQUE</code></td><td>重複禁止</td><td><code>email VARCHAR(255) NOT NULL UNIQUE</code></td><td>NULLは複数入る。空も禁止なら <code>NOT NULL</code> とセット</td></tr><tr><td><code>FOREIGN KEY</code></td><td>他の表にある値だけ</td><td><code>FOREIGN KEY (user_id) REFERENCES users(id)</code></td><td>参照先と型を合わせる。参照される側を先に作る</td></tr><tr><td><code>CHECK</code></td><td>自分で決めた条件</td><td><code>age INT CHECK (age &gt;= 0)</code></td><td>MySQL 8.0.16より前では書いても無視される</td></tr><tr><td><code>DEFAULT</code></td><td>何も指定しないときの初期値</td><td><code>created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP</code></td><td>明示的に NULL を入れると NULL になる</td></tr></table></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><b>外部キーの削除時の動き(ON DELETE)</b></p><ul><li><code>RESTRICT</code>:子があれば親を削除できない(安全。指定しないときはこれと同じ動き)</li><li><code>CASCADE</code>:親を消すと子も一緒に消える(便利だが、意図せず大量に消えることも)</li><li><code>SET NULL</code>:子の外部キーを空にする</li></ul></div></div><h4>NULL とは</h4><p><b>NULL = 「値がない・不明」という特別な状態。</b></p><ul><li>NULL と空文字 <code>''</code> と <code>0</code> はすべて別物</li><li>カラムを後から追加すると、今ある行のそのカラムは全部 NULL になる</li><li>検索のしかたは 8章「NULL の探し方」へ</li></ul>"}, {"id": "db-06", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 6, "title": "テーブルの作成・確認・変更", "summary": "列を増やす = ALTER TABLE / 行を増やす = INSERT / 行を書き換える = UPDATE", "snippet": "CREATE TABLE users (", "date": "2026-10-16", "min": 4, "html": "<h4>テーブルの操作一覧</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>コード</th></tr><tr><td>一覧を見る</td><td><code>SHOW TABLES;</code>(先に <code>USE DB名;</code>)</td></tr><tr><td>列の形を見る</td><td><code>DESC テーブル名;</code></td></tr><tr><td>作ったときのSQL(外部キー含む)を見る</td><td><code>SHOW CREATE TABLE テーブル名;</code></td></tr><tr><td>作る</td><td><code>CREATE TABLE テーブル名 (列名 型, ...);</code></td></tr><tr><td>列を追加する(末尾)</td><td><code>ALTER TABLE テーブル名 ADD COLUMN 列名 型;</code></td></tr><tr><td>○○の後ろに列を追加</td><td><code>ALTER TABLE テーブル名 ADD COLUMN 列名 型 AFTER ○○;</code></td></tr><tr><td>一番前に列を追加</td><td><code>ALTER TABLE テーブル名 ADD COLUMN 列名 型 FIRST;</code></td></tr><tr><td>✨ 列の型や設定を変える</td><td><code>ALTER TABLE テーブル名 MODIFY COLUMN 列名 新しい型;</code></td></tr><tr><td>✨ 列の名前を変える</td><td><code>ALTER TABLE テーブル名 RENAME COLUMN 旧名 TO 新名;</code></td></tr><tr><td>列を削除する</td><td><code>ALTER TABLE テーブル名 DROP COLUMN 列名;</code></td></tr><tr><td>外部キーを後から追加</td><td>下のコード</td></tr><tr><td>テーブルを削除する</td><td><code>DROP TABLE テーブル名;</code> ⚠️ 戻せない</td></tr></table></div><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>列を増やす = </b><b><code>ALTER TABLE</code></b><b> / 行を増やす = </b><b><code>INSERT</code></b><b> / 行を書き換える = </b><b><code>UPDATE</code></b></p></div></div><h4>テーブルを作る例</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>CREATE TABLE users (\n  id         INT AUTO_INCREMENT PRIMARY KEY,      -- 自動で 1,2,3… と番号が増える\n  name       VARCHAR(255) NOT NULL,               -- 名前は必須\n  email      VARCHAR(255) NOT NULL UNIQUE,        -- 必須&amp;重複禁止\n  age        INT CHECK (age &gt;= 0),                -- マイナス禁止\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP  -- 自動で日時\n);\n\nCREATE TABLE articles (\n  id      INT AUTO_INCREMENT PRIMARY KEY,\n  title   VARCHAR(255) NOT NULL,\n  body    TEXT NOT NULL,\n  user_id INT NOT NULL,                           -- 誰の記事か(「多」側に置く)\n  FOREIGN KEY (user_id) REFERENCES users(id)\n);</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>列と列の間は <code>,</code> で区切る。<b>最後の列には </b><b><code>,</code></b><b> を付けない</b>(付けると ERROR 1064)</li><li>途中で改行してもOK。<code>;</code> を打つまでが1つの命令</li><li>参照される側(users)を<b>先に</b>作る。削除するときは逆の順番</li><li>全部 VARCHAR にせず、入れるものに合わせて型を選ぶ。外部キーはつなぐ先(INT)と同じ型</li><li>実際のサービスでは、パスワードはそのまま保存せず<b>ハッシュ化</b>して保存する</li></ul></div></div><h4>外部キーを後から追加する</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>ALTER TABLE comments\nADD CONSTRAINT fk_comments_article\nFOREIGN KEY (article_id) REFERENCES articles(id);</code></pre></div><div class=\"tbl\"><table><tr><th>部品</th><th>例1</th><th>例2</th></tr><tr><td>変更するテーブル</td><td>articles</td><td>comments</td></tr><tr><td>ルールの名前</td><td>fk_articles_user</td><td>fk_comments_article</td></tr><tr><td>外部キーにする列</td><td>user_id</td><td>article_id</td></tr><tr><td>つなぐ先</td><td>users(id)</td><td>articles(id)</td></tr></table></div><p>確認は <code>SHOW CREATE TABLE comments;</code></p><h4>DESC の結果の読み方</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>+---------+--------------+------+-----+---------+----------------+\n| Field   | Type         | Null | Key | Default | Extra          |\n+---------+--------------+------+-----+---------+----------------+\n| id      | int          | NO   | PRI | NULL    | auto_increment |\n| title   | varchar(255) | NO   |     | NULL    |                |\n| user_id | int          | NO   | MUL | NULL    |                |\n+---------+--------------+------+-----+---------+----------------+</code></pre></div><div class=\"tbl\"><table><tr><th>列</th><th>意味</th></tr><tr><td>Field / Type</td><td>カラム名 / データ型</td></tr><tr><td>Null</td><td>空っぽを許すか(NO = 禁止)</td></tr><tr><td>Key</td><td>PRI = 主キー、UNI = UNIQUE、✨ MUL = 外部キーなど(重複ありの索引)</td></tr><tr><td>Default</td><td>何も入れなかったときに入る値</td></tr><tr><td>Extra</td><td>auto_increment = 自動で番号が増える</td></tr></table></div>"}, {"id": "db-07", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 7, "title": "データの操作(INSERT / UPDATE / DELETE)", "summary": "列名は必ず書く。 どの値がどの列に入るか一目で分かり、idなど書かなくていい列を省け、列が増えても壊れない。列名の順番と値の順番・数をそろえる。", "snippet": "INSERT INTO users (name, email, age) VALUES ('山田太郎', 'yamada@example.com', 20);", "date": "2026-10-16", "min": 4, "html": "<div class=\"tbl\"><table><tr><th>やりたいこと</th><th>命令</th><th>型</th></tr><tr><td>➕ 追加する</td><td>INSERT</td><td><code>INSERT INTO テーブル (列1, 列2) VALUES (値1, 値2);</code></td></tr><tr><td>👀 見る</td><td>SELECT</td><td><code>SELECT 列 FROM テーブル WHERE 条件;</code>(8章)</td></tr><tr><td>✏️ 変更する</td><td>UPDATE</td><td><code>UPDATE テーブル SET 列 = 値 WHERE 条件;</code></td></tr><tr><td>🗑️ 削除する</td><td>DELETE</td><td><code>DELETE FROM テーブル WHERE 条件;</code></td></tr></table></div><h4>INSERT(追加)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- 1件\nINSERT INTO users (name, email, age) VALUES (&#x27;山田太郎&#x27;, &#x27;yamada@example.com&#x27;, 20);\n\n-- まとめて複数件\nINSERT INTO articles (title, body, user_id) VALUES\n(&#x27;タイトル1&#x27;, &#x27;本文1&#x27;, 1),\n(&#x27;タイトル2&#x27;, &#x27;本文2&#x27;, 2),\n(&#x27;タイトル3&#x27;, &#x27;本文3&#x27;, 3);</code></pre></div><ul><li>文字は <code>' '</code> で囲む、数字はそのまま</li><li>id(AUTO_INCREMENT)は書かなくてOK</li><li><code>( )</code> 1つが1件分。1件ごとに <code>,</code> でつなぎ、<b>最後だけ </b><b><code>;</code></b></li><li><code>Query OK, 3 rows affected</code> = 3件入った</li></ul><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>列名は必ず書く。</b> どの値がどの列に入るか一目で分かり、idなど書かなくていい列を省け、列が増えても壊れない。列名の順番と値の順番・数をそろえる。</p></div></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p>複数行 INSERT は、1行でも間違いがあると<b>全部入らない</b>(エラーで 0件)。</p></div></div><h4>UPDATE(もうある行を書き換える)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>UPDATE users SET age = 21 WHERE id = 1;\n\n-- 複数の列を一度に(区切りは , )\nUPDATE articles\nSET title = &#x27;新しいタイトル&#x27;, body = &#x27;新しい本文&#x27;\nWHERE id = 1;</code></pre></div><p><b>後から追加した列にデータを入れる手順</b>(追加しただけだと中身は全部 NULL)</p><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT id, name, name_kana FROM users;                          -- ① 誰が何番か確認\nUPDATE users SET name_kana = &#x27;ひらおかしんいち&#x27; WHERE id = 1;    -- ② 1人ずつ\nUPDATE users SET name_kana = &#x27;こにししおん&#x27; WHERE id = 2;\nSELECT id, name, name_kana FROM users;                          -- ③ 確認</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><ul><li>複数列の区切りを <code>AND</code> にすると、エラーにならずにおかしな値が入ることがある(<code>SET title = 'A' AND body = 'B'</code> ✕)</li><li>users の番号は <code>id</code>(<code>user_id</code> ではない)。どのテーブルの列かを意識する</li></ul></div></div><h4>DELETE(削除)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>DELETE FROM users WHERE id = 1;</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>UPDATE と DELETE は WHERE を忘れると全部の行が変わる/消える!</b> MySQLにはゴミ箱がないので、消したものは基本的に戻せません。</p><ul><li><code>DELETE FROM articles WHERE id = 1;</code> → 1件消える</li><li><code>DELETE FROM articles WHERE user_id = 1;</code> → その人の記事が<b>全部</b>消える</li><li><code>DELETE FROM articles;</code> → <b>全部消える</b></li></ul></div></div><h4>安全な手順:先に SELECT で確かめる</h4><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><ol><li><b>同じ WHERE で SELECT</b> して、対象の行を確認する → <code>SELECT * FROM articles WHERE id = 1;</code></li><li>正しければ、<code>SELECT *</code> の部分だけ書き換えて実行 → <code>DELETE FROM articles WHERE id = 1;</code></li><li><b>結果の件数を見る</b> → <code>Query OK, 1 row affected</code>。思っていた件数と違ったら要注意</li></ol><p>1件だけ変えたいときは<b>id(主キー)で指定</b>するのが一番安全(名前だと同姓同名が全員変わる)。</p></div></div><h4>論理削除(消さずに「消した印」を付ける)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>ALTER TABLE articles ADD COLUMN deleted_at DATETIME;          -- 印用の列を用意\n\nUPDATE articles SET deleted_at = NOW() WHERE id = 1;          -- 消す(DELETEの代わり)\nSELECT * FROM articles WHERE deleted_at IS NULL;              -- 消していないものだけ見る\nUPDATE articles SET deleted_at = NULL WHERE id = 1;           -- 戻す</code></pre></div><div class=\"tbl\"><table><tr><th></th><th>物理削除(DELETE)</th><th>論理削除(UPDATEで印)</th></tr><tr><td>元に戻せる</td><td>✕</td><td>○</td></tr><tr><td>いつ消したか分かる</td><td>✕</td><td>○(deleted_atに日時が残る)</td></tr><tr><td>注意</td><td>戻せない</td><td>SELECTで毎回 <code>deleted_at IS NULL</code> を付けないと、消したはずのものが出てくる</td></tr></table></div><p><code>NOW()</code> = 今の日時。印は <code>is_deleted</code>(0か1)のような列で表すこともある。</p>"}, {"id": "db-08", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 8, "title": "SELECTでデータを探す", "summary": "覚え方:「 何を・どこから・どれを・どう並べて・何件 」(順番を入れ替えると ERROR 1064)", "snippet": "SELECT 列名", "date": "2026-10-16", "min": 5, "html": "<h4>書く順番(入れ替え不可)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT 列名\nFROM テーブル名\nWHERE 条件\nORDER BY 並べる列\nLIMIT 件数;</code></pre></div><p>覚え方:「<b>何を・どこから・どれを・どう並べて・何件</b>」(順番を入れ替えると ERROR 1064)</p><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT * FROM users;                       -- 全部の列(* は確認用)\nSELECT name, age FROM users;               -- name と age だけ</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><code>SELECT *</code> は練習や確認ではOK。本番のプログラムでは<b>必要な列だけ書く</b>のが基本(余計なデータを取らない、列が増えても影響を受けない)。</p></div></div><h4>WHEREで使う条件</h4><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th></tr><tr><td><code>age = 20</code></td><td>20と同じ</td></tr><tr><td><code>age != 20</code> / <code>age &lt;&gt; 20</code></td><td>20じゃない(<code>&lt;&gt;</code> がSQLの標準)</td></tr><tr><td><code>age &gt; 20</code></td><td>20より大きい(<b>20は含まない</b>)</td></tr><tr><td><code>age &gt;= 20</code></td><td>20以上(<b>20を含む</b>)</td></tr><tr><td><code>age &lt; 20</code></td><td>20未満(<b>20は含まない</b>)</td></tr><tr><td><code>age &lt;= 20</code></td><td>20以下(<b>20を含む</b>)</td></tr><tr><td><code>age BETWEEN 20 AND 30</code></td><td>20以上30以下(両端を含む)</td></tr><tr><td><code>id IN (1, 3, 5)</code></td><td>1か3か5(<code>OR</code> を何個も書くより短い)</td></tr><tr><td><code>id NOT IN (1, 2)</code></td><td>1と2以外</td></tr><tr><td><code>条件A AND 条件B</code></td><td>A かつ B</td></tr><tr><td><code>条件A OR 条件B</code></td><td>A または B</td></tr></table></div><h4>文字の条件</h4><ul><li>文字は必ず <code>' '</code> で囲む(<code>WHERE name = '平岡新一'</code>)。数字は囲まない</li><li>全角と半角は別物(<code>'ABC'</code> と <code>'ＡＢＣ'</code> は一致しない)</li><li>余計なスペースもデータ(<code>'平岡 新一'</code> と <code>'平岡新一'</code> は一致しない)</li><li>文字の中に <code>'</code> を入れたいときは <code>''</code>(2つ重ねる):<code>'Let''s SQL'</code></li></ul><h4>LIKE(あいまい検索)</h4><p><code>=</code> は<b>完全に同じ</b>でないと見つからない(データが「東京都」だと <code>= '東京'</code> では0件)。</p><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th><th>「大阪府」は見つかる?</th></tr><tr><td><code>= '大阪府'</code></td><td>完全に同じ</td><td>○</td></tr><tr><td><code>LIKE '大阪%'</code></td><td>大阪で<b>始まる</b></td><td>○</td></tr><tr><td><code>LIKE '%大阪'</code></td><td>大阪で<b>終わる</b></td><td>✕</td></tr><tr><td><code>LIKE '%大阪%'</code></td><td>大阪をどこかに<b>含む</b></td><td>○</td></tr><tr><td><code>LIKE '平岡__'</code></td><td><code>_</code> はちょうど1文字(平岡+2文字)</td><td>—</td></tr><tr><td><code>NOT LIKE '%SQL%'</code></td><td>SQLを含まない</td><td>—</td></tr></table></div><p><code>%</code> = 何文字でもOK(0文字も含む)。注意:<code>LIKE '%○○%'</code> はデータが多いと遅くなりやすい。</p><h4>AND と OR を混ぜるとき</h4><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>AND は OR より先に計算される</b>(かけ算がたし算より先なのと同じ)。迷ったら必ず <code>( )</code> を付ける。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- ✕ 「東京の人全員」または「大阪の20歳以上」になってしまう\nWHERE birthplace = &#x27;東京&#x27; OR birthplace = &#x27;大阪&#x27; AND age &gt;= 20;\n\n-- ○ 「東京か大阪で、しかも20歳以上」\nWHERE (birthplace = &#x27;東京&#x27; OR birthplace = &#x27;大阪&#x27;) AND age &gt;= 20;</code></pre></div><h4>NULL の探し方</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>WHERE name_kana = NULL       -- ✕ 何も見つからない(エラーにもならないので気づきにくい)\nWHERE name_kana IS NULL      -- ○ 空っぽの行\nWHERE name_kana IS NOT NULL  -- ○ 何か入っている行</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><p><code>!=</code> や <code>&lt;&gt;</code> でも NULL の行は出てこない。<code>WHERE birthplace &lt;&gt; '東京'</code> だと出身地が NULL の人は結果に入らない → 入れたいときは <code>OR birthplace IS NULL</code> を足す。</p></div></div><h4>並べ替え(ORDER BY)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT * FROM users ORDER BY age;              -- 小さい順(ASC。省略可)\nSELECT * FROM users ORDER BY age DESC;         -- 大きい順\nSELECT * FROM users ORDER BY birthplace, age DESC;  -- 出身地で並べ、同じ中では年齢の大きい順</code></pre></div><p>ORDER BY がないと表示の順番は<b>決まっていない</b>。id順に見たいときは <code>ORDER BY id</code>。</p><h4>件数をしぼる(LIMIT / OFFSET)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT * FROM articles ORDER BY id DESC LIMIT 3;          -- 新しい順に3件\nSELECT * FROM articles ORDER BY id LIMIT 3 OFFSET 3;      -- 3件飛ばして次の3件(4〜6件目)</code></pre></div><p>LIMIT は <b>ORDER BY とセット</b>で使う(ないとどの3件が出るか決まらない)。OFFSETはページ分けで使う。</p><h4>別名(AS)と重複なし(DISTINCT)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT title AS タイトル, body AS 本文 FROM articles;   -- 表示だけ変わる(列名は変わらない)\nSELECT DISTINCT birthplace FROM users;                 -- どんな値が入っているか一覧で見る</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p>条件を書く前に <code>SELECT DISTINCT 列名 FROM テーブル;</code> で実際の値(「大阪」なのか「大阪府」なのか)を確認すると、「0件になる」ミスが減ります。</p></div></div>"}, {"id": "db-09", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 9, "title": "JOIN:テーブルをつなげて見る", "summary": "この章と次の章の例で使うテーブル:", "snippet": "products(商品)                          reviews(レビュー)", "date": "2026-10-16", "min": 6, "html": "<p>この章と次の章の例で使うテーブル:</p><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>products(商品)                          reviews(レビュー)\nid | name       | price | category      id | body           | rating | product_id\n1  | ボールペン | 150   | 文房具        1  | 書きやすい     | 5      | 1\n2  | ノート     | 200   | 文房具        3  | 紙がなめらか   | 4      | 2\n3  | 消しゴム   | 120   | 文房具        4  | 子どもが喜んだ | 5      | 4\n4  | けん玉     | 800   | おもちゃ      5  | ふわふわ…      | 4      | 5\n5  | ぬいぐるみ | 1500  | おもちゃ      6  | 思ったより…    | 3      | 6\n6  | マグカップ | 1200  | NULL\n7  | 万年筆     | 3000  | 文房具\n8  | パズル     | 950   | おもちゃ</code></pre></div><h4>なぜ JOIN が必要?</h4><p>reviews には「どの商品か」が<b>番号(product_id)でしか入っていない</b>。商品名は products にある。</p><p>→ <b>2つのテーブルを product_id と id でつなげれば、レビューと商品名を一緒に見られる。</b> テーブルは分けて保存して(4章)、見るときに JOIN でつなぐのが基本。</p><h4>INNER JOIN(内部結合)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT r.body AS レビュー, p.name AS 商品名\nFROM reviews AS r\nINNER JOIN products AS p ON r.product_id = p.id;</code></pre></div><p>&gt; 「reviews と products を、product_id と id が同じもの同士でつないで、本文と商品名を見せて」</p><div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><ul><li><b>ON = つなぐ条件</b>。ほとんどの場合「<b>子の外部キー = 親の id</b>」の形</li><li><b>WHERE = つないだ結果からしぼる条件</b>(<code>WHERE r.rating &gt;= 4</code> など)</li><li><code>reviews AS r</code> で短い別名を付ける(<code>AS</code> は省略可)。別名を付けたら、そのSQLの中は別名で統一</li><li><code>INNER</code> は省略できる(<code>JOIN</code> だけでも INNER JOIN)</li></ul></div></div><p><b>INNER JOIN で出る行 = 両方のテーブルに相手がいる行だけ</b></p><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>ボールペン(1) ─── 書きやすい\nノート(2)     ─── 紙がなめらか\n消しゴム(3)   ✕ レビューなし → 出てこない\nけん玉(4)     ─── 子どもが喜んだ\nぬいぐるみ(5) ─── ふわふわ…\nマグカップ(6) ─── 思ったより…\n万年筆(7)     ✕ 出てこない\nパズル(8)     ✕ 出てこない</code></pre></div><ul><li>1つの商品にレビューが2件あれば、その商品は<b>2行</b>出てくる</li><li>出てこない行は、テーブルから消えたわけではない</li></ul><h4>3つ以上つなぐ</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT c.body AS コメント, a.title AS 記事, u.name AS 著者\nFROM comments c\nINNER JOIN articles a ON c.article_id = a.id\nINNER JOIN users u ON a.user_id = u.id;</code></pre></div><p><code>JOIN ... ON ...</code> を<b>1つずつ足していく</b>。2つ目の ON は、すでにつないだテーブル(a)と新しいテーブル(u)をつなぐ。</p><h4>LEFT JOIN(外部結合):左は全部出す</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT p.name, r.body\nFROM products p\nLEFT JOIN reviews r ON p.id = r.product_id;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>ボールペン | 書きやすい\nノート     | 紙がなめらか\n消しゴム   | NULL          ← レビューなしでも出る(右側は NULL で埋まる)\n…\n万年筆     | NULL\nパズル     | NULL</code></pre></div><p><b>「左」= FROM の後ろのテーブル(全部出す)、「右」= LEFT JOIN の後ろのテーブル(あれば出す)</b></p><div class=\"tbl\"><table><tr><th></th><th>INNER JOIN</th><th>LEFT JOIN</th></tr><tr><td>出る行</td><td>両方に相手がいる行だけ</td><td>左は全部 + 右は相手がいれば</td></tr><tr><td>相手がいない行</td><td>出ない</td><td>右側が NULL で出る</td></tr><tr><td>上の例の行数</td><td>5行</td><td>8行</td></tr><tr><td>イメージ</td><td>2つの円の重なった部分だけ</td><td>左の円まるごと</td></tr></table></div><h4>相手がいないものを探す(LEFT JOIN + IS NULL)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT p.name\nFROM products p\nLEFT JOIN reviews r ON p.id = r.product_id\nWHERE r.id IS NULL;            -- → 消しゴム / 万年筆 / パズル</code></pre></div><p>右テーブルの <b>id(主キー)</b> で <code>IS NULL</code> を見るのが確実(id は必ず値が入っているので、NULL なら「相手なし」と言い切れる)。</p><p><b>RIGHT JOIN</b> は左右が逆なだけ。テーブルの順番を入れ替えて LEFT JOIN で書くほうが読みやすいので、<b>「全部出したいテーブルを FROM に書いて LEFT JOIN」に統一</b>するのがおすすめ。</p><h4>どの JOIN を使う?</h4><div class=\"tbl\"><table><tr><th>やりたいこと</th><th>使うもの</th><th>実務の例</th></tr><tr><td>番号を名前にして見たい</td><td>INNER JOIN</td><td>記事一覧に著者名、注文一覧に商品名</td></tr><tr><td>相手がいなくても全部出したい</td><td>LEFT JOIN</td><td>全商品の一覧にレビュー数(0件も表示)</td></tr><tr><td>相手がいないものを探したい</td><td>LEFT JOIN + <code>WHERE 右.id IS NULL</code></td><td>一度も注文していないお客さん</td></tr></table></div><h4>JOIN のよくあるミス</h4><div class=\"tbl\"><table><tr><th>ミス</th><th>どうなる</th><th>対策</th></tr><tr><td>ON を書き忘れる</td><td>全部の組み合わせ(8×5=40行など)が出る</td><td>JOIN を書いたら必ず ON</td></tr><tr><td>ON の列を間違える(<code>r.id = p.id</code>)</td><td>エラーにならず、おかしな組み合わせになる</td><td>ON は「外部キー = つなぐ先の id」</td></tr><tr><td>両方にある列名(id、name)にテーブル名を付けない</td><td>ERROR 1052(ambiguous)</td><td><code>別名.列名</code> で書く</td></tr><tr><td>別名を付けたのに元の名前で書く</td><td>ERROR 1054(Unknown column)</td><td>別名で統一</td></tr><tr><td><code>JOIN</code> の前に <code>,</code> を付ける</td><td>ERROR 1064</td><td>FROM / JOIN / ON / WHERE の間に <code>,</code> は不要</td></tr><tr><td>LEFT JOIN したのに WHERE で右の列をしぼる</td><td>NULL の行が消えて INNER JOIN と同じになる</td><td>右の条件は ON に書く(<code>ON p.id = r.product_id AND r.rating &gt;= 4</code>)</td></tr><tr><td>全部出したいほうを右に書く</td><td>欲しい行が出ない</td><td>全部出したいテーブルを FROM の後ろ(左)に</td></tr></table></div>"}, {"id": "db-10", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 10, "title": "集約:数える・合計する・グループごとにまとめる", "summary": "たくさんの行を、1つの数字にまとめること。 「全部で何件?」「合計は?」「〇〇ごとに?」と聞かれたら集約。", "snippet": "SELECT COUNT(*) AS 商品数, AVG(price) AS 平均価格, MAX(price) AS 最高値", "date": "2026-10-16", "min": 4, "html": "<p><b>たくさんの行を、1つの数字にまとめること。</b>「全部で何件?」「合計は?」「〇〇ごとに?」と聞かれたら集約。</p><h4>集計関数</h4><div class=\"tbl\"><table><tr><th>関数</th><th>意味</th><th>例</th><th>結果(products)</th></tr><tr><td><code>COUNT(*)</code></td><td>行の<b>数</b></td><td><code>SELECT COUNT(*) FROM products;</code></td><td>8</td></tr><tr><td><code>COUNT(列)</code></td><td>その列が <b>NULL でない</b>行の数</td><td><code>SELECT COUNT(category) FROM products;</code></td><td>7</td></tr><tr><td><code>SUM(列)</code></td><td><b>合計</b></td><td><code>SELECT SUM(price) FROM products;</code></td><td>7920</td></tr><tr><td><code>AVG(列)</code></td><td><b>平均</b></td><td><code>SELECT AVG(price) FROM products;</code></td><td>990.0000</td></tr><tr><td><code>MAX(列)</code></td><td><b>最大</b></td><td><code>SELECT MAX(price) FROM products;</code></td><td>3000</td></tr><tr><td><code>MIN(列)</code></td><td><b>最小</b></td><td><code>SELECT MIN(price) FROM products;</code></td><td>120</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT COUNT(*) AS 商品数, AVG(price) AS 平均価格, MAX(price) AS 最高値\nFROM products;</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li><code>COUNT(*)</code> は NULL も含めて全行、<code>COUNT(列)</code> は NULL の行を数えない</li><li>SUM / AVG / MAX / MIN は <b>NULL を無視</b>して計算する(AVG は NULL を0としてではなく、除いて平均)</li><li><code>COUNT (*)</code> のように関数名と <code>(</code> の間にスペースを入れない</li><li>✨ 平均の小数を整えたいときは <code>ROUND(AVG(price), 1)</code>(小数第1位まで)</li></ul></div></div><h4>WHERE と組み合わせる(しぼってから集計)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT COUNT(*) AS 文房具の数, AVG(price) AS 平均価格\nFROM products\nWHERE category = &#x27;文房具&#x27;;         -- → 4 / 867.5</code></pre></div><h4>GROUP BY(グループごとに集計)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT category, COUNT(*) AS 商品数, AVG(price) AS 平均価格\nFROM products\nGROUP BY category;</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>GROUP BY category = 同じ値のものを箱に分けて、箱ごとに数える\n\n [文房具の箱]        [おもちゃの箱]       [NULLの箱]\n ボールペン 150      けん玉     800       マグカップ 1200\n ノート     200      ぬいぐるみ 1500\n 消しゴム   120      パズル     950\n 万年筆     3000\n   ↓                   ↓                    ↓\n COUNT = 4           COUNT = 3            COUNT = 1</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>SELECT に書ける列は、GROUP BY に書いた列か、集計関数だけ。</b></p><p><code>SELECT category, name, COUNT(*) FROM products GROUP BY category;</code> → ERROR 1055(文房具の箱に4つあるのに name を1つだけ出せと言われても決められない)</p></div></div><h4>HAVING(グループにまとめた後でしぼる)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT category, COUNT(*) AS 商品数\nFROM products\nWHERE price &gt;= 500                -- ① 500円以上の行だけにして\nGROUP BY category                 -- ② category ごとに箱に分けて\nHAVING COUNT(*) &gt;= 2;             -- ③ 2つ以上ある箱だけ残す</code></pre></div><div class=\"tbl\"><table><tr><th></th><th>WHERE</th><th>HAVING</th></tr><tr><td>しぼるタイミング</td><td>グループに<b>分ける前</b></td><td>グループに<b>分けた後</b></td></tr><tr><td>しぼるもの</td><td>1行1行</td><td>グループ(集計結果)</td></tr><tr><td>集計関数(COUNTなど)</td><td>使えない(ERROR 1111)</td><td>使える</td></tr></table></div><h4>書く順番と、MySQLが動く順番</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT 列名\nFROM テーブル\nJOIN テーブル ON 条件\nWHERE 条件\nGROUP BY 列名\nHAVING 条件\nORDER BY 列名\nLIMIT 件数;</code></pre></div><p>覚え方:「<b>何を・どこから・つないで・しぼって・まとめて・箱をしぼって・並べて・何件</b>」</p><p>WHERE で集計関数が使えないのは、②の時点ではまだ箱に分けていないから。SELECT で付けた別名(<code>AS 商品数</code>)は ORDER BY では使えるが WHERE では使えない。</p>"}, {"id": "db-11", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 11, "title": "JOIN と集約を組み合わせる", "summary": "LEFT JOIN + COUNT(*) のワナ :レビューのない消しゴムも LEFT JOIN すると「消しゴム | NULL」の1行がある。", "snippet": "SELECT a.title, COUNT(c.id) AS コメント数", "date": "2026-10-16", "min": 2, "html": "<div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- 記事ごとのコメント数(0件の記事も出す)\nSELECT a.title, COUNT(c.id) AS コメント数\nFROM articles a\nLEFT JOIN comments c ON a.id = c.article_id\nGROUP BY a.id, a.title;\n\n-- 商品ごとの平均評価とレビュー数\nSELECT p.name, AVG(r.rating) AS 平均評価, COUNT(r.id) AS レビュー数\nFROM products p\nINNER JOIN reviews r ON p.id = r.product_id\nGROUP BY p.id, p.name;\n\n-- 著者ごとの記事数(多い順)\nSELECT u.name AS 著者, COUNT(a.id) AS 記事数\nFROM users u\nLEFT JOIN articles a ON u.id = a.user_id\nGROUP BY u.id, u.name\nORDER BY 記事数 DESC;\n\n-- 記事が2件以上ある著者だけ\nSELECT u.name AS 著者, COUNT(a.id) AS 記事数\nFROM users u\nINNER JOIN articles a ON u.id = a.user_id\nGROUP BY u.id, u.name\nHAVING COUNT(a.id) &gt;= 2;</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><p><b>LEFT JOIN + COUNT(*) のワナ</b>:レビューのない消しゴムも LEFT JOIN すると「消しゴム | NULL」の1行がある。</p><p><code>COUNT(*)</code> → 1(行があるので数える)✕ / <code>COUNT(r.id)</code> → 0(NULL は数えない)○</p><p>→ <b>LEFT JOIN で数えるときは </b><b><code>COUNT(右テーブルの id)</code></b></p></div></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>INNER JOIN では「0件のもの」はJOINの時点で消えている → 0件も出したいなら LEFT JOIN</li><li>GROUP BY に名前だけ書くと、同姓同名がまとめられてしまう → <code>GROUP BY u.id, u.name</code> と id も入れる</li></ul></div></div>"}, {"id": "db-12", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 12, "title": "実務で役立つ追加テクニック", "summary": "( ) の中が先に実行され、その結果を外側のSQLが使う。", "snippet": "SELECT name, price", "date": "2026-10-16", "min": 2, "html": "<h4>サブクエリ(SQLの中にSQL)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- 平均価格より高い商品\nSELECT name, price\nFROM products\nWHERE price &gt; (SELECT AVG(price) FROM products);\n\n-- レビューが1件でもある商品(IN と組み合わせ)\nSELECT name FROM products\nWHERE id IN (SELECT product_id FROM reviews);</code></pre></div><p><code>( )</code> の中が先に実行され、その結果を外側のSQLが使う。</p><h4>日付の扱い</h4><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th></tr><tr><td><code>NOW()</code></td><td>今の日時</td></tr><tr><td><code>CURDATE()</code></td><td>今日の日付</td></tr><tr><td><code>DATE_FORMAT(created_at, '%Y-%m')</code></td><td>「2026-10」の形に整える(月ごとの集計に使う)</td></tr><tr><td><code>WHERE created_at &gt;= '2026-10-01'</code></td><td>10月1日以降</td></tr><tr><td><code>WHERE created_at &gt;= NOW() - INTERVAL 7 DAY</code></td><td>直近7日間</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- 月ごとの記事数\nSELECT DATE_FORMAT(created_at, &#x27;%Y-%m&#x27;) AS 月, COUNT(*) AS 記事数\nFROM articles\nGROUP BY 月\nORDER BY 月;</code></pre></div><h4>CASE(条件によって表示を変える)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>SELECT name, price,\n  CASE\n    WHEN price &gt;= 1000 THEN &#x27;高い&#x27;\n    WHEN price &gt;= 500  THEN &#x27;ふつう&#x27;\n    ELSE &#x27;安い&#x27;\n  END AS 価格帯\nFROM products;</code></pre></div><h4>トランザクション(まとめて成功 or まとめて取り消し → 詳しくは17章)</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>START TRANSACTION;\nUPDATE articles SET deleted_at = NOW() WHERE user_id = 1;\nSELECT * FROM articles WHERE user_id = 1;   -- 結果を確認\nROLLBACK;   -- 間違っていたら取り消し(なかったことになる)\n-- COMMIT;  -- 正しければ確定</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><p><b>練習中の大量 UPDATE / DELETE の保険になる。</b> <code>START TRANSACTION;</code> の後の変更は、<code>COMMIT;</code> するまで確定しない。ただし <code>CREATE TABLE</code> や <code>ALTER TABLE</code> などテーブルの形を変える命令は取り消せない。</p></div></div><h4>SQLファイルをまとめて実行する</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>mysql&gt; SOURCE /パス/02_practice.sql;</code></pre></div><p>答えのSQLをファイルにまとめておけば、1行で全部流せる(Dockerの場合はコンテナの中にあるパスを指定)。</p>"}, {"id": "db-13", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 13, "title": "エラー早見表", "summary": "エラー 意味 直し方 10061(A5:SQL Mk-2) MySQLが動いていない docker ps で確認して docker start 用語 ‘docekr’ は認識されません コマンドのつづりミス docker のつづりを確認 N", "snippet": "", "date": "2026-10-16", "min": 2, "html": "<div class=\"tbl\"><table><tr><th>エラー</th><th>意味</th><th>直し方</th></tr><tr><td>10061(A5:SQL Mk-2)</td><td>MySQLが動いていない</td><td><code>docker ps</code> で確認して <code>docker start</code></td></tr><tr><td>用語 ‘docekr’ は認識されません</td><td>コマンドのつづりミス</td><td><code>docker</code> のつづりを確認</td></tr><tr><td>No such container</td><td>その名前のコンテナがない</td><td><code>docker ps -a</code> の NAMES 列で確認</td></tr><tr><td>ERROR 1045</td><td>ユーザー名かパスワードが違う</td><td>打ち間違い(大文字小文字)を確認</td></tr><tr><td>ERROR 1046</td><td>データベースが選ばれていない</td><td>先に <code>USE データベース名;</code></td></tr><tr><td>ERROR 1048</td><td>NOT NULL の列が空っぽ</td><td>その列の値を入れる</td></tr><tr><td>ERROR 1050</td><td>そのテーブルはもうある</td><td><code>SHOW TABLES;</code> で確認。作り直すなら <code>DROP TABLE</code></td></tr><tr><td>ERROR 1052</td><td>列名があいまい(どのテーブルの id?)</td><td><code>別名.列名</code> で書く</td></tr><tr><td>ERROR 1054</td><td>そんな列はない(Unknown column)</td><td>列名のつづり・別名を確認。<code>DESC</code> で列名を見る</td></tr><tr><td>ERROR 1055</td><td>GROUP BY にない列を SELECT した</td><td>GROUP BY の列か集計関数だけにする</td></tr><tr><td><b>ERROR 1064</b></td><td><b>書き方のミス(一番多い)</b></td><td><code>;</code> <code>' '</code> <code>,</code> の抜け・余計な <code>,</code>・順番・つづりを確認</td></tr><tr><td>ERROR 1111</td><td>WHERE に集計関数を書いた</td><td>HAVING に書く</td></tr><tr><td>ERROR 1146</td><td>そのテーブルが存在しない</td><td><code>SHOW TABLES;</code> で名前を確認(<code>user</code> → <code>users</code> など)</td></tr><tr><td>✨ ERROR 1205</td><td>ロック待ちが長すぎて時間切れ</td><td>他の画面で開始したままのトランザクションを COMMIT / ROLLBACK(18章)</td></tr><tr><td>✨ ERROR 1213</td><td>デッドロック(片方が自動で取り消された)</td><td>もう一度実行。更新の順番をそろえる(18章)</td></tr><tr><td>ERROR 1227</td><td>その操作の権限がない</td><td>root でログインし直す</td></tr><tr><td>ERROR 1396</td><td>そのユーザーはもう存在する</td><td><code>SELECT user, host FROM mysql.user;</code> で確認</td></tr><tr><td>ERROR 1406</td><td>文字が長すぎる</td><td>VARCHAR の最大文字数を確認</td></tr><tr><td>ERROR 1410</td><td>GRANT の宛先ユーザーが存在しない</td><td>先に CREATE USER。名前のつづりを確認</td></tr><tr><td>ERROR 1452</td><td>外部キー違反(存在しない番号を入れた)</td><td>つなぐ先に、その id があるか確認</td></tr><tr><td>Warning 1285</td><td>Docker の MySQL の設定による注意</td><td><code>'localhost'</code> なら気にしなくてOK</td></tr></table></div>"}, {"id": "db-14", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 14, "title": "迷ったときの選び方", "summary": "やりたいこと 使うもの 列を増やす・形を変える ALTER TABLE 行を増やす INSERT もうある行を書き換える UPDATE(WHERE 必須) 行を消す DELETE(WHERE 必須・先に SELECT)/ 戻したいなら論理削", "snippet": "書く順番:SELECT → FROM → JOIN → ON → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT", "date": "2026-10-16", "min": 1, "html": "<div class=\"tbl\"><table><tr><th>やりたいこと</th><th>使うもの</th></tr><tr><td>列を増やす・形を変える</td><td>ALTER TABLE</td></tr><tr><td>行を増やす</td><td>INSERT</td></tr><tr><td>もうある行を書き換える</td><td>UPDATE(WHERE 必須)</td></tr><tr><td>行を消す</td><td>DELETE(WHERE 必須・先に SELECT)/ 戻したいなら論理削除</td></tr><tr><td>番号を名前にして見たい</td><td>INNER JOIN</td></tr><tr><td>相手がいなくても全部出したい</td><td>LEFT JOIN</td></tr><tr><td>相手がいないものを探したい</td><td>LEFT JOIN + <code>WHERE 右.id IS NULL</code></td></tr><tr><td>全部で何件・合計・平均・最大・最小</td><td>COUNT / SUM / AVG / MAX / MIN</td></tr><tr><td>〇〇ごとに集計したい</td><td>GROUP BY</td></tr><tr><td>行をしぼってから集計 / 集計結果でしぼる</td><td>WHERE / HAVING</td></tr><tr><td>✨ 同じ情報が何度も出てくる表を直したい</td><td>正規化(16章)</td></tr><tr><td>✨ 複数の変更をまとめて確定・取り消ししたい</td><td>START TRANSACTION / COMMIT / ROLLBACK(17章)</td></tr><tr><td>✨ 同時に在庫などを減らしても壊れないようにしたい</td><td><code>stock = stock - 1</code> の条件付きUPDATE / FOR UPDATE(18章)</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>書く順番:SELECT → FROM → JOIN → ON → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT</code></pre></div>"}, {"id": "db-15", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 15, "title": "正規化:同じ情報は1か所にだけ書く", "summary": "正規化 = 表を分けて、同じ情報が何度も出てこないようにすること。 ゴールは「直すときに1か所だけ直せばいい」状態。", "snippet": "users(id, name, age, birthplace)        ← ユーザーの情報は1か所だけ", "date": "2026-10-16", "min": 3, "html": "<div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>正規化 = 表を分けて、同じ情報が何度も出てこないようにすること。</b> ゴールは「直すときに1か所だけ直せばいい」状態。</p></div></div><h4>なぜ必要?(重複があると起きる3つの事故)</h4><div class=\"tbl\"><table><tr><th>事故</th><th>何が起きる?</th><th>例(1つの表に「注文・客・商品」を全部入れた場合)</th></tr><tr><td>💥 更新の事故</td><td>直し忘れで、データが食い違う</td><td>田中さんの住所を3行中2行だけ直した → どれが正しい?</td></tr><tr><td>💥 追加の事故</td><td>入れたいのに入れられない</td><td>まだ注文がない新商品は、商品名や値段を登録できない</td></tr><tr><td>💥 削除の事故</td><td>消したくない情報まで消える</td><td>田中さんの注文を消したら、田中さんの住所も消えた</td></tr></table></div><h4>正規化の3ステップ</h4><div class=\"tbl\"><table><tr><th>段階</th><th>ルール(これだけ覚える)</th><th>やること</th><th>合言葉</th></tr><tr><td>🟥 非正規形</td><td>1つのマスに値が2つ以上ある</td><td>(スタート地点)</td><td>—</td></tr><tr><td>🟨 <b>第1正規形</b></td><td><b>1マス1つの値</b></td><td>繰り返しを行に分ける</td><td>「1マス1つ」</td></tr><tr><td>🟦 <b>第2正規形</b></td><td>主キーの<b>一部だけ</b>で決まる列がない</td><td>その列を別の表へ</td><td>「キー<b>全体</b>で決まる」</td></tr><tr><td>🟩 <b>第3正規形</b></td><td>主キー<b>以外</b>の列で決まる列がない</td><td>その列を別の表へ</td><td>「キー<b>だけ</b>で決まる」</td></tr></table></div><div class=\"co co-purple\"><span class=\"co-i\">🧠</span><div class=\"co-b\"><p><b>覚え方:「1マス1つ、キー全体に、キーだけに」</b></p><p>すべての列が「主キー全体に、主キーだけに」くっついていれば第3正規形。</p></div></div><h4>「〜で決まる」(関数従属)とは?</h4><p><b>Aが分かれば、Bが1つに決まる</b>こと。「客ID → 客名」(C1 なら必ず田中)、「商品ID → 単価」(P1 なら必ず100円)。</p><div class=\"tbl\"><table><tr><th>主キー</th><th>列</th><th>何で決まる?</th><th>判定</th></tr><tr><td>注文ID+商品ID</td><td>個数</td><td>注文ID と 商品ID の<b>両方</b></td><td>✅ OK(キー全体)</td></tr><tr><td>注文ID+商品ID</td><td>商品名・単価</td><td>商品ID <b>だけ</b></td><td>🟦 第2正規形で追い出す</td></tr><tr><td>注文ID+商品ID</td><td>客ID</td><td>注文ID <b>だけ</b></td><td>🟦 第2正規形で追い出す</td></tr><tr><td>注文ID</td><td>客名</td><td>客ID(キーではない列)</td><td>🟩 第3正規形で追い出す</td></tr></table></div><h4>例のテーブルで見ると</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>users(id, name, age, birthplace)        ← ユーザーの情報は1か所だけ\narticles(id, title, body, user_id)      ← 著者名は書かず、user_id でつなぐ\ncomments(id, body, article_id)          ← 記事タイトルは書かず、article_id でつなぐ</code></pre></div><p>articles に著者名を直接書いていないのは、第3正規形の考え方そのもの。名前が変わっても users を1か所直すだけで済み、JOIN で毎回最新の名前が出る。</p><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li>実務では<b>第3正規形まで</b>できていれば十分なことが多い</li><li>分けすぎると JOIN だらけになって遅く・読みにくくなる。速さのためにわざと重複を残すこともある(<b>非正規化</b>)</li><li>✨ <b>注文時の値段</b>は注文明細にコピーして残すのが正解。商品の値段が後で変わっても、過去の注文金額が変わらないようにするため(「重複=全部ダメ」ではない)</li></ul></div></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><ul><li>「趣味:サッカー,読書」のようなカンマ区切り → 第1正規形違反。別テーブル(user_hobbies)にする</li><li>「商品1, 商品2, 商品3」のように列を番号で増やす → これも繰り返し。行に分ける</li></ul></div></div><details class=\"tg\"><summary>確認クイズ ▶ 開いて答え合わせ</summary><p><b>Q1.</b> 1つのマスに「東京,大阪」と入っている。何正規形違反? → <b>第1正規形</b>(1マス1つにする)</p><p><b>Q2.</b> 主キーが(生徒ID+授業ID)の表に「生徒名」がある。何を直す? → 生徒名は生徒ID<b>だけ</b>で決まるので、<b>第2正規形</b>で students 表へ</p><p><b>Q3.</b> 社員表(主キー:社員ID)に「部署ID」と「部署名」がある。何を直す? → 部署名は部署ID(キー以外)で決まるので、<b>第3正規形</b>で departments 表へ</p></details>"}, {"id": "db-16", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 16, "title": "トランザクション:まとめて成功 or まとめて取り消し", "summary": "トランザクション = 「ここからここまでは1つの作業」とまとめること。 途中で失敗したら全部なかったことにできる。", "snippet": "START TRANSACTION;", "date": "2026-10-16", "min": 3, "html": "<div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>トランザクション = 「ここからここまでは1つの作業」とまとめること。</b> 途中で失敗したら全部なかったことにできる。</p></div></div><h4>使う命令は3つだけ</h4><div class=\"tbl\"><table><tr><th>命令</th><th>意味</th><th>たとえると</th></tr><tr><td><code>START TRANSACTION;</code>(または <code>BEGIN;</code>)</td><td>ここから1つの作業として始める</td><td>ゲームの<b>セーブポイント</b>を作る</td></tr><tr><td><code>COMMIT;</code></td><td>全部確定する</td><td><b>セーブする</b></td></tr><tr><td><code>ROLLBACK;</code></td><td>START からの変更を全部取り消す</td><td>セーブせずに<b>やり直す</b></td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>START TRANSACTION;\n\nUPDATE accounts SET balance = balance - 1000 WHERE name = &#x27;A&#x27;;   -- ① Aから引く\nUPDATE accounts SET balance = balance + 1000 WHERE name = &#x27;B&#x27;;   -- ② Bに足す\n\nSELECT * FROM accounts;   -- 確認(この時点ではまだ自分にしか見えない)\n\nCOMMIT;     -- 正しければ確定\n-- ROLLBACK;  -- おかしければ取り消し</code></pre></div><h4>ACID:トランザクションが守る4つの約束</h4><div class=\"tbl\"><table><tr><th>文字</th><th>名前</th><th>ひとことで</th><th>例</th></tr><tr><td>🔵 <b>A</b></td><td>原子性(Atomicity)</td><td><b>全部か、ゼロか</b></td><td>①だけ成功して②が失敗、は起きない</td></tr><tr><td>🟢 <b>C</b></td><td>一貫性(Consistency)</td><td><b>ルールを破らない</b></td><td>外部キー・NOT NULL などの制約違反は確定されない</td></tr><tr><td>🟡 <b>I</b></td><td>独立性(Isolation)</td><td><b>同時でも混ざらない</b></td><td>他の人のCOMMIT前の変更は見えない(18章)</td></tr><tr><td>🟣 <b>D</b></td><td>永続性(Durability)</td><td><b>確定したら消えない</b></td><td>COMMIT後に停電しても、データは残る</td></tr></table></div><h4>オートコミット(MySQLのいつもの動き)</h4><ul><li>MySQLは普段、<b>1文ごとに自動でCOMMIT</b>している(オートコミット)。だから今までの UPDATE や DELETE は、打った瞬間に確定していた</li><li><code>START TRANSACTION;</code> を打つと、COMMIT か ROLLBACK するまで自動確定が止まる</li><li>今の設定は <code>SELECT @@autocommit;</code> で確認(1 = オン)</li></ul><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><ul><li><b>練習中の UPDATE / DELETE の保険</b>:先に <code>START TRANSACTION;</code> → 実行 → SELECT で確認 → OK なら COMMIT、ダメなら ROLLBACK</li><li>A5:SQL Mk-2 の「トランザクション開始」ボタンも同じ仕組み。開始したら、最後に<b>コミット</b>か<b>ロールバック</b>のボタンを押して終わらせる</li><li>SELECT だけならデータは変わらないので、トランザクションは不要</li></ul></div></div><div class=\"co co-yellow\"><span class=\"co-i\">🟨</span><div class=\"co-b\"><ul><li><code>CREATE TABLE</code> / <code>ALTER TABLE</code> / <code>DROP TABLE</code> など<b>表の形を変える命令は取り消せない</b>(実行した時点で自動COMMITされる)</li><li>トランザクションは<b>短く</b>。開始したまま放置すると、他の人の作業を待たせる(18章のロック)</li><li>COMMIT を忘れて接続を切ると、その変更は取り消される</li></ul></div></div><details class=\"tg\"><summary>確認クイズ ▶ 開いて答え合わせ</summary><p><b>Q1.</b> START TRANSACTION → DELETE → ROLLBACK。データはどうなる? → <b>消えていない</b>(DELETE がなかったことになる)</p><p><b>Q2.</b> START TRANSACTION → ALTER TABLE で列を追加 → ROLLBACK。列は? → <b>残る</b>(ALTER は取り消せない)</p><p><b>Q3.</b> 「振込で引き出しだけ成功した」を防ぐのは ACID のどれ? → <b>A(原子性)</b></p></details>"}, {"id": "db-17", "page": "DB（MySQL）まとめ", "cat": "db", "ch": 17, "title": "同時実行制御:みんなで同時に使っても壊さない", "summary": "同時実行制御 = たくさんの人が同時に同じデータを読み書きしても、結果がおかしくならないようにする仕組み。 主役は ロック(鍵) 。", "snippet": "UPDATE products SET stock = stock - 1 WHERE id = 1 AND stock > 0;", "date": "2026-10-16", "min": 5, "html": "<div class=\"co co-blue\"><span class=\"co-i\">🟦</span><div class=\"co-b\"><p><b>同時実行制御 = たくさんの人が同時に同じデータを読み書きしても、結果がおかしくならないようにする仕組み。</b> 主役は<b>ロック(鍵)</b>。</p></div></div><h4>同時に動くと起きる4つの問題</h4><div class=\"tbl\"><table><tr><th>問題</th><th>ひとことで</th><th>例</th></tr><tr><td>💥 <b>ロストアップデート</b>(更新の消失)</td><td>後から書いた人に<b>上書きされて消える</b></td><td>在庫1個を2人が同時に買えてしまう(上の図)</td></tr><tr><td>💥 <b>ダーティリード</b></td><td>COMMIT前の<b>途中の値</b>を読んでしまう</td><td>ROLLBACK されて実際には存在しない値を見る</td></tr><tr><td>💥 <b>ノンリピータブルリード</b></td><td>同じ行を2回読むと<b>値が変わっている</b></td><td>1回目は在庫5個、2回目は3個</td></tr><tr><td>💥 <b>ファントムリード</b></td><td>同じ条件で2回読むと<b>行が増えている</b></td><td>1回目は記事10件、2回目は11件(幽霊=ファントムが出る)</td></tr></table></div><h4>ロックの種類</h4><div class=\"tbl\"><table><tr><th>種類</th><th>他の人は読める?</th><th>他の人は書ける?</th><th>たとえると</th><th>書き方</th></tr><tr><td>🔓 <b>共有ロック</b>(読むための鍵)</td><td>○</td><td>✕(待つ)</td><td>図書館の本を<b>みんなで閲覧</b>中。書き込みは禁止</td><td><code>SELECT ... FOR SHARE;</code></td></tr><tr><td>🔒 <b>排他ロック</b>(書くための鍵)</td><td>ロック付きの読み取りは✕(待つ)</td><td>✕(待つ)</td><td>トイレの<b>鍵</b>。使い終わるまで他の人は入れない</td><td><code>SELECT ... FOR UPDATE;</code> / UPDATE・DELETE は自動</td></tr></table></div><ul><li>ロックは <b>COMMIT か ROLLBACK で外れる</b></li><li>MySQL(InnoDB)では、ロックの付いていない普通の <code>SELECT</code> は待たずに「COMMIT済みの値」を読める</li></ul><h4>在庫を安全に減らす2つの書き方</h4><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- ① いちばん簡単:引き算をDBにまかせる(「残っていれば」の条件付き)\nUPDATE products SET stock = stock - 1 WHERE id = 1 AND stock &gt; 0;\n-- → 1 row affected なら購入成功、0 rows なら売り切れ\n\n-- ② 確認してから更新したいとき:FOR UPDATE で鍵をかける\nSTART TRANSACTION;\nSELECT stock FROM products WHERE id = 1 FOR UPDATE;   -- 🔒 他の人はここで待つ\nUPDATE products SET stock = stock - 1 WHERE id = 1;\nCOMMIT;                                               -- 🔓 鍵が外れる</code></pre></div><h4>悲観ロックと楽観ロック</h4><div class=\"tbl\"><table><tr><th></th><th>🔒 悲観ロック</th><th>🔖 楽観ロック</th></tr><tr><td>考え方</td><td>「<b>きっと</b>ぶつかる」→ 先に鍵をかける</td><td>「<b>たぶん</b>ぶつからない」→ 保存のときだけチェック</td></tr><tr><td>やり方</td><td><code>SELECT ... FOR UPDATE</code></td><td><code>version</code> 列を用意して、保存時に変わっていないか確認</td></tr><tr><td>ぶつかったら</td><td>相手は待たされる</td><td>後から保存した人がエラー → やり直し</td></tr><tr><td>向いている場面</td><td>在庫・座席予約・お金</td><td>ブログ記事の編集・プロフィール更新</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>-- 楽観ロックの例(読んだときの version が 3 だった)\nUPDATE articles\nSET body = &#x27;新しい本文&#x27;, version = version + 1\nWHERE id = 1 AND version = 3;\n-- 0 rows affected → 誰かが先に更新していた → 「他の人が編集しました」と表示</code></pre></div><h4>分離レベル(どこまで「混ざらない」を守るか)</h4><div class=\"tbl\"><table><tr><th>分離レベル</th><th>ダーティリード</th><th>ノンリピータブルリード</th><th>ファントムリード</th><th>速さ</th></tr><tr><td>READ UNCOMMITTED</td><td>💥 起きる</td><td>💥 起きる</td><td>💥 起きる</td><td>速い</td></tr><tr><td>READ COMMITTED</td><td>✅</td><td>💥 起きる</td><td>💥 起きる</td><td>↓</td></tr><tr><td><b>REPEATABLE READ</b>(MySQLの初期設定)</td><td>✅</td><td>✅</td><td>△(MySQLでは普通の読み取りなら起きない)</td><td>↓</td></tr><tr><td>SERIALIZABLE</td><td>✅</td><td>✅</td><td>✅</td><td>遅い</td></tr></table></div><p>上に行くほど速いけど危ない、下に行くほど安全だけど待ちが増える。<b>まずは初期設定のままでOK。</b> 確認は <code>SELECT @@transaction_isolation;</code></p><h4>デッドロック(お互いに待ち続ける)</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Aさん:商品1に🔒 → 次に商品2が欲しい …… Bを待つ\nBさん:商品2に🔒 → 次に商品1が欲しい …… Aを待つ\n→ 永遠に終わらない! MySQLが気づいて、片方を自動で ROLLBACK する(ERROR 1213)</code></pre></div><div class=\"co co-green\"><span class=\"co-i\">🟩</span><div class=\"co-b\"><ul><li><b>更新する順番をそろえる</b>(いつも id の小さい順など)とデッドロックが起きにくい</li><li>トランザクションは短く。ユーザーの入力待ちの間にロックを持ち続けない</li><li>ERROR 1213 や 1205 が出たら、<b>もう一度実行し直せばよい</b>ことが多い</li></ul></div></div><div class=\"co co-red\"><span class=\"co-i\">🟥</span><div class=\"co-b\"><ul><li>「SELECT で在庫を確認 → アプリで計算 → UPDATE」を<b>ロックなし</b>でやると、ロストアップデートが起きる</li><li><code>FOR UPDATE</code> は <b>トランザクションの中で</b>使う(オートコミットのままだと、1文ごとにすぐ鍵が外れて意味がない)</li></ul></div></div><details class=\"tg\"><summary>確認クイズ ▶ 開いて答え合わせ</summary><p><b>Q1.</b> AさんとBさんが同時に編集して、Aさんの変更が消えた。この問題の名前は? → <b>ロストアップデート</b></p><p><b>Q2.</b> 座席予約で「残り1席」を確実に1人だけにしたい。悲観・楽観どっち? → <b>悲観ロック</b>(<code>FOR UPDATE</code>)</p><p><b>Q3.</b> MySQLの初期設定の分離レベルは? → <b>REPEATABLE READ</b></p><p><b>Q4.</b> お互いのロックを待ち合って止まる状態は? → <b>デッドロック</b>(MySQLが片方を ROLLBACK)</p></details><h4>3つの関係まとめ</h4><div class=\"tbl\"><table><tr><th>テーマ</th><th>守るもの</th><th>ひとことで</th></tr><tr><td>🗂️ 正規化</td><td><b>設計</b>(表の形)</td><td>同じ情報は1か所に</td></tr><tr><td>📦 トランザクション</td><td><b>1人の作業</b></td><td>全部成功か、全部なかったことに</td></tr><tr><td>🚦 同時実行制御</td><td><b>みんなの作業</b></td><td>同時でも、順番待ちで正しく</td></tr></table></div>"}, {"id": "java1-01", "page": "Java 基礎編", "cat": "java", "ch": 1, "title": "実行のしかた（PowerShell・ターミナル）", "summary": "javac でコンパイル → java で実行 。コードを書き換えたら、毎回 javac からやり直す。", "snippet": "javac -encoding UTF-8 Main.java              // コンパイル（Main.class ができる）", "date": "2026-10-28", "min": 2, "html": "<div class=\"co co-gray\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>javac でコンパイル → java で実行</b>。コードを書き換えたら、毎回 javac からやり直す。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>javac -encoding UTF-8 Main.java              // コンパイル（Main.class ができる）\njava Main                                    // 実行（.java は付けない）\njava -encoding UTF-8 Main.java               // 1行でコンパイル＋実行（.class は作られない）\njavac -encoding UTF-8 Person.java Main.java  // ファイルが2つのときはまとめてコンパイル</code></pre></div><h4>守ること</h4><ul><li>ファイル名とクラス名は、大文字・小文字までそろえる（<code>public class Person</code> → <code>Person.java</code>）</li><li>1行目に VS Code が自動で入れた <code>package 〇〇;</code> があったら消す（<code>java クラス名</code> で動かなくなる。数字で始まるパッケージ名はエラー）</li><li>日本語を含むファイルは <code>-encoding UTF-8</code> を付ける</li></ul><h4>よく出たエラー</h4><div class=\"tbl\"><table><tr><th>表示</th><th>原因と直し方</th></tr><tr><td>ClassNotFoundException</td><td>javac していない／コンパイルが失敗している</td></tr><tr><td>エンコーディングwindows-31jにマップできません</td><td><code>-encoding UTF-8</code> の付け忘れ</td></tr><tr><td>実行結果が文字化け</td><td><code>java ファイル名.java</code> で実行するときも <code>-encoding UTF-8</code> を付ける</td></tr><tr><td>パッケージ〇〇は存在しません</td><td><code>System</code> などのつづりミス</td></tr><tr><td>シンボルが見つかりません</td><td>変数名・型名のつづり、大文字・小文字、import 忘れ</td></tr><tr><td>'.class'がありません</td><td>キャストの ( ) 忘れ（<code>int (…)</code> → <code>(int) (…)</code>）</td></tr><tr><td>全角スペース・全角記号</td><td>エラーになる。日本語入力をオフにして半角で打つ</td></tr></table></div><h4>フォルダの移動</h4><div class=\"tbl\"><table><tr><th>コマンド</th><th>動き</th></tr><tr><td><code>cd 〇〇</code></td><td>今のフォルダの中の〇〇に入る</td></tr><tr><td><code>cd ..</code></td><td>1つ上に戻る</td></tr><tr><td><code>cd ..\\〇〇</code></td><td>1つ上に戻って、隣の〇〇に入る</td></tr><tr><td><code>ls</code></td><td>今のフォルダの中身を見る</td></tr><tr><td><code>pwd</code></td><td>今いる場所を確認する</td></tr></table></div><ul><li>名前の途中まで打って Tabキーで補完できる</li><li>VS Code でフォルダを右クリック →「統合ターミナルで開く」で、そのフォルダから始められる</li></ul>"}, {"id": "java1-02", "page": "Java 基礎編", "cat": "java", "ch": 2, "title": "クラスとメソッド", "summary": "クラス ＝データ（フィールド）と操作（メソッド）をまとめた 設計図 。 インスタンス ＝設計図から作った実物。 Javaのプログラムはクラスという単位でできていて、クラスは class で定義する。インスタンスは クラス名 変数名 = ne", "snippet": "public class Car {", "date": "2026-10-28", "min": 6, "html": "<div class=\"co co-blue\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>クラス</b>＝データ（フィールド）と操作（メソッド）をまとめた<b>設計図</b>。<b>インスタンス</b>＝設計図から作った実物。<br>Javaのプログラムはクラスという単位でできていて、クラスは <code>class</code> で定義する。インスタンスは <code>クラス名 変数名 = new クラス名();</code> で作る。</p></div></div><h4>クラスの定義とインスタンス化</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class Car {\n    // フィールド（クラス内の変数）\n    private String brand;\n    private String color;\n\n    // コンストラクタ（インスタンスの初期化）\n    public Car(String brand, String color) {\n        this.brand = brand;\n        this.color = color;\n    }\n\n    // メソッド（クラス内の操作）\n    public void start()      { System.out.println(&quot;The car is starting.&quot;); }\n    public void accelerate() { System.out.println(&quot;The car is accelerating.&quot;); }\n    public void stop()       { System.out.println(&quot;The car has stopped.&quot;); }\n}\n\nCar myCar = new Car(&quot;Toyota&quot;, &quot;red&quot;);   // インスタンス化\nmyCar.start();</code></pre></div><h4>メソッドの形</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>戻り値の型 メソッド名(引数の型 引数名, ...) {\n    // 処理\n    return 戻り値;   // void の場合は不要\n}</code></pre></div><div class=\"tbl\"><table><tr><th>用語</th><th>意味</th></tr><tr><td>引数</td><td>メソッドに渡す値</td></tr><tr><td>戻り値</td><td>メソッドが返す結果</td></tr><tr><td>void</td><td>戻り値なし</td></tr><tr><td>オーバーロード</td><td>同じ名前で<b>引数の型や数が違う</b>メソッドを複数作ること</td></tr></table></div><h4>メソッドに分ける理由</h4><p><b>メソッド</b>＝クラスの中で実行される処理のまとまり。大きなプログラムをメソッドに分けると、<b>何度も使い回せて（再利用性）</b>、<b>読みやすく直しやすくなる（保守性）</b>。</p><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class MyClass {\n    public static void main(String[] args) {   // プログラムの入口\n        int sum = calculateSum(5, 10);         // 計算は別のメソッドに任せる\n        displayResult(sum);                    // 表示も別のメソッドに任せる\n    }\n\n    public static int calculateSum(int num1, int num2) {   // 引数を受け取って、戻り値を返す\n        return num1 + num2;\n    }\n\n    public static void displayResult(int result) {\n        System.out.println(&quot;Sum: &quot; + result);\n    }\n}</code></pre></div><h4>オーバーロード</h4><p>同じ名前のメソッドを、<b>引数の型や個数を変えて</b>いくつも作れる。呼び出すときに渡した引数に合うものが自動で選ばれる。</p><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class Calculator {\n    public int add(int num1, int num2)            { return num1 + num2; }\n    public double add(double num1, double num2)   { return num1 + num2; }\n    public int add(int num1, int num2, int num3)  { return num1 + num2 + num3; }\n}\n\nCalculator calculator = new Calculator();\nint result1 = calculator.add(5, 10);        // int を2つ → 1つ目の add\ndouble result2 = calculator.add(2.5, 3.7);  // double を2つ → 2つ目の add\nint result3 = calculator.add(3, 6, 9);      // int を3つ → 3つ目の add</code></pre></div><h4>クラス内のメソッド呼び出し</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public void method2() {\n    method1();   // 同じクラスのメソッドは名前だけで呼べる\n}</code></pre></div><h4>メソッドの1行目のルール</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public static 戻り値の型 メソッド名(受け取る型 引数名) {\n\npublic static void main(String[] args) {               // void＝何も返さない\npublic static String reverseString(String str) {\npublic static double calculateAverage(int[] numbers) {</code></pre></div><ul><li>1行目には<b>型</b>（種類）を書く。中身（値）は書かない</li><li>中で使うのは<b>名前</b>のほう（<code>String str</code> → <code>str</code>）</li></ul><h4>作る と 呼び出す</h4><div class=\"tbl\"><table><tr><th></th><th>書き方</th><th>( ) の中</th></tr><tr><td>作る</td><td><code>public void setName(String name) { … }</code></td><td>型と名前</td></tr><tr><td>呼び出す</td><td><code>person.setName(\"Tanaka\");</code></td><td>実際の値</td></tr></table></div><ul><li>同じクラスの static メソッドは名前だけで呼べる：<code>reverseString(original)</code></li><li>インスタンスのメソッドは「変数名.メソッド名()」：<code>person.getName()</code></li><li>戻り値は変数で受け取れる：<code>String reversed = reverseString(original);</code></li></ul><h4>コンストラクタ</h4><ul><li>クラスと<b>同じ名前</b>で、戻り値の型は書かない（void も書かない）</li><li>new したときに自動で呼ばれる</li><li>コンストラクタを作っていないクラスは、<code>new Person()</code> と ( ) を空にして作る</li></ul><h4>ゲッター・セッター</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>private String name;\n\npublic String getName() {           // ゲッター：値を返す\n    return name;\n}\n\npublic void setName(String name) {  // セッター：受け取った値を入れる\n    this.name = name;               // this.name＝フィールド、name＝引数\n}</code></pre></div><div class=\"co co-red\"><span class=\"co-i\">⚠️</span><div class=\"co-b\"><p>セッターの引数名は、フィールドと<b>同じつづり</b>にする。<code>setAddress(String Address)</code> のように1文字でも違うと、<code>this.address = address;</code> が「フィールドを自分に入れ直す」だけになり、値が入らない（null のまま）。エラーにならないので気づきにくい。</p></div></div><h4>private と別のクラス</h4><ul><li>private は「同じクラスの中」からならさわれる。main を同じクラスに書くと <code>dog1.name</code> でも動いてしまう</li><li>main を別のクラス（<code>Main.java</code>）に書くと <code>person.name</code> はエラー → ゲッター・セッター経由で使う</li></ul>"}, {"id": "java1-03", "page": "Java 基礎編", "cat": "java", "ch": 3, "title": "変数とデータ型", "summary": "変数 ＝データを入れる名前付きの箱（メモリの場所）。 データ型 変数名 = 値; で宣言と初期化を同時にできる。", "snippet": "int num;          // 宣言（箱を用意する）", "date": "2026-10-28", "min": 6, "html": "<div class=\"co co-green\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>変数</b>＝データを入れる名前付きの箱（メモリの場所）。<code>データ型 変数名 = 値;</code> で宣言と初期化を同時にできる。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int num;          // 宣言（箱を用意する）\nnum = 10;         // 初期化（値を入れる）\nint num2 = 10;    // 宣言と初期化を同時に\nSystem.out.println(num);   // 変数の値を表示</code></pre></div><h4>数値型</h4><div class=\"tbl\"><table><tr><th>型</th><th>種類</th><th>ポイント</th></tr><tr><td>byte / short</td><td>整数（小）</td><td>小さい数用</td></tr><tr><td class=\"c-green\">int</td><td>整数</td><td><b>いちばんよく使う</b></td></tr><tr><td>long</td><td>整数（大）</td><td>末尾に <code>L</code>（例：10000000000L）</td></tr><tr><td>float</td><td>小数</td><td>末尾に <code>f</code>（例：3.14f）</td></tr><tr><td class=\"c-green\">double</td><td>小数</td><td><b>小数はこれが基本</b></td></tr></table></div><h4>整数型の範囲</h4><div class=\"tbl\"><table><tr><th>型</th><th>大きさ</th><th>入る範囲</th></tr><tr><td>byte</td><td>8ビット</td><td>-128 ～ 127</td></tr><tr><td>short</td><td>16ビット</td><td>-32,768 ～ 32,767</td></tr><tr><td>int</td><td>32ビット</td><td>約 -21億 ～ 約21億（2,147,483,647）</td></tr><tr><td>long</td><td>64ビット</td><td>約 -922京 ～ 約922京</td></tr></table></div><ul><li>扱う数の大きさで選ぶ。迷ったら int、約21億を超えるなら long（末尾に <code>L</code> か <code>l</code>）</li></ul><h4>小数（浮動小数点型）</h4><div class=\"tbl\"><table><tr><th>型</th><th>大きさ</th><th>精度</th><th>書き方</th></tr><tr><td>float</td><td>32ビット</td><td>約6～7桁</td><td><code>3.14f</code>（末尾に <code>f</code> か <code>F</code>）</td></tr><tr><td>double</td><td>64ビット</td><td>約15桁</td><td><code>3.14</code>（これが基本）</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">⚠️</span><div class=\"co-b\"><p>小数の計算には<b>小さな誤差</b>が出ることがある。小数どうしを <code>==</code> で比べず、「差がとても小さいか」で比べる（例：<code>Math.abs(a - b) &lt; 0.0001</code>）。</p></div></div><h4>型の変換</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int x = 10;\ndouble y = x;          // 小→大は自動（拡大変換）10.0\n\ndouble a = 12.34;\nint b = (int) a;       // 大→小はキャストが必要（縮小変換）12\n\nint i = 100;\nlong l = i;            // int → long、float → double も自動</code></pre></div><ul><li>キャストすると小数点以下が切り捨てられるなど、<b>精度が失われる</b>ことがある</li><li>入りきらない大きさの値をキャストすると、おかしな値になる</li></ul><h4>文字列（String）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>String name = &quot;John&quot;;\nString full = name + &quot; Doe&quot;;          // 連結\nint len = full.length();              // 長さ\nboolean same = name.equals(&quot;John&quot;);  // 内容の比較は equals()\nString msg = String.format(&quot;%sは%d歳&quot;, name, 30);  // フォーマット\nString part = &quot;Hello, World&quot;.substring(7);        // &quot;World&quot;（7番目から後ろ）\nSystem.out.printf(&quot;%sは%d歳&quot;, name, 30);           // フォーマットしてそのまま表示</code></pre></div><ul><li><b>文字列リテラル</b>＝コードに直接書いた <code>\"…\"</code> の文字。String はクラス（だから大文字始まり）</li><li><code>+</code> では、文字列と数字などほかの型もつなげられる</li></ul><div class=\"tbl\"><table><tr><th>フォーマットの記号</th><th>意味</th></tr><tr><td><code>%s</code></td><td>文字列</td></tr><tr><td><code>%d</code></td><td>整数</td></tr><tr><td><code>%.1f</code></td><td>小数（小数点以下1桁）</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>String path = &quot;C:\\\\Program Files\\\\Java&quot;;   // \\\\ でバックスラッシュ1つ\nString lines = &quot;Line 1\\nLine 2&quot;;           // \\n で改行</code></pre></div><div class=\"tbl\"><table><tr><th>エスケープ</th><th>意味</th></tr><tr><td><code>\\n</code></td><td>改行</td></tr><tr><td><code>\\t</code></td><td>タブ</td></tr><tr><td><code>\\\"</code></td><td>ダブルクォート</td></tr><tr><td><code>\\\\</code></td><td>バックスラッシュ</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">⚠️</span><div class=\"co-b\"><p>文字列の比較は <code>==</code> ではなく <b><code>equals()</code></b> を使う。<code>==</code> は「同じ物か（参照）」を比べるため。</p></div></div><h4>配列</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int[] numbers = {10, 20, 30};\nnumbers[0];         // 10（インデックスは0から）\nnumbers.length;     // 3\nint[][] matrix = {{1, 2}, {3, 4}};  // 2次元配列</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int[] scores = new int[5];   // 要素数5の配列を作る（中身は全部 0）\nscores[0] = 10;              // 番号を指定して代入\nscores[1] = 25;              // あとから変更もできる\n\nint[] copy = new int[scores.length];\nSystem.arraycopy(scores, 0, copy, 0, scores.length);  // 配列をコピー（元, 元の位置, 先, 先の位置, 個数）\n\nmatrix.length;      // 2次元配列の行数\nmatrix[0].length;   // 列数\nmatrix[1][0];       // 2行目の1列目（→ 3）</code></pre></div><h4>そのほかのデータ型</h4><ul><li>int・double・boolean などの基本の型のほかに、<b>クラス</b>・<b>インターフェース</b>・<b>配列</b>・<b>コレクション</b>も型として使える（<code>Person p</code>、<code>int[] a</code>、<code>List&lt;String&gt; list</code>）</li><li>インターフェースは応用編の「インターフェースと抽象クラス」を参照</li></ul><h4>型・名前・値</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>double price = 100.5;\n// double＝型（種類）  price＝名前  100.5＝値</code></pre></div><div class=\"tbl\"><table><tr><th>型</th><th>入れるもの</th><th>例</th></tr><tr><td>int</td><td>整数（約21億まで）</td><td><code>3500</code></td></tr><tr><td>long</td><td>大きな整数（末尾に L）</td><td><code>111111111111L</code></td></tr><tr><td>boolean</td><td>真偽値</td><td><code>true</code> / <code>false</code></td></tr></table></div><h4>割り算とキャスト</h4><ul><li>int ÷ int は小数点以下が切り捨て：<code>10 / 3</code> → 3、<code>46 / 12</code> → 3（余りは <code>46 % 12</code> → 10）</li><li>小数で割りたいときは、割る前に (double)：<code>(double) sum / numbers.length</code></li><li>計算結果を int にするときは、式全体を ( ) で囲む：<code>(int) (unitPrice * (1 + taxRate))</code></li><li>int × double の答えは double になる</li></ul><h4>println の書き方</h4><ul><li>文字は \" \" で囲む、変数は名前を書く、つなぐときは +：<code>\"税込み価格: \" + total + \"円\"</code></li><li>条件式をそのまま入れると true / false が表示される</li><li>計算は変数に入れて使い回す（表示のときに計算し直さない）</li></ul><h4>StringBuilder（文字列を逆順にする）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>StringBuilder sb = new StringBuilder(str);\nsb.reverse();\nreturn sb.toString();   // String に戻す</code></pre></div><h4>main の args</h4><ul><li><code>java Main banana</code> と打つと、<code>args[0]</code> に \"banana\" が入る</li></ul>"}, {"id": "java1-04", "page": "Java 基礎編", "cat": "java", "ch": 4, "title": "演算子・スコープ", "summary": "0で割る と ArithmeticException。intの最大値を超えると オーバーフロー して値がおかしくなる。", "snippet": "int x = 10, y = 5;", "date": "2026-10-28", "min": 2, "html": "<h4>演算子</h4><div class=\"tbl\"><table><tr><th>種類</th><th>記号</th></tr><tr><td>算術</td><td><code>+</code> <code>-</code> <code>*</code> <code>/</code> <code>%</code>（%は余り）</td></tr><tr><td>比較</td><td>== != &gt; &gt;= &lt; &lt;=</td></tr><tr><td>論理</td><td>&amp;&amp;（かつ） ||（または） !（否定）</td></tr><tr><td>代入</td><td>= += -= *=</td></tr><tr><td>三項</td><td>条件 ? 値1 : 値2</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">⚠️</span><div class=\"co-b\"><p><b>0で割る</b>と ArithmeticException。intの最大値を超えると<b>オーバーフロー</b>して値がおかしくなる。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int x = 10, y = 5;\nx += y;                      // x = x + y と同じ（15）\nx *= y;                      // x = x * y と同じ（75）\nint max = (x &gt; y) ? x : y;   // 三項演算子：条件が true なら x、false なら y\n\nint over = Integer.MAX_VALUE + 1;   // オーバーフロー → マイナスの最小値になる\nint error = 10 / 0;                 // 実行時に ArithmeticException</code></pre></div><h4>計算の順番（優先順位）</h4><ol><li><code>( )</code> で囲んだ式</li><li>単項演算子（<code>-5</code> のような正負の記号や <code>!</code>）</li><li><code>*</code> <code>/</code> <code>%</code></li><li><code>+</code> <code>-</code></li></ol><ul><li>同じ順位なら<b>左から右</b>へ計算される</li><li><code>10 + 5 * 2</code> → 20、<code>(10 + 5) * 2</code> → 30</li></ul><h4>ブロックとスコープ</h4><div class=\"co co-orange\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><code>{ }</code> の中で宣言した変数は、<b>その { } の中でしか使えない</b>。</p></div></div><div class=\"tbl\"><table><tr><th>スコープ</th><th>使える範囲</th></tr><tr><td>ブロックスコープ</td><td>if・for などの <code>{ }</code> の中だけ。抜けると消える</td></tr><tr><td>メソッドスコープ</td><td>そのメソッドの中だけ</td></tr><tr><td>クラススコープ</td><td>フィールド。そのクラスのどのメソッドからでも使える</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int y = 20;               // メソッドスコープ\nif (y &gt; 15) {\n    int z = 30;           // ブロックスコープ\n    System.out.println(z);\n}\n// System.out.println(z); ← if の外なのでコンパイルエラー</code></pre></div><ul><li>スコープを意識すると、名前のぶつかりを防げて、読みやすくなる</li></ul>"}, {"id": "java1-05", "page": "Java 基礎編", "cat": "java", "ch": 5, "title": "命令文（条件分岐・繰り返し）", "summary": "命令文 ＝プログラムの中で、一つ一つの処理を実行する文。 条件分岐 （if・switch）は条件によって処理を分け、 繰り返し （for・while・do-while）は条件を満たす間、同じ処理をくり返す。", "snippet": "if (条件) { ... } else { ... }   // 条件が真なら前、偽なら else", "date": "2026-10-28", "min": 2, "html": "<div class=\"co co-orange\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>命令文</b>＝プログラムの中で、一つ一つの処理を実行する文。<b>条件分岐</b>（if・switch）は条件によって処理を分け、<b>繰り返し</b>（for・while・do-while）は条件を満たす間、同じ処理をくり返す。</p></div></div><h4>条件分岐とループ</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>if (条件) { ... } else { ... }   // 条件が真なら前、偽なら else\n\nswitch (値) {\n    case 1: ...; break;\n    default: ...;\n}\n\nfor (int i = 0; i &lt; 5; i++) { ... }   // for (初期化式; 条件式; 更新式)\nwhile (条件) { ... }                    // 条件が真の間くり返す（1回も実行されないこともある）\ndo { ... } while (条件);   // 最低1回は実行される</code></pre></div><h4>if / else if / else</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>if (score &gt;= 90) {\n    System.out.println(&quot;優秀です！&quot;);\n} else if (score &gt;= 70) {   // ここに来た時点で 90 未満\n    System.out.println(&quot;合格です！&quot;);\n} else {                    // else に条件は書かない\n    System.out.println(&quot;不合格です...&quot;);\n}</code></pre></div><ul><li>比べるのは <code>&gt;=</code> <code>&lt;</code> など。<code>=</code> は代入</li><li>「かつ」は <code>&amp;&amp;</code>（and は使えない）。<code>if ( )</code> のうしろに ; を付けない</li><li>境目の値（90・70）でも確かめる</li></ul><h4>for（番号を使う）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int sum = 0;                              // 合計用の変数は for の前に用意\nfor (int i = 0; i &lt; numbers.length; i++) {\n    sum += numbers[i];                    // ループの中で足す\n}\nSystem.out.println(&quot;合計: &quot; + sum);       // 表示はループのあとで1回</code></pre></div><ul><li>真ん中は「続ける条件」（比べる式）。1〜5 なら <code>int i = 1; i &lt;= 5</code></li><li><code>i</code> は for の中だけで使える（スコープ）</li><li>1行に1つの仕事（足す行と表示する行は分ける）</li></ul><h4>拡張for（全部取り出す）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>for (int n : numbers) { … }\nfor (String f : fruits) { … }</code></pre></div><h4>switch</h4><ul><li>文字列でも使える：<code>switch (fruit) { case \"apple\": … }</code></li><li>case のあとに break を書かないと、次の case に流れる</li><li>どれにも当てはまらないときは default</li></ul>"}, {"id": "java1-06", "page": "Java 基礎編", "cat": "java", "ch": 6, "title": "識別子・命名規則と予約語", "summary": "識別子 ＝自分で付ける 名前 のこと。クラス名（ Dog ）・変数名（ score ）・メソッド名（ getName ）などが識別子。", "snippet": "", "date": "2026-10-28", "min": 3, "html": "<div class=\"co co-brown\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>識別子</b>＝自分で付ける<b>名前</b>のこと。クラス名（<code>Dog</code>）・変数名（<code>score</code>）・メソッド名（<code>getName</code>）などが識別子。</p></div></div><h4>識別子のルール（守らないとエラー）</h4><ul><li>使える文字は<b>英字・数字・</b><b><code>_</code></b><b>・</b><b><code>$</code></b></li><li><b>スペースや </b><b><code>-</code></b><b> などの記号は使えない</b>（<code>my-score</code> ✗、<code>my score</code> ✗）</li><li>数字から始まる名前は<b>NG</b>（1myVar ✗）</li><li>大文字・小文字は区別される（<code>score</code> と <code>Score</code> は別物）</li><li><b>予約語</b>（if, class, public, static, return など）はそのまま名前にできない</li></ul><h4>命名規則（守らなくても動くが、守るのが決まり）</h4><div class=\"tbl\"><table><tr><th>対象</th><th>書き方</th><th>例</th></tr><tr><td>クラス</td><td>大文字始まり（アッパーキャメル）</td><td>MyClass</td></tr><tr><td>メソッド・変数</td><td>小文字始まり（キャメル）</td><td>myMethod</td></tr><tr><td>定数</td><td>全部大文字＋_</td><td>MAX_VALUE</td></tr></table></div><div class=\"co co-brown\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>識別子のルール</b>＝Javaの文法なので、破るとコンパイルエラー／<b>命名規則</b>＝名前の付け方のルール／<b>予約語</b>＝Javaが特別な意味で使うので名前にできない単語。</p></div></div><h4>名前の書き方の呼び名</h4><div class=\"tbl\"><table><tr><th>呼び名</th><th>使う場所</th><th>例</th></tr><tr><td>camelCase</td><td>変数・メソッド</td><td><code>customerName</code></td></tr><tr><td>PascalCase</td><td>クラス</td><td><code>CustomerService</code></td></tr><tr><td>UPPER_SNAKE_CASE</td><td>定数（final）</td><td><code>MAX_RETRY_COUNT</code></td></tr><tr><td>snake_case・kebab-case</td><td>Javaでは使わない（- は使えない）</td><td><code>customer_name</code>・<code>customer-name</code></td></tr></table></div><ul><li>メソッド名は動詞から始める（<code>printData</code>・<code>organizeData</code>）</li><li>クラス名は単数形にする（<code>Fruit</code>）</li><li>定数：<code>final int PASSING_SCORE = 70;</code>（final＝あとから値を変えられない）</li></ul><h4>名前の付け方のベストプラクティス</h4><ul><li>他の人が読んでも意味がわかる名前にする</li><li>略語よりも完全な単語を使う（<code>cnt</code> より <code>count</code>）</li><li><code>_</code> や <code>$</code> で始めるのはルール上OKだが、<b>おすすめされない</b></li><li><code>my_variable</code>・<code>MyVariable</code> も変数名としてはエラーにならないが、命名規則では <code>myVariable</code> が正解</li></ul><h4>予約語の例</h4><div class=\"tbl\"><table><tr><th>予約語</th><th>使い道</th></tr><tr><td>if, else, switch, case, default</td><td>条件分岐</td></tr><tr><td>while, do, for</td><td>繰り返し</td></tr><tr><td>class, interface, extends, implements</td><td>クラス・インターフェースの定義</td></tr><tr><td>public, private, protected</td><td>アクセス修飾子</td></tr><tr><td>static, final, abstract</td><td>変数やメソッドの性質</td></tr><tr><td>return, void</td><td>戻り値</td></tr></table></div><h4>予約語ではないもの</h4><ul><li><code>main</code>（メソッド名）や <code>String</code>（クラス名）は識別子</li><li><code>true</code>・<code>false</code>・<code>null</code> は「リテラル」。予約語ではないが、名前には使えない</li><li><code>_</code> 1文字だけの名前は使えない</li></ul>"}, {"id": "java1-07", "page": "Java 基礎編", "cat": "java", "ch": 7, "title": "カプセル化とアクセス修飾子", "summary": "カプセル化 ＝データとその操作をクラスの中に閉じ込めて、外から直接さわれないようにすること。データが安全になり、使いやすくなる。 フィールドは private にして、メソッド（getter / setter）経由で触らせるのが一般的。", "snippet": "public class MyClass {", "date": "2026-10-28", "min": 1, "html": "<div class=\"co co-purple\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>カプセル化</b>＝データとその操作をクラスの中に閉じ込めて、外から直接さわれないようにすること。データが安全になり、使いやすくなる。<br>フィールドは<b>private</b>にして、メソッド（getter / setter）経由で触らせるのが一般的。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class MyClass {\n    private int privateField;      // クラスの中からだけさわれる\n\n    public void publicMethod() {   // どこからでも呼べる\n        // 処理\n    }\n}</code></pre></div><div class=\"tbl\"><table><tr><th>修飾子</th><th>アクセスできる範囲</th></tr><tr><td class=\"c-green\">public</td><td>どこからでも</td></tr><tr><td class=\"c-yellow\">protected</td><td>同じパッケージ＋サブクラス</td></tr><tr><td class=\"c-orange\">（なし）</td><td>同じパッケージのみ</td></tr><tr><td class=\"c-red\">private</td><td>同じクラスのみ</td></tr></table></div>"}, {"id": "java1-08", "page": "Java 基礎編", "cat": "java", "ch": 8, "title": "コレクション（List / Map / Set）", "summary": "配列 はサイズ固定、 List は後から追加できる。実務ではListをよく使う。", "snippet": "List<String> names = new ArrayList<>();", "date": "2026-10-28", "min": 4, "html": "<div class=\"tbl\"><table><tr><th>種類</th><th>特徴</th><th>使いどころ</th></tr><tr><td class=\"c-yellow\">List</td><td>順序あり・重複OK・サイズ可変</td><td>一覧データ、検索結果</td></tr><tr><td class=\"c-yellow\">Map</td><td>キーと値のペア</td><td>コード値→表示名の変換</td></tr><tr><td class=\"c-yellow\">Set</td><td>重複なし・順序なし</td><td>重複排除、存在チェック</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>List&lt;String&gt; names = new ArrayList&lt;&gt;();\nnames.add(&quot;田中&quot;);\nnames.get(0);          // &quot;田中&quot;\nnames.size();          // 1\nfor (String n : names) { System.out.println(n); }\n\nMap&lt;String, String&gt; statusMap = new HashMap&lt;&gt;();\nstatusMap.put(&quot;PENDING&quot;, &quot;受付中&quot;);\nstatusMap.get(&quot;PENDING&quot;);   // &quot;受付中&quot;\n\nSet&lt;String&gt; tags = new HashSet&lt;&gt;();\ntags.add(&quot;Java&quot;);\ntags.add(&quot;Java&quot;);      // 重複は無視される</code></pre></div><div class=\"co co-yellow\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>配列</b>はサイズ固定、<b>List</b>は後から追加できる。実務ではListをよく使う。</p></div></div><div class=\"tbl\"><table><tr><th>種類</th><th>よく使うクラス（実装）</th></tr><tr><td>List</td><td>ArrayList（番号で取り出すのが速い）・LinkedList（先頭・末尾の追加・削除が速い）</td></tr><tr><td>Set</td><td>HashSet・TreeSet</td></tr><tr><td>Map</td><td>HashMap・TreeMap</td></tr></table></div><ul><li>コレクションを使うと、データの追加・削除・検索がかんたんにできる。Map はキーですばやく探せる</li></ul><h4>使う準備（import）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>import java.util.ArrayList;\nimport java.util.List;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.HashSet;\nimport java.util.Set;</code></pre></div><ul><li><code>public class</code> より<b>上</b>に書く。忘れると「シンボルが見つかりません」</li></ul><h4>List のメソッド</h4><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th></tr><tr><td><code>fruits.add(\"りんご\")</code></td><td>追加する</td></tr><tr><td><code>fruits.size()</code></td><td>要素数</td></tr><tr><td><code>fruits.get(0)</code></td><td>番号で取り出す</td></tr><tr><td><code>fruits.remove(\"バナナ\")</code></td><td>削除する</td></tr><tr><td><code>fruits.contains(\"りんご\")</code></td><td>入っているか（true / false）</td></tr></table></div><h4>配列と List の違い</h4><div class=\"tbl\"><table><tr><th></th><th>配列</th><th>List</th></tr><tr><td>サイズ</td><td>固定</td><td>あとから変えられる</td></tr><tr><td>書き方</td><td><code>String[] arr</code></td><td><code>List&lt;String&gt; list</code></td></tr><tr><td>要素の追加</td><td>できない（作り直し）</td><td><code>add()</code> でいつでも</td></tr><tr><td>実務で見る場所</td><td>DBから取った結果など</td><td>Service での処理の中など</td></tr></table></div><h4>Map のメソッド</h4><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th></tr><tr><td><code>statusMap.put(\"01\", \"未着手\")</code></td><td>追加する（キー, 値）</td></tr><tr><td><code>statusMap.get(\"02\")</code></td><td>キーで値を取り出す</td></tr><tr><td><code>statusMap.entrySet()</code></td><td>キーと値のペアの一覧</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>for (Map.Entry&lt;String, String&gt; e : statusMap.entrySet()) {\n    System.out.println(e.getKey() + &quot; &quot; + e.getValue());\n}</code></pre></div><ul><li>HashMap は入れた順番どおりに出てくるとは限らない。順番を守りたいときは LinkedHashMap</li><li>値は文字列以外もOK：<code>Map&lt;String, Integer&gt; scores</code> なら <code>scores.put(\"田中\", 80)</code></li><li>ないキーを <code>get</code> すると <code>null</code> が返る（<code>int</code> の変数に入れると NullPointerException）</li><li>実務では、区分コードと区分名の対応（「01」→「未対応」）やキャッシュに使う</li></ul><h4>Set の使い方</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Set&lt;String&gt; tags = new HashSet&lt;&gt;();\ntags.add(&quot;Java&quot;);\ntags.add(&quot;Spring&quot;);\ntags.add(&quot;Java&quot;);               // 重複 → 無視される\nSystem.out.println(tags.size()); // 2</code></pre></div><h4>実務コードでよく見る形</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// Repository から取った List をループする\nList&lt;Customer&gt; customers = customerRepository.findAll();\nfor (Customer customer : customers) {\n    System.out.println(customer.getName());\n}\n\n// ステータスコードを画面表示用の名前に変換する\nString displayStatus = statusMap.get(order.getStatus());</code></pre></div>"}, {"id": "java1-09", "page": "Java 基礎編", "cat": "java", "ch": 9, "title": "例外（Exception）", "summary": "例外 ＝プログラムの 実行中 に発生する、予期しないエラーのこと。適切に処理しないと、プログラムは 強制終了 する。", "snippet": "Throwable", "date": "2026-10-28", "min": 5, "html": "<div class=\"co co-red\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>例外</b>＝プログラムの<b>実行中</b>に発生する、予期しないエラーのこと。適切に処理しないと、プログラムは<b>強制終了</b>する。</p></div></div><h4>よくある例外</h4><div class=\"tbl\"><table><tr><th>例外</th><th>原因</th></tr><tr><td>NullPointerException</td><td>nullのオブジェクトのメソッドを呼び出した</td></tr><tr><td>ArrayIndexOutOfBoundsException</td><td>配列の存在しないインデックスにアクセスした</td></tr><tr><td>NumberFormatException</td><td>数値に変換できない文字列を parseInt した</td></tr><tr><td>IOException</td><td>ファイルの読み書きに失敗した</td></tr><tr><td>IllegalArgumentException</td><td>不正な引数が渡された</td></tr></table></div><h4>継承関係（重要）</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Throwable\n├── Error（システムエラー。原則キャッチしない）\n└── Exception\n    ├── RuntimeException（unchecked例外。コンパイルエラーにならない）\n    │   ├── NullPointerException\n    │   ├── IllegalArgumentException\n    │   └── NumberFormatException など\n    └── IOException など（checked例外。コンパイル時にハンドリングが必須）</code></pre></div><h4>try-catch-finally</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>try {\n    // 例外が発生する可能性のある処理\n    int result = Integer.parseInt(&quot;abc&quot;);  // NumberFormatException 発生\n} catch (NumberFormatException e) {\n    // 例外をキャッチして対処する\n    System.out.println(&quot;数値に変換できません：&quot; + e.getMessage());\n} finally {\n    // 例外の有無に関わらず必ず実行される\n    System.out.println(&quot;処理終了&quot;);\n}</code></pre></div><h4>複数の catch</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>try {\n    String text = null;\n    int result = Integer.parseInt(text);   // 実際は NumberFormatException になる\n} catch (NullPointerException e) {\n    System.out.println(&quot;nullです&quot;);\n} catch (NumberFormatException e) {\n    System.out.println(&quot;数値に変換できません&quot;);\n} catch (Exception e) {\n    // 上記以外の全例外をキャッチ（最後に書く）\n    System.out.println(&quot;予期しないエラー：&quot; + e.getMessage());\n}</code></pre></div><ul><li>上から順に調べて、当てはまった catch だけが動く</li><li><code>catch (Exception e)</code> は何でも受け止めるので、<b>いちばん最後</b>に書く</li></ul><div class=\"co co-red\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>finally の使いどころ</b>：「必ず実行したい処理」に使う。Spring Boot では自動で管理されることが多いが、仕組みを理解しておくことが大事。</p></div></div><h4>throws と throw の違い</h4><div class=\"tbl\"><table><tr><th>キーワード</th><th>役割</th></tr><tr><td>throws</td><td>「この例外を投げるかも」と<b>宣言</b>する（メソッドの横）</td></tr><tr><td>throw</td><td>実際に例外を<b>投げる</b>（メソッドの中）</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// throws で宣言、throw で実際に投げる\npublic void divide(int a, int b) throws IllegalArgumentException {\n    if (b == 0) {\n        throw new IllegalArgumentException(&quot;0で除算はできません&quot;);\n    }\n    System.out.println(a / b);\n}</code></pre></div><h4>カスタム例外</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class CustomerNotFoundException extends RuntimeException {\n    public CustomerNotFoundException(Long id) {\n        super(&quot;顧客が見つかりません。ID：&quot; + id);\n    }\n}\n\n// 使う側\npublic Customer findById(Long id) {\n    Customer customer = customerRepository.findById(id).orElse(null);\n    if (customer == null) {\n        throw new CustomerNotFoundException(id);\n    }\n    return customer;\n}</code></pre></div><ul><li><b>カスタム例外</b>＝業務ロジック固有のエラーを表すために、自分で作る例外クラス</li><li><code>extends RuntimeException</code> で作ると unchecked 例外になる（throws の宣言がいらない）</li><li><code>super(\"…\")</code> で渡した文字が、<code>e.getMessage()</code> で取り出せるメッセージになる</li></ul><div class=\"co co-red\"><span class=\"co-i\">🏢</span><div class=\"co-b\"><p><b>実務での重要性</b>：Spring Boot では <code>@ControllerAdvice</code> と組み合わせて、カスタム例外を一か所でまとめてハンドリングできる（応用編 07 で学習）。</p></div></div><h4>いつ try-catch するか（例外ハンドリングの指針）</h4><div class=\"tbl\"><table><tr><th>ケース</th><th>対応方針</th></tr><tr><td>回復できるエラー</td><td>try-catch で処理し、代わりの処理や再試行をする</td></tr><tr><td>回復できないエラー</td><td>上位に投げる（throws で宣言）</td></tr><tr><td>業務ロジック上のエラー</td><td>カスタム例外を作ってスローする</td></tr></table></div><div class=\"co co-red\"><span class=\"co-i\">🚫</span><div class=\"co-b\"><p><b>よくある間違い</b></p><ul><li><b>例外を握りつぶす</b>（catch の中を空にする）→ 問題が見えなくなる</li><li><b>全部 RuntimeException でキャッチする</b> → くわしい原因がわからなくなる</li></ul></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// NG：例外を握りつぶす\ntry {\n    ...\n} catch (Exception e) {\n    // 何もしない ← ダメ！\n}\n\n// OK：ログに残す or 再スローする\ntry {\n    ...\n} catch (Exception e) {\n    System.out.println(&quot;エラー発生：&quot; + e.getMessage());  // e.getMessage()＝エラーの内容\n    throw e;  // 上位に投げる\n}</code></pre></div>"}, {"id": "java1-10", "page": "Java 基礎編", "cat": "java", "ch": 10, "title": "ラムダ式・Stream API", "summary": "ラムダ式 ＝「メソッドを式として短く書く」書き方。Java 8 から使える。実務のコードでよく登場する。", "snippet": "Runnable r1 = new Runnable() {", "date": "2026-10-28", "min": 3, "html": "<h4>ラムダ式</h4><div class=\"co co-pink\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>ラムダ式</b>＝「メソッドを式として短く書く」書き方。Java 8 から使える。実務のコードでよく登場する。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// ふつうの書き方（匿名クラス）\nRunnable r1 = new Runnable() {\n    @Override\n    public void run() {\n        System.out.println(&quot;Hello&quot;);\n    }\n};\n\n// ラムダ式で同じことを書く\nRunnable r2 = () -&gt; System.out.println(&quot;Hello&quot;);</code></pre></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>() -&gt; System.out.println(&quot;Hello&quot;)      // 引数なし\nname -&gt; System.out.println(name)        // 引数1つ\n(a, b) -&gt; a + b                         // 引数2つ\n\n(a, b) -&gt; {                             // 処理が複数行のときは { } と return\n    int result = a + b;\n    return result;\n}</code></pre></div><h4>Stream API とは</h4><p>コレクション（List・Set など）の要素を、「何をしたいか」だけ簡潔に書いて処理できる仕組み。</p><h4>Stream API の流れ</h4><div class=\"co co-pink\"><span class=\"co-i\">🔁</span><div class=\"co-b\"><p><b>stream()</b> → <b>中間操作</b>（filter / map） → <b>終端操作</b>（collect / count）</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// filter：絞り込み（偶数だけ）\nList&lt;Integer&gt; evens = numbers.stream()\n    .filter(n -&gt; n % 2 == 0)\n    .collect(Collectors.toList());\n\n// map：変換（全部大文字に）\nList&lt;String&gt; upper = names.stream()\n    .map(String::toUpperCase)    // メソッド参照\n    .collect(Collectors.toList());</code></pre></div><div class=\"tbl\"><table><tr><th>書き方</th><th>同じ意味</th></tr><tr><td>name -&gt; name.toUpperCase()</td><td>String::toUpperCase</td></tr></table></div><ul><li>メソッド参照はラムダ式をさらに短くした書き方。実務でよく出てくるので、<b>読めるように</b>しておく</li><li><code>Collectors</code> を使うときは <code>import java.util.stream.Collectors;</code> が必要</li></ul><h4>実務でよく見る形</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// Entity のリストから、名前だけのリストを作る\nList&lt;String&gt; customerNames = customers.stream()\n    .map(customer -&gt; customer.getName())\n    .collect(Collectors.toList());\n\n// 条件に合う件数を数える\nlong activeCount = orders.stream()\n    .filter(order -&gt; order.getStatus().equals(&quot;対応中&quot;))\n    .count();</code></pre></div>"}, {"id": "java2-01", "page": "Java 応用編", "cat": "java", "ch": 1, "title": "継承・オーバーライド・ポリモーフィズム", "summary": "継承 ＝親クラス（スーパークラス）の機能を子クラス（サブクラス）が引き継ぐ（ extends ） オーバーライド ＝親のメソッドを子で書き換える（ @Override ） ポリモーフィズム ＝子を親の型で扱い、実際の中身に合わせた処理が動く", "snippet": "class Animal {                       // 親クラス", "date": "2026-10-28", "min": 4, "html": "<div class=\"co co-blue\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>継承</b>＝親クラス（スーパークラス）の機能を子クラス（サブクラス）が引き継ぐ（<code>extends</code>）<br><b>オーバーライド</b>＝親のメソッドを子で書き換える（<code>@Override</code>）<br><b>ポリモーフィズム</b>＝子を親の型で扱い、実際の中身に合わせた処理が動く</p></div></div><h4>継承の利点</h4><div class=\"tbl\"><table><tr><th>利点</th><th>内容</th></tr><tr><td>再利用性</td><td>親クラスに書いた処理を、子クラスでそのまま使える</td></tr><tr><td>メンテナンスしやすい</td><td>共通の処理は親クラスを直すだけで済む</td></tr><tr><td>拡張性</td><td>子クラスで新しい機能を足せる</td></tr><tr><td>オブジェクト指向の土台</td><td>継承・ポリモーフィズム・カプセル化を実現する基本</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>class Animal {                       // 親クラス\n    void eat() { System.out.println(&quot;食事をします。&quot;); }\n}\n\nclass Dog extends Animal {           // 子クラス：eat() はそのまま使える\n    void bark() { System.out.println(&quot;ワンワン！&quot;); }\n}\n\nDog dog = new Dog();\ndog.eat();    // 親のメソッド\ndog.bark();   // 自分のメソッド</code></pre></div><h4>オーバーライドとポリモーフィズム</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>class Animal {\n    void sound() { System.out.println(&quot;動物の鳴き声&quot;); }\n}\n\nclass Dog extends Animal {\n    @Override                        // 書き換えていることを明示（つづりミスもチェックしてくれる）\n    void sound() { System.out.println(&quot;ワンワン！&quot;); }\n}\n\nclass Cat extends Animal {\n    @Override\n    void sound() { System.out.println(&quot;ニャーニャー！&quot;); }\n}\n\nAnimal a1 = new Dog();   // 子を親の型で扱う\nAnimal a2 = new Cat();\na1.sound();              // ワンワン！（中身は Dog）\na2.sound();              // ニャーニャー！（中身は Cat）</code></pre></div><ul><li>メソッドの引数や戻り値を親の型にしておくと、いろいろな子クラスをまとめて扱える</li><li>新しい子クラス（たとえば Bird）を足しても、既存のコードを直さなくていい</li></ul><h4>コンストラクタと super()</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>class Animal {\n    String name;\n    Animal(String name) {                 // 引数ありのコンストラクタ\n        this.name = name;\n        System.out.println(&quot;Animalコンストラクタ&quot;);\n    }\n}\n\nclass Dog extends Animal {\n    String breed;\n    Dog(String name, String breed) {\n        super(name);                      // 親のコンストラクタを先に呼ぶ（1行目に書く）\n        this.breed = breed;\n        System.out.println(&quot;Dogコンストラクタ&quot;);\n    }\n}\n\nnew Dog(&quot;Pochi&quot;, &quot;Shiba Inu&quot;);   // Animalコンストラクタ → Dogコンストラクタ の順に表示</code></pre></div><ul><li>子のインスタンスを作ると、<b>必ず親のコンストラクタが先に</b>動く</li><li>親に引数ありのコンストラクタしかないときは、子のコンストラクタで <code>super(…)</code> を書く必要がある</li></ul><h4>インターフェース（基本）</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>interface Flyable { void fly(); }\ninterface Swimmable { void swim(); }\n\nclass Bird implements Flyable {\n    @Override\n    public void fly() { System.out.println(&quot;Bird is flying.&quot;); }\n}</code></pre></div><ul><li><code>implements</code> で実装する。1つのクラスが<b>複数</b>のインターフェースを実装できる（多重継承の代わり）</li><li>インターフェースのメソッドは自動で public・抽象メソッドになる</li><li>実装したら<b>全部のメソッドをオーバーライド</b>する（しないならそのクラスは abstract にする）</li></ul><h4>型の変換</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>int x = 10;\ndouble y = x;          // 自動の変換（拡大変換）→ 10.0\n\ndouble a = 12.34;\nint b = (int) a;       // 型キャスト（縮小変換）→ 12（小数は切り捨て）</code></pre></div><h4>instanceof</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>Animal animal = new Dog();\nif (animal instanceof Dog) {             // 中身が Dog なら true\n    System.out.println(&quot;This is a Dog.&quot;);\n} else if (animal instanceof Cat) {\n    System.out.println(&quot;This is a Cat.&quot;);\n}</code></pre></div>"}, {"id": "java2-02", "page": "Java 応用編", "cat": "java", "ch": 2, "title": "抽象クラスとインターフェース", "summary": "抽象クラス（abstract） 一部だけ未実装 継承は 1つだけ 共通の処理を持たせたいとき", "snippet": "abstract class Shape {", "date": "2026-10-28", "min": 2, "html": "<div class=\"cols\"><div><div class=\"co co-purple\"><span class=\"co-i\">📐</span><div class=\"co-b\"><p><b>抽象クラス（abstract）</b><br>一部だけ未実装<br>継承は<b>1つだけ</b><br>共通の処理を持たせたいとき</p></div></div></div><div><div class=\"co co-blue\"><span class=\"co-i\">🔌</span><div class=\"co-b\"><p><b>インターフェース（interface）</b><br>基本は全部未実装<br><b>複数</b>実装できる（implements）<br>「できること」の約束を決めるとき</p></div></div></div></div><h4>抽象クラス</h4><ul><li>一部のメソッドが未実装（<b>抽象メソッド</b>）なので、<b>そのままでは new できない</b></li><li>共通の特徴を持つクラスをまとめ、子クラスで未実装のメソッドを書く</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>abstract class Shape {\n    abstract void draw();                                    // 未実装（子が書く）\n    void displayInfo() { System.out.println(&quot;This is a shape.&quot;); }  // 共通の処理\n}\n\nclass Circle extends Shape {\n    @Override\n    void draw() { System.out.println(&quot;Drawing a circle.&quot;); }\n}\n\nShape circle = new Circle();   // 親（抽象クラス）の型で扱える\ncircle.draw();\ncircle.displayInfo();</code></pre></div><h4>インターフェース</h4><ul><li>メソッドの約束だけを決める型。インターフェース自体は new できない</li><li>異なるクラスが同じインターフェースを実装すると、<b>共通の型</b>で扱える</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>interface Vehicle {\n    void start();\n    void stop();\n}\n\nclass Car implements Vehicle {\n    @Override public void start() { System.out.println(&quot;Car is starting.&quot;); }\n    @Override public void stop()  { System.out.println(&quot;Car is stopping.&quot;); }\n}\n\nVehicle car = new Car();   // インターフェースの型で扱える\ncar.start();</code></pre></div><h4>違いと使い分け</h4><div class=\"tbl\"><table><tr><th></th><th>抽象クラス</th><th>インターフェース</th></tr><tr><td>実装済みのメソッド</td><td>持てる</td><td>基本は持たない</td></tr><tr><td>継承・実装できる数</td><td>1つだけ（extends）</td><td>いくつでも（implements）</td></tr><tr><td>使うとき</td><td>共通の処理を持たせたい</td><td>複数の「できること」を持たせたい</td></tr></table></div><ul><li>どちらも<b>ポリモーフィズム</b>を実現するために使う。共通の型で扱い、実際の中身に合わせた処理を動かす</li></ul>"}, {"id": "java2-03", "page": "Java 応用編", "cat": "java", "ch": 3, "title": "カプセル化・アクセス修飾子・イミュータブル", "summary": "final クラス＋ private final フィールド＋setterなし＋コンストラクタで全部初期化", "snippet": "public void setAge(int age) {", "date": "2026-10-28", "min": 3, "html": "<h4>カプセル化の利点</h4><div class=\"tbl\"><table><tr><th>利点</th><th>内容</th></tr><tr><td>情報の隠蔽</td><td>中の作りを外から見えなくし、不正なアクセスを防ぐ</td></tr><tr><td>データの保護</td><td>private にして、勝手に書き換えられないようにする</td></tr><tr><td>使い方がシンプル</td><td>公開するメソッドだけ使えばよい</td></tr><tr><td>再利用しやすい</td><td>クラスが独立して動くので、ほかでも使いやすい</td></tr></table></div><h4>原則</h4><ul><li>フィールドは <b>private</b></li><li>読み書きは <b>getter / setter</b> 経由</li><li>状態を変えるときは、<b>条件をチェック</b>してから変える</li><li>変わらないものは、変えられない設計にする（イミュータブル）</li><li>同じパッケージだけに見せたいものは package-private</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public void setAge(int age) {\n    if (age &gt;= 0) {                // チェックしてから代入\n        this.age = age;\n    } else {\n        System.out.println(&quot;無効な年齢です。&quot;);\n    }\n}\n\npublic void celebrateBirthday() {  // 状態の変更をメソッドで制御する\n    this.age++;\n    System.out.println(&quot;Happy Birthday, &quot; + name + &quot;!&quot;);\n}</code></pre></div><h4>アクセス修飾子の使い分け</h4><div class=\"tbl\"><table><tr><th>対象</th><th>よく使う修飾子</th><th>理由</th></tr><tr><td>クラス</td><td>public かデフォルト（なし）</td><td>public は他から使える、なしは同じパッケージだけ</td></tr><tr><td>フィールド</td><td>private</td><td>getter / setter 経由でさわらせる</td></tr><tr><td>メソッド</td><td>外から使う → public、中だけの補助 → private</td><td>中の作りを隠す</td></tr><tr><td>コンストラクタ</td><td>ふつうは public、特別なときは private</td><td>private にすると外から new できない（シングルトン）</td></tr></table></div><h4>private メソッド</h4><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class Person {\n    private void greet() { System.out.println(&quot;Hello!&quot;); }   // 中だけで使う\n    public void sayHello() { greet(); }                       // 外からはこちらを呼ぶ\n}</code></pre></div><h4>package-private（修飾子なし）</h4><ul><li>修飾子を何も付けないと、<b>同じパッケージの中だけ</b>で使える</li><li>同じパッケージのクラスどうしで情報を共有したいときに使う</li></ul><h4>イミュータブル（変更できない）オブジェクト</h4><div class=\"co co-green\"><span class=\"co-i\">🧊</span><div class=\"co-b\"><p><code>final</code> クラス＋<code>private final</code> フィールド＋setterなし＋コンストラクタで全部初期化</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public final class Person {          // final：継承させない\n    private final String name;       // final：一度入れたら変えられない\n    private final int age;\n\n    public Person(String name, int age) {\n        this.name = name;\n        this.age = age;\n    }\n\n    public String getName() { return name; }\n    public int getAge() { return age; }\n}</code></pre></div><ul><li>状態が変わらないので、同時に使われても安全（スレッドセーフ）</li><li>思わぬ書き換えが起きないので、バグが減る</li><li>HashMap のキーなどに使われる</li></ul>"}, {"id": "java2-04", "page": "Java 応用編", "cat": "java", "ch": 4, "title": "デバッグ（Eclipse）", "summary": "デバッグ ＝プログラムが期待どおりに動かない原因を見つけて直す作業。エラーの行だけでなく、 「なぜその値になったのか」 をさかのぼって追う。エンジニアに必須の問題解決スキル。", "snippet": "", "date": "2026-10-28", "min": 1, "html": "<div class=\"co co-orange\"><span class=\"co-i\">🔍</span><div class=\"co-b\"><p><b>デバッグ</b>＝プログラムが期待どおりに動かない原因を見つけて直す作業。エラーの行だけでなく、<b>「なぜその値になったのか」</b>をさかのぼって追う。エンジニアに必須の問題解決スキル。</p></div></div><h4>デバッグの役割</h4><ol><li><b>不具合の原因を見つける</b>：エラーの原因は、エラーが出た行より前にあることが多い</li><li><b>処理の流れを理解する</b>：メソッドがどの順番で呼ばれるかを追える</li><li><b>値の変化を確認する</b>：どのタイミングで想定と違う値になったかがわかる</li><li><b>直したあとの確認</b>：本当に想定どおりの流れになったか、ほかに影響がないかを確かめる</li></ol><h4>使う場面</h4><ul><li>コンパイルは通るが、結果が違う（計算結果・条件分岐・保存内容など）</li><li>実行時エラー（NullPointerException など）が出た → 「なぜ null になったか」まで追う</li><li>ループの回数や、if のどちらに入っているかを確かめたい</li><li>他の人が書いたコードを理解したい</li><li><code>System.out.println()</code> だけでは追いきれない</li></ul><h4>用語とEclipseでできること</h4><div class=\"tbl\"><table><tr><th>用語</th><th>意味</th></tr><tr><td>ブレークポイント</td><td>処理を止める目印。「ここで止めて確認したい」行に置く</td></tr><tr><td>Debugモード</td><td>ブレークポイントで止まる実行方法</td></tr><tr><td>ステップ実行</td><td>1行ずつ処理を進める</td></tr><tr><td>ステップイン</td><td>メソッドの中に入る</td></tr><tr><td>ステップオーバー</td><td>次の行へ進む</td></tr><tr><td>ステップアウト</td><td>メソッドの外に出る</td></tr><tr><td>変数</td><td>止まった時点の値を確認できる（値を変えて試すこともできる）</td></tr><tr><td>コールスタック</td><td>どのメソッドから呼ばれてきたか</td></tr><tr><td>スタックトレース</td><td>エラーがどこで起きたかの記録</td></tr><tr><td>条件付きブレークポイント</td><td>特定の条件のときだけ止める</td></tr></table></div>"}, {"id": "java2-05", "page": "Java 応用編", "cat": "java", "ch": 5, "title": "Spring Boot・MVC・DI", "summary": "MVC（Model-View-Controller） ＝アプリの役割を分けて整理する設計パターン。読みやすく、直しやすく、保守しやすくなる。画面を持つWebアプリ（一覧表示・登録フォーム・検索・管理画面など）で使う。", "snippet": "@SpringBootApplication                       // 自動設定を有効にする（起動クラス）", "date": "2026-10-28", "min": 4, "html": "<h4>Spring Boot とは</h4><ul><li>Spring Framework をもとにした、<b>シンプルで素早く</b>アプリを作れるフレームワーク</li><li>昔は XML の設定がたくさん必要だったが、アノテーションと設定ファイルで済む</li><li>現場では、画面表示・DB連携・フォームの値の受け取り・業務ロジック・API連携などを作れることが求められ、そのための代表的な技術</li></ul><h4>Spring Boot の特徴</h4><ul><li><b>自動設定</b>：必要な設定を依存関係から自動でやってくれる</li><li><b>組み込みサーバー</b>：Tomcat入りで単体起動できる（war を外部サーバーに置かなくていい）</li><li><b>スターター</b>：<code>spring-boot-starter-web</code> などでまとめて導入</li><li><b>設定ファイル</b>：<code>application.yml</code> で一元管理</li></ul><h4>よく一緒に使う技術</h4><div class=\"tbl\"><table><tr><th>技術</th><th>役割</th></tr><tr><td>Thymeleaf</td><td>HTMLにデータを埋め込んで画面を表示</td></tr><tr><td>Spring Data JPA</td><td>Javaからかんたんに DB を操作</td></tr><tr><td>MyBatis</td><td>SQL を自分で書いて DB を操作</td></tr><tr><td>Validation</td><td>入力値のチェック</td></tr><tr><td>Lombok</td><td>getter / setter などの決まった書き方を省略</td></tr><tr><td>PostgreSQL / MySQL / Oracle</td><td>データを保存するデータベース</td></tr><tr><td>REST API</td><td>システムどうしでデータをやり取りする仕組み</td></tr></table></div><h4>プロジェクトの作り方と基本の形</h4><ul><li>Spring Initializr（<a href=\"http://start.spring.io\" target=\"_blank\" rel=\"noopener\">start.spring.io</a>）や、STS・IntelliJ IDEA のテンプレートで作る</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>@SpringBootApplication                       // 自動設定を有効にする（起動クラス）\npublic class MyApp {\n    public static void main(String[] args) {\n        SpringApplication.run(MyApp.class, args);\n    }\n}\n\n@RestController\npublic class MyController {\n    @GetMapping(&quot;/hello&quot;)                    // GET /hello で呼ばれる\n    public String hello() {\n        return &quot;Hello, Spring Boot!&quot;;\n    }\n}</code></pre></div><h4>MVC とは</h4><p><b>MVC（Model-View-Controller）</b>＝アプリの役割を分けて整理する設計パターン。読みやすく、直しやすく、保守しやすくなる。画面を持つWebアプリ（一覧表示・登録フォーム・検索・管理画面など）で使う。</p><div class=\"co co-green\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p>一言でいうと「<b>責任を分けて、変更に強くする</b>」。全部を1か所に書くと、どこに何があるかわからない・修正の影響が大きい・テストしにくい・分担しにくい・同じ処理が重複する、という問題が起きる。</p></div></div><h4>層の役割（MVC＋層構造）</h4><div class=\"tbl\"><table><tr><th>層</th><th>役割</th></tr><tr><td class=\"c-blue\">Controller</td><td>リクエストを受け取る・画面を選ぶ</td></tr><tr><td class=\"c-green\">Service</td><td>業務ロジック</td></tr><tr><td class=\"c-yellow\">Repository</td><td>DBアクセス</td></tr><tr><td class=\"c-orange\">Entity</td><td>テーブルに対応するデータ</td></tr><tr><td class=\"c-pink\">View</td><td>HTML画面（Thymeleaf）</td></tr></table></div><h4>リクエストの流れ</h4><div class=\"code\"><div class=\"code-head\"><span>txt</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>ブラウザ\n  ↓ HTTPリクエスト（GET /customers）\nController（@GetMapping）\n  ↓ 処理を頼む\nService（業務ロジック）\n  ↓ データを頼む\nRepository（DB問い合わせ）\n  ↓ Entity の List\nService → Controller\n  ↓ Model にデータを入れて、View 名を返す\nView（Thymeleaf テンプレート）\n  ↓ HTML を作る\nブラウザ</code></pre></div><h4>DI（依存性注入）</h4><div class=\"co co-green\"><span class=\"co-i\">☕</span><div class=\"co-b\"><p><b>DI</b>＝「使う側」と「作る側」を分けること。使うオブジェクトを自分で <code>new</code> せず、外から渡してもらう。コーヒーを豆から自分で作らず、お店で<b>受け取る</b>イメージ。</p></div></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// DIなし：自分で作る（Controller が Service に強く依存）\nclass Controller {\n    private Service service = new Service();\n}\n\n// DIあり：コンストラクタで受け取る（コンストラクタインジェクション）\nclass Controller {\n    private final Service service;\n    public Controller(Service service) {\n        this.service = service;\n    }\n}</code></pre></div><div class=\"tbl\"><table><tr><th>DIなしの問題</th><th>内容</th></tr><tr><td>密結合</td><td>Service を変えると Controller も影響を受ける。差し替えできない</td></tr><tr><td>テストしにくい</td><td>テスト用の Service に差し替えられない</td></tr><tr><td>再利用しにくい</td><td>特定の Service に縛られる</td></tr></table></div><ul><li>コンストラクタインジェクションのよいところ：必ずセットされる／<code>final</code> にできて安全／何に依存しているかが一目でわかる</li></ul><div class=\"tbl\"><table><tr><th>用語</th><th>意味</th></tr><tr><td>IoC</td><td>生成・管理を外に任せる<b>考え方</b></td></tr><tr><td>DI</td><td>その<b>具体的な方法</b></td></tr></table></div>"}, {"id": "java2-06", "page": "Java 応用編", "cat": "java", "ch": 6, "title": "JPA・Entity・Spring Data JPA・トランザクション", "summary": "ORM ＝Javaのオブジェクトと DB のテーブルを対応づける考え方。テーブルの1行を Java のオブジェクトとして扱える。Spring Boot では主に Repository 層 で使う。役割は「Java オブジェクトと DB の橋", "snippet": "import jakarta.persistence.*;", "date": "2026-10-28", "min": 10, "html": "<h4>ORM・JPA の関係</h4><div class=\"co co-yellow\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>ORM</b>＝Javaのオブジェクトと DB のテーブルを対応づける考え方。テーブルの1行を Java のオブジェクトとして扱える。Spring Boot では主に <b>Repository 層</b>で使う。役割は「Java オブジェクトと DB の橋渡し」。</p></div></div><div class=\"tbl\"><table><tr><th>名前</th><th>正体</th></tr><tr><td>ORM</td><td>オブジェクトとテーブルを対応づける<b>考え方</b></td></tr><tr><td>JPA</td><td>そのための<b>標準仕様</b>（ルール。実装そのものではない）</td></tr><tr><td>Hibernate</td><td>JPAの<b>実装</b>（Spring Boot でよく使う）</td></tr><tr><td>Spring Data JPA</td><td>JPAを<b>もっと楽に</b>使えるSpringの仕組み</td></tr></table></div><div class=\"tbl\"><table><tr><th>Java</th><th>DB</th></tr><tr><td>User クラス</td><td>users テーブル</td></tr><tr><td>id フィールド</td><td>id カラム</td></tr><tr><td>User を保存 / 取得 / 変更して保存 / 削除</td><td>INSERT / SELECT / UPDATE / DELETE</td></tr></table></div><ul><li>会員・商品・予約・顧客管理のような <b>CRUD（登録・取得・更新・削除）</b>をする業務システムでよく使う</li></ul><h4>Entity</h4><p><b>Entity</b>＝DB のテーブルに対応する Java のクラス。テーブルの<b>1行</b>を1つのオブジェクトとして表す。</p><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>import jakarta.persistence.*;\n\n@Entity\n@Table(name = &quot;customers&quot;)\npublic class Customer {\n    @Id\n    @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n\n    @Column(name = &quot;customer_name&quot;, nullable = false, length = 100)\n    private String name;              // name フィールド → customer_name カラム\n\n    @Column(name = &quot;phone&quot;, length = 20)\n    private String phone;\n\n    @Column(name = &quot;address&quot;)\n    private String address;\n\n    public Customer() { }             // JPA 用の引数なしコンストラクタ\n    // 引数ありコンストラクタ・getter / setter\n}</code></pre></div><div class=\"tbl\"><table><tr><th>アノテーション</th><th>役割</th></tr><tr><td>@Entity</td><td>Entityとして登録</td></tr><tr><td>@Table</td><td>対応するテーブル名</td></tr><tr><td class=\"c-yellow\">@Id</td><td><b>主キー（特に重要）</b>。どのレコードか・新規か更新かを判断するのに使う</td></tr><tr><td>@GeneratedValue</td><td>主キーの自動採番</td></tr><tr><td>@Column</td><td>カラム名・制約</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// Entity なし：SQL と値を直接あつかう\nString sql = &quot;INSERT INTO customers (customer_name, phone, address) VALUES (?, ?, ?)&quot;;\nPreparedStatement ps = connection.prepareStatement(sql);\nps.setString(1, &quot;田中太郎&quot;);\nps.setString(2, &quot;090-1234-5678&quot;);\nps.setString(3, &quot;東京都&quot;);\nps.executeUpdate();\n\n// Entity あり：オブジェクトとしてあつかう（意図が読み取りやすい）\nCustomer customer = new Customer(&quot;田中太郎&quot;, &quot;090-1234-5678&quot;, &quot;東京都&quot;);\ncustomerRepository.save(customer);</code></pre></div><h4>Spring Data JPA（Repository）</h4><ul><li>JPA を使った基本の CRUD を、少ないコードで書けるようにする Spring の仕組み</li><li><b>Entity</b> は「どのデータか」、<b>Repository</b> は「どう DB 操作するか」の窓口</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public interface CustomerRepository extends JpaRepository&lt;Customer, Long&gt; {\n}   // JpaRepository&lt;Entity, 主キーの型&gt; を継承するだけ</code></pre></div><div class=\"tbl\"><table><tr><th>メソッド</th><th>意味</th></tr><tr><td>findAll()</td><td>全件取得</td></tr><tr><td>findById(id)</td><td>IDで1件取得</td></tr><tr><td>save(entity)</td><td>登録・更新</td></tr><tr><td>deleteById(id)</td><td>ID指定で削除</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>@Service\npublic class CustomerService {\n    private final CustomerRepository customerRepository;\n\n    public CustomerService(CustomerRepository customerRepository) {   // DI\n        this.customerRepository = customerRepository;\n    }\n\n    public List&lt;Customer&gt; findAll() { return customerRepository.findAll(); }\n\n    public Customer findById(Long id) {\n        return customerRepository.findById(id)\n                .orElseThrow(() -&gt; new RuntimeException(&quot;顧客が見つかりません ID:&quot; + id));\n    }\n\n    public Customer save(Customer customer) { return customerRepository.save(customer); }\n\n    public void delete(Long id) { customerRepository.deleteById(id); }\n}</code></pre></div><h4>トランザクション</h4><div class=\"co co-yellow\"><span class=\"co-i\">🔄</span><div class=\"co-b\"><p><b>トランザクション</b>＝複数の DB 操作を「ひとまとまり」として扱うこと。<b>全部成功（コミット）か、全部取り消し（ロールバック）か</b>。役割は「データの整合性を守ること」。</p></div></div><ul><li><b>コミット</b>：トランザクション内の変更を正式に確定する</li><li><b>ロールバック</b>：途中で問題が起きたら、それまでの変更を取り消して元に戻す</li><li>使う場面：注文と注文明細の登録、注文登録と在庫更新、複数テーブルの更新、振込やポイント付与など</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>@Transactional\npublic void createOrder(Order order, List&lt;OrderDetail&gt; details) {\n    orderRepository.save(order);\n    for (OrderDetail d : details) {\n        orderDetailRepository.save(d);   // 途中で失敗したら全部元に戻る\n    }\n}</code></pre></div><div class=\"tbl\"><table><tr><th>タイミング</th><th>動き</th></tr><tr><td>メソッド開始</td><td>トランザクション開始</td></tr><tr><td>メソッド内の DB 操作</td><td>同じトランザクションの中で実行</td></tr><tr><td>正常に終わった</td><td>コミット（確定）</td></tr><tr><td>例外が起きた</td><td>ロールバック（取り消し）</td></tr></table></div><ul><li><code>@Transactional</code> がないと、途中で失敗したとき、先に保存できたデータだけが残ってしまう</li></ul><div class=\"co co-red\"><span class=\"co-i\">⚠️</span><div class=\"co-b\"><p>ロールバックされるのは基本的に <b>RuntimeException</b>（NullPointerException・IllegalArgumentException など）が発生したとき。</p></div></div><h4>application.yml</h4><div class=\"tbl\"><table><tr><th>項目</th><th>内容</th></tr><tr><td>読み込み</td><td>アプリ起動時に自動</td></tr><tr><td>書き方</td><td>YAML 形式（インデントで階層を表す）</td></tr><tr><td>場所</td><td><code>src/main/resources/application.yml</code></td></tr><tr><td>役割</td><td>DB 接続・ポート番号・JPA の動きなどを一元管理</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>yaml</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>server:\n  port: 8080                     # 起動ポート（デフォルト 8080）\n\nspring:\n  datasource:\n    url: jdbc:postgresql://localhost:5432/sample_db\n    username: postgres\n    password: postgres\n    driver-class-name: org.postgresql.Driver\n  jpa:\n    hibernate:\n      ddl-auto: validate         # 実務では validate か none\n    show-sql: true               # 発行された SQL をログに出す（開発時）\n    properties:\n      hibernate:\n        dialect: org.hibernate.dialect.PostgreSQLDialect\n        format_sql: true</code></pre></div><div class=\"tbl\"><table><tr><th>ddl-auto</th><th>意味</th><th>使いどころ</th></tr><tr><td class=\"c-red\">create</td><td>起動時にテーブルを作り直す（データ消える）</td><td>開発初期のみ</td></tr><tr><td class=\"c-yellow\">update</td><td>差分を自動更新</td><td>開発中</td></tr><tr><td class=\"c-green\">validate</td><td>Entityとテーブルが合っているか確認だけ</td><td>実務・本番</td></tr><tr><td class=\"c-gray\">none</td><td>何もしない</td><td>本番（DDLは手で管理）</td></tr></table></div><h4>DBにつなぐ流れ（例）</h4><ol><li>PostgreSQL で <code>sample_db</code> と <code>products</code> テーブルを作る（<code>psql -U postgres</code> → <code>CREATE DATABASE sample_db;</code> → <code>\\c sample_db</code>。psql があるかは <code>psql --version</code> で確認）</li><li><a href=\"http://start.spring.io\" target=\"_blank\" rel=\"noopener\">start.spring.io</a> でプロジェクト作成（Gradle - Groovy / Java 21 / Jar / Group <code>com.example</code> / Artifact <code>demo</code> / Spring Web・Spring Data JPA・PostgreSQL Driver・Thymeleaf）→ zip を Eclipse にインポート</li><li><code>application.yml</code> を設定（username / password は自分の PostgreSQL に合わせる）</li><li><code>entity/Product.java</code> と <code>repository/ProductRepository.java</code>（<code>JpaRepository&lt;Product, Long&gt;</code>）を作る</li><li><code>DemoApplication.java</code> を右クリック → Run As → Spring Boot App。<code>Started DemoApplication</code> が出れば成功</li></ol><div class=\"code\"><div class=\"code-head\"><span>sql</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>CREATE TABLE products (\n    product_id     BIGSERIAL PRIMARY KEY,\n    product_name   VARCHAR(100) NOT NULL,\n    unit_price     INTEGER NOT NULL,\n    stock_quantity INTEGER NOT NULL DEFAULT 0\n);\nINSERT INTO products (product_name, unit_price, stock_quantity) VALUES (&#x27;テスト商品A&#x27;, 1000, 10);</code></pre></div><div class=\"tbl\"><table><tr><th>エラー</th><th>確認するところ</th></tr><tr><td class=\"c-red\">Connection refused</td><td>PostgreSQLが起動しているか</td></tr><tr><td class=\"c-red\">password authentication failed</td><td>username / password</td></tr><tr><td class=\"c-red\">relation does not exist</td><td>テーブル名・カラム名</td></tr><tr><td class=\"c-red\">validateで起動失敗</td><td>EntityとDBカラムの対応</td></tr></table></div>"}, {"id": "java2-07", "page": "Java 応用編", "cat": "java", "ch": 7, "title": "Bean Validation（入力チェック）", "summary": "Bean Validation ＝フォームの入力値チェックを、 アノテーション を付けるだけで行う仕組み。", "snippet": "public class CustomerForm {", "date": "2026-10-28", "min": 2, "html": "<div class=\"co co-red\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>Bean Validation</b>＝フォームの入力値チェックを、<b>アノテーション</b>を付けるだけで行う仕組み。</p></div></div><div class=\"tbl\"><table><tr><th>アノテーション</th><th>チェック内容</th></tr><tr><td>@NotNull</td><td>null じゃない</td></tr><tr><td>@NotBlank</td><td>null・空文字・空白だけじゃない（String 向け）</td></tr><tr><td>@Size(min=, max=)</td><td>文字数の範囲</td></tr><tr><td>@Min(value) / @Max(value)</td><td>最小値以上・最大値以下</td></tr><tr><td>@Pattern(regexp=)</td><td>正規表現に一致</td></tr><tr><td>@Email</td><td>メール形式</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>public class CustomerForm {\n\n    @NotBlank(message = &quot;顧客名は必須です&quot;)\n    @Size(max = 100, message = &quot;顧客名は100文字以内で入力してください&quot;)\n    private String name;\n\n    @NotBlank(message = &quot;電話番号は必須です&quot;)\n    @Pattern(regexp = &quot;^[0-9-]{10,13}$&quot;, message = &quot;電話番号の形式が不正です&quot;)\n    private String phone;\n\n    // getter / setter\n}</code></pre></div><ul><li><code>message</code> で、エラーのときに表示する文を決められる</li><li>実務演習の CustomerForm では phone は「任意」なので @NotBlank は付けない（上は使い方を学ぶための例）</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>@PostMapping(&quot;/customers&quot;)\npublic String create(@Valid @ModelAttribute CustomerForm form,\n                     BindingResult bindingResult) {\n    if (bindingResult.hasErrors()) {\n        return &quot;customer/form&quot;;     // エラーなら登録画面に戻る\n    }\n    customerService.save(form);\n    return &quot;redirect:/customers&quot;;\n}</code></pre></div><ul><li><code>@Valid</code> を付けるとチェックが動き、結果は <code>BindingResult</code> に入る</li></ul>"}, {"id": "java2-08", "page": "Java 応用編", "cat": "java", "ch": 8, "title": "テスト（JUnit5 / Mockito）", "summary": "テスト ＝作ったプログラムが期待どおりに動くかを確認する作業。「動いているように見えても、本当に正しいとは限らない」ので必要。テストは最後のおまけではなく、 実装とセット で行う。", "snippet": "dependencies {", "date": "2026-10-28", "min": 5, "html": "<div class=\"co co-red\"><span class=\"co-i\">💡</span><div class=\"co-b\"><p><b>テスト</b>＝作ったプログラムが期待どおりに動くかを確認する作業。「動いているように見えても、本当に正しいとは限らない」ので必要。テストは最後のおまけではなく、<b>実装とセット</b>で行う。</p></div></div><h4>テストでわかること・よいこと</h4><ul><li>正しい結果が返るか／想定外の入力で壊れないか／修正でほかが壊れていないか</li><li>直したときにすぐ確認できる・仕様をコードで表せる・手動確認の手間が減る・安心して修正できる</li><li><b>自動化テスト</b>＝確認をコードで書いて、実行するだけで検証できるようにしたもの</li></ul><h4>テストの種類</h4><div class=\"tbl\"><table><tr><th>種類</th><th>対象</th><th>内容</th></tr><tr><td class=\"c-green\">単体テスト</td><td>1クラス・1メソッド（Service・ロジック）</td><td>「この入力なら、この結果」を小さな単位で確認</td></tr><tr><td class=\"c-yellow\">結合テスト</td><td>Controller〜DB</td><td>複数の層をつないで、連携して正しく動くか</td></tr><tr><td class=\"c-orange\">E2Eテスト</td><td>画面操作を含む全体</td><td>画面を開く→入力→登録→一覧に反映、を利用者目線で確認（コストが高い）</td></tr></table></div><ul><li>開発の流れ：仕様を理解 → 実装 → テスト → 直す → もう一度テスト</li><li>初めはまず単体テストと結合テストを理解する</li></ul><h4>テストケースの観点</h4><div class=\"tbl\"><table><tr><th>観点</th><th>内容</th><th>例</th></tr><tr><td>正常系</td><td>期待どおりの入力で正しく動く</td><td>有効なIDで顧客が取れる</td></tr><tr><td>異常系</td><td>不正な入力・例外のケース</td><td>ないIDで例外が出る</td></tr><tr><td>境界値</td><td>上限・下限・0・null など</td><td>価格が 0、最大値、null</td></tr><tr><td>副作用</td><td>期待した処理が呼ばれたか</td><td>save が1回呼ばれたか</td></tr></table></div><h4>JUnit5</h4><ul><li>Java で単体テストを書くための標準のフレームワーク</li><li>手動確認と違い、コマンド一発で全パターンを検証でき、デグレ（壊れた箇所）にすぐ気づける。テストコード自体が説明書にもなる</li></ul><div class=\"tbl\"><table><tr><th>モジュール</th><th>役割</th></tr><tr><td>JUnit Jupiter</td><td>テストを書くための API（@Test・assertEquals など）。<b>ふだん意識するのはこれだけ</b></td></tr><tr><td>JUnit Platform</td><td>テストを実行する基盤</td></tr><tr><td>JUnit Vintage</td><td>古い JUnit4 のテストを動かすためのもの</td></tr></table></div><div class=\"code\"><div class=\"code-head\"><span>groovy</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>// build.gradle（spring-boot-starter-test を入れるだけで JUnit5 と Mockito が使える）\ndependencies {\n    testImplementation &#x27;org.springframework.boot:spring-boot-starter-test&#x27;\n}\ntasks.named(&#x27;test&#x27;) {\n    useJUnitPlatform()   // JUnit5 を使うために必要\n}</code></pre></div><ul><li>テストコードは <code>src/test/java/</code> の下に、本体と<b>同じパッケージ構成</b>で置く（<code>CalculatorService.java</code> → <code>CalculatorServiceTest.java</code>）</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>import org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass CalculatorServiceTest {\n    @Test                                   // これを付けたメソッドがテストとして動く\n    void 三と四を足すと七になる() {          // 内容がわかる名前にする\n        CalculatorService service = new CalculatorService();  // Arrange（準備）\n        int result = service.add(3, 4);                       // Act（実行）\n        assertEquals(7, result);                              // Assert（検証）\n    }\n}</code></pre></div><div class=\"tbl\"><table><tr><th>実行方法</th><th>手順</th></tr><tr><td>IDE から</td><td>テストクラスやメソッドを右クリック →「Run」</td></tr><tr><td>Gradle から</td><td>ターミナルで <code>./gradlew test</code></td></tr><tr><td>結果の確認</td><td><code>build/reports/tests/test/index.html</code> をブラウザで開く</td></tr></table></div><h4>Mockito（Repositoryを偽物にする）</h4><ul><li>テスト対象が使うオブジェクト（Repository など）を<b>偽物（モック）</b>に置き換える</li><li>DB につながずに、Service の業務ロジックだけを確認できる</li></ul><div class=\"code\"><div class=\"code-head\"><span>java</span><button type=\"button\" class=\"copy\">写経する</button></div><pre><code>@ExtendWith(MockitoExtension.class)\nclass CustomerServiceTest {\n    @Mock\n    private CustomerRepository customerRepository;   // 偽物\n\n    @InjectMocks\n    private CustomerService customerService;         // テスト対象（偽物が自動で入る）\n\n    @Test\n    void 全件取得するとリポジトリから取得した件数が返る() {\n        when(customerRepository.findAll())\n            .thenReturn(List.of(new Customer(1L, &quot;田中&quot;), new Customer(2L, &quot;鈴木&quot;)));\n\n        List&lt;Customer&gt; result = customerService.findAll();\n\n        assertEquals(2, result.size());\n        verify(customerRepository, times(1)).findAll();  // 1回呼ばれたか\n    }\n\n    @Test\n    void 存在しないIDで検索するとRuntimeExceptionが発生する() {\n        when(customerRepository.findById(999L)).thenReturn(Optional.empty());\n\n        assertThrows(RuntimeException.class, () -&gt; {\n            customerService.findById(999L);\n        });\n    }\n}</code></pre></div><div class=\"tbl\"><table><tr><th>書き方</th><th>意味</th></tr><tr><td>when(...).thenReturn(...)</td><td>偽物の返す値を決める</td></tr><tr><td>verify(...)</td><td>呼ばれた回数を確認</td></tr><tr><td>assertEquals(期待値, 実際)</td><td>値が同じか確認</td></tr><tr><td>assertThrows(...)</td><td>例外が出ることを確認</td></tr></table></div>"}];
